WoWFQ[14022] = { t = "Pilgrim's Bounty", d = "نمی‌خواهی با ما جشن Pilgrim's Bounty را برگزاری، <name>؟ وقت آن است که به سفرهایت و اقبال نیکت بیندیشی و در کنار دوستان، از خوراک فراوان و قصه‌ها لذت ببری.\nمی‌توانی نزدیک شهرهای بزرگ با نشستن پشت میز پرنعمت و سرو کردن خوراکی‌های آنجا، در ضیافت‌های باشکوه Pilgrim's Bounty شرکت کنی.\nاگر دوست داری پختن خوراکی‌های سنتی Pilgrim's Bounty را یاد بگیری، سراغ Gregory Tabor برو. او را دقیقا بیرون از دروازه‌های Stormwind پیدا خواهی کرد.", o = { "کمی بیرون از دروازه‌های شهر Stormwind با Gregory Tabor گفتگو کن." }, c = "اگر می‌خواهی پختن خوراکی‌های Pilgrim's Bounty را یاد بگیری، من می‌توانم کمکت کنم. اگر هنوز آشپز نشده‌ای، فقط کافی است آموزش ببینی و خیلی زود دست به دیگ می‌شوی!" }
WoWFQ[14036] = { t = "Pilgrim's Bounty", d = "آمده‌ای که با ما جشن Pilgrim's Bounty را برگزاری؟ روزگاری وقتِ اندیشیدن به سفرها و اقبال نیک، در کنار سفره‌ای با دوستان بود. بسیاری هنوز این جشن را برگزار می‌کنند.\nمی‌توانی نزدیک شهرهای بزرگ با نشستن پشت میز پرنعمت و سرو کردن خوراکی‌های آنجا، در ضیافت‌های Pilgrim's Bounty شرکت کنی.\nاگر دوست داری پختن خوراکی‌های سنتی Pilgrim's Bounty را یاد بگیری، سراغ Miles Standish برو. او را در حیاط بالای Undercity پیدا خواهی کرد.", o = { "در حیاط بالای Undercity با Miles Standish گفتگو کن." }, c = "اگر می‌خواهی پختن خوراکی‌های Pilgrim's Bounty را یاد بگیری، من می‌توانم کمکت کنم. اگر هنوز آشپز نشده‌ای، فقط کافی است آموزش ببینی و خیلی زود دست به دیگ می‌شوی." }
WoWFQ[76308] = { t = "Trial of Style", d = "خب، این ظاهرت قطعا ظاهرِ... جالبی است، <class>.\nمن؟ یکجانبه‌نگر؟ البته که نه. با این حال کنجکاوم بقیه چه فکری درباره‌اش می‌کنند.\nبهتر است با Transmogrifier آن‌طرف حرف بزنی و در Trial of Style شرکت کنی.\nببینیم نظر عامه مردم درباره انتخاب پوششت چیست.", o = { "برای ورود و کامل کردن Trial of Style با یک Transmogrifier صحبت کن.", "با یک Transmogrifier صحبت کن", "Trial of Style را کامل کن" }, p = "اوف، چه حوصله‌سررفته.\nTrial of Style را دیگر کامل کردی؟", c = "تا حدی تأثیرگذار بود.\nتا حدی.\nخب برو دیگر. از دیدنت خسته شدم." }
WoWFQ[76361] = { t = "هفته مد", d = "آه، Trial of Style از راه رسیده، <class>.\nلباس‌ها، خلاقیت و شکوه این مراسم واقعا دیدنی‌اند.\nبرای آشنایی بیشتر با این رویداد با یک Trial of Style Envoy صحبت کن.\nیک هشدار: کنار آمدن با آن فرستاده‌ها می‌تواند... دشوار باشد.", o = { "با یک Trial of Style Envoy صحبت کن." }, c = "واقعا فکر می‌کنی برای Trial of Style آماده‌ای؟\nبا آن لباس؟" }
WoWFQ[82672] = { t = "یک دعوت به‌موقع دیگر", d = "اژدهایان برنزی درست بیرون از Caverns of Time در Tanaris جشنی برپا کرده‌اند!\nفعالیت‌های تازه‌ای از هر نوع برای شرکت برپاست؛ هم به آنچه طی این سال‌ها گذشته احترام می‌گذارند و هم یادش را زنده نگه می‌دارند.\nبه Tanaris برو و در جشن‌ها شرکت کن.", o = { "به جشن در Tanaris، بیرون از Caverns of Time سر بزن." }, c = "خوش آمدی!\nباز هم به آن زمانِ خاص از سال رسیده‌ایم؛ زمانی که اژدهایان برنزی همه آنچه طی سال‌ها گذشته را جشن می‌گیرند.\nتو، <name>، مهمان بسیار گرامی ما هستی!" }
WoWFQ[84371] = { t = "Lorewalking: تیغه و کاهنه اعظم", d = "Xal'atath، پیام‌آور Void، دشمنی حیله‌گر و خطرناک است. همیشه با دقت مراقب بوده که حضورش فقط برای عده‌ای بسیار اندک آشکار شود.\nنخستین بار در سومین یورش Legion به Azeroth با او آشنا شدیم، اما زمزمه‌ها می‌گویند او بسیار، بسیار پیش از آن هم وجود داشته است.\nاین قصه‌ای است از قدرت، تاریکی و فریب. همراهم شو تا سرگذشت مرموز Xal'atath را برایت بگویم.", o = { "برای آشنایی با سرگذشت Xal'atath از راهنمایی Cho پیروی کن.", "برای شنیدن داستان یورش Legion به Lorewalker Cho گوش کن", "برای آگاهی از سفر کاهنه اعظم با Lorewalker Cho صحبت کن", "سفر کاهنه اعظم را دنبال کن و Xal'atath را به دست بیاور", "Xal'atath, Blade of the Black Empire را به دست بیاور" }, c = "Xal'atath سلاحی نیرومند بود و... موجودی بسیار پرحرف." }
WoWFQ[84779] = { t = "Lorewalking: بازی تیغه", d = "هرچند Xal'atath اکنون تنها تیغه‌ای کم‌قدرت بود، دست از کار نکشید. پس از یورش Legion، تنش‌ها میان Horde و Alliance به جنگ چهارم منفجر شد.\nXal'atath از نیروهای گوناگون درگیر در جنگ بهره گرفت تا در بازی‌ای بزرگ قدرتش را بازگرداند...", o = { "برای شنیدن داستان Xal'atath در جنگ چهارم به Lorewalker Cho گوش کن.", "برای آگاهی از بازی Xal'atath به Lorewalker Cho گوش کن" }, c = "باور دارم اطلاعاتی که من و همکاران Lorewalker ام یافته‌ایم کاملا تازه است. از اهمیتش مطمئن نیستم، اما شاید بتوانی خودت قضاوت کنی." }
WoWFQ[84782] = { t = "Lorewalking: گذشته تیغه", d = "سال‌ها پیش، لوح سنگی‌ای از Stormsong Valley راهش به کتابخانه‌ام کشید.\nشکستن رمز و ترجمه تکه‌های نوشته‌های حکاکی‌شده بر آن، سال‌ها وقت گرفت.\nآنچه را کنار هم چیده‌ایم برایت می‌گویم؛ قصه‌ای از خیانتی دیگر...", o = { "برای شنیدن داستان Xal'atath در Ny'alotha به Cho گوش کن.", "برای آگاهی از گذشته دور Xal'atath به Lorewalker Cho گوش کن" }, c = "تو برگزیده شده‌ای، هرچند اندک‌ارزشی. شکرگزار باش." }
WoWFQ[84789] = { t = "Lorewalking: سقوط تیغه", d = "آن‌ها آماده‌اند.\nLordها Xal'atath را در قلعه نگه داشته‌اند. تو سنگریزه‌ای هستی که ریزش بهمنِ قدرتشان را آغاز می‌کند؛ برای پایان دادن به Xal'atath.\nبرو. به آن‌ها بپیوند.", o = { "با Xal'atath روبه‌رو شو.", "به Annex of Prophecy فرود بیا", "Xal'atath را شکست بده" }, c = "آخرین سخنان Xal'atath با N'Zoth چه معنایی داشت؟ آیا همکاری آینده‌شان را پیش‌بینی کرده بود؟\nاز همان ابتدا نقشه‌اش همین بود؟" }
WoWFQ[85027] = { t = "Lorewalking: Protectorate", d = "مدت‌ها درباره Etherealها کنجکاو بوده‌ام؛ کسانی که وقتی مه‌ها کنار رفتند، نخستین بار به Pandaria آمدند. گروهی مرموز که از گفتن تاریخ‌شان سرباز می‌زنند... اما شاید من در پرس‌وجو از بیشترها سرسخت‌تر باشم.\nخب! این غریبه‌ها کیستند؟ از تاریخ‌شان چه می‌دانیم؟ به نظر می‌رسد باید خودمان قطعه‌ها را کنار هم بگذاریم.\nاما قصه ما از Outland آغاز می‌شود؛ جایی که قهرمانی در Netherstorm به گروهی از Etherealها پیوست تا در راهشان یاری‌شان کند.", o = { "برای آشنایی با Etherealها از راهنمایی Cho پیروی کن.", "برای آشنایی با Etherealها با Lorewalker Cho صحبت کن", "برای آشنایی با Protectorate با Lorewalker Cho صحبت کن", "به Protectorate در برابر Nexus-King Salhadaar کمک کن", "برای آشنایی با Dimensius با Lorewalker Cho صحبت کن", "به Professor Dabiri کمک کن برای حمله به Dimensius آماده شود", "به نیروهای Protectorate در برابر Dimensius the All-Devouring کمک کن" }, c = "با شکست Salhadaar و Dimensius، به نظر می‌رسید سرانجام بزرگ‌ترین مشکلات پیش روی Etherealها حل شده بود." }
WoWFQ[85028] = { t = "Lorewalking: Brokerها", d = "Etherealها بی‌گمان بسیار شگفت‌انگیزند، اما در پژوهش‌هایم با نژاد دیگری از موجودات روبه‌رو شدم که شباهت‌های زیادی با آن‌ها دارد. به نظرم بهتر است از آن‌ها هم بگوییم--Brokerها.\nآن‌ها هم طبعی کوچ‌نشین دارند، هم شوق جمع‌آوری عتیقه‌های نایاب و عجیب، و هم علاقه‌ای وافر به تجارت.\nبا این حال Brokerها در Azeroth زندگی نمی‌کنند. آن‌ها در Shadowlands ساکن‌اند... سرزمین مرگ.", o = { "برای آشنایی با Brokerها از راهنمایی Cho پیروی کن.", "درباره Brokerها با Lorewalker Cho صحبت کن", "با Host Ta'rela گفتگو کن", "به Al'dalil کمک کن از نقشه‌های Cartel So باخبر شود", "درباره Night Market با Cho صحبت کن", "در Night Market با Ta'nla گفتگو کن", "[DNT] Kill Credit: Exit Area Trigger را بکش", "به Ta'oku کمک کن محموله‌اش را بازپس گیرد", "با Mishi سوار شو و به Tazavesh Ferry برو", "سوار بارکش شو و به Tazavesh برو", "Al'Dalil: هنوز نرسیده‌ایم؟", "کوشش کن وارد Tazavesh شوی", "درباره Ve'nari از Lorewalker Cho بپرس", "دستورالعمل‌های Ve'nari را دنبال کن", "با Mishi سوار شو و به Ve'nari's Refuge برو", "به Broker یعنی Ve'nari کمک کن", "از Lorewalker Cho بابت بینشش تشکر کن" }, c = "واقعا شگفت‌انگیز است که این دو نژاد چه شباهت‌هایی به هم دارند؛ مگر نه؟" }
WoWFQ[85029] = { t = "Lorewalking: Locus-Walker", d = "هرچند Protectorate در Outland شاید Dimensius و Salhadaar را متوقف کرده بود، Ethereum باقی ماند. و همان‌طور که Salhadaar آرزو داشت، بر آن شدند که Void را در آغوش بگیرند.\nنه فقط در آغوش گرفتن--بلکه تبدیل شدن به آن. Void آن‌ها را به سایه‌هایی از خودشان بدل کرد؛ آکنده از شوق بی‌پایان قدرت.\nاما یک Ethereal بود، Locus-Walker، که می‌خواست Void را برای اهدافی نوع‌دوستانه‌تر به کار گیرد. سرگذشت او با الفی از دنیای ما--Alleria Windrunner--گره خورده است.", o = { "برای آشنایی با Etherealهای Void از راهنمایی Cho پیروی کن.", "برای آشنایی با Etherealهای Void با Lorewalker Cho صحبت کن", "به Locus-Walker کمک کن به Alleria یاد بدهد بر Void مسلط شود" }, c = "نیت Locus-Walker بی‌گمان خوب به نظر می‌رسد، هرچند کسانی هستند که تا امروز هم به او و هم به Alleria شک دارند." }
WoWFQ[85035] = { t = "Locus-Walker، Ranger Telogrus", d = "بابت قطع کردن گفتگویتان عذرخواهی می‌کنم، فانی. اما همین گفتگوی شما بود که نظر Ve'nari را جلب کرد. او بسیار می‌شنود--به‌ویژه وقتی پای نامش در میان باشد.\nمرا با شی‌ای فرستاده‌اند که باید به Locus-Walker برسانی. او Ethereali است که در Telogrus Rift زندگی می‌کند. به گمانم \"void elf\"های دنیای تو هم همان‌جا ساکن‌اند.\nلازم نیست سفری در پیش بگیری. من به مقصدی که باید بروی درگاه باز می‌کنم. آیا در این کار به او کمک می‌کنی؟", o = { "وسیله Ve'nari را در Telogrus Rift به Locus-Walker برسان.", "درگاه را باز کن", "با درگاه به Telogrus Rift برو", "قاتل‌های Ethereal را بکش (6)" }, p = "Shadowguard چرا به این‌جا، از همه جا، آمده‌اند؟", c = "مرسوله‌ای برای من؟ بسیار عجیب است. بسیار خب، پس به من بده... و از کمکت برای دفع Shadowguard ممنونم." }
WoWFQ[85036] = { t = "آمدم، دیدم، Ve'nari", d = "یک Broker تو را با این وسیله فرستاده؟ و آن هم Ve'nari بود که او را فرستاده؟\nاین چندان خوش‌یمن نیست.", o = { "گفتگو با Locus-Walker را از نزدیک ببین.", "شاهد گفتگوی Ve'nari و Locus-Walker باش", "نزد Lorewalker Cho بازگرد", "برای خروج آماده شو" }, p = "چیزهای زیادی برای فکر کردن دارم، دوست من--و چیزهای زیادی هم برای افزودن به پژوهش‌هایم!", c = "پس Locus-Walker و Ve'nari همدیگر را می‌شناختند؟ مطمئنی، دوست من؟\nبه نظر می‌رسد پژوهش‌هایم بی‌پایه و اساس نبوده پس.\nمن می‌خواستم دانش تو را درباره Etherealها گسترش بدهم، اما تو دامنه دانش مرا گسترش دادی! از تو ممنونم." }
WoWFQ[86621] = { t = "Magister سرگردان", d = "Magister Umbric--هیچ‌کس پس از Mother به اندازه او بر Void مسلط نیست. اگر کسی بتواند در آن طوفانِ در آسمان به ما کمک کند، اوست که می‌تواند... البته اگر ببخشد که دیگران از همان اول حرفش را نشنیدند.\nدست‌کم Lor'themar عقل را پذیرفت. بدون Umbric هیچ راهی نداریم که جنگ را به Xal'atath ببریم.\nنیروهایی که Voidstorm را مهار کرده‌اند تنها تا زمانی دوام می‌آورند. باید شتاب کنیم.", o = { "Arator را همراهی کن تا در Tranquillien با Magister Umbric دیدار کنید.", "در جاده Tranquillien با Arator دیدار کن", "اندکی بمان و به Orweyna گوش کن", "Despoiled Notes را پیدا کن", "در Tranquillien با Umbric دیدار کن" }, p = "آنچه دست داری چیست؟", c = "<Umbric looks stricken.>\nاین خبری نبود که انتظارش را داشتم. نه!" }
WoWFQ[86622] = { t = "قراری تصادفی", d = "خودم هم شایعه‌های عجیبی شنیده‌ام. حوادثی ناآشنا در جنوب--اما در شرق و غرب و شمال هم. به نظر می‌رسد Tranquillien احاطه شده است.\nچون این‌قدر مصمم به پیگیری تحقیقت هستی، می‌شود لطفا یک چیزی را هم برای من بررسی کنی؟\nگزارش مهمی از یکی از دیده‌بان‌هایم لازم دارم. تو برو سراغش، من هم بقیه شهر را از نظر می‌گذرانم.", o = { "نزدیک Tranquillien با دیده‌بان Lord Antenorian دیدار کن.", "به قرار دیده‌بان Lord Antenorian برو", "Cultist Ambusher را بکش", "Suspicious Missive را به دست بیاور" }, p = "بگذار ریشه این ماجرا را پیدا کنیم.", c = "بدبخت--به نظر می‌رسد آن فرقه همه‌جا گوش دارد!" }
WoWFQ[86623] = { t = "درخواستی به Void", d = "Kasiea... هرچه یافته بودی، جانت را برایش از دست دادی.\nنمی‌گذارم زحماتش بر باد برود.\nاینجا چیزی برای یافتن هست، $p. چند مکان در فهرست نوشته شده. برویم سراغشان و چندی از این اصول را بیازماییم. شاید فرمول‌ها ناقص باشند، اما شاید بفهمیم او دنبال چه بود.\nحتما چیزی مهم بوده.", o = { "در بیرون Tranquillien به Umbric در آزمودن اصول Void کمک کن.", "مراسم شرقی را برگزار کن", "مراسم غربی را برگزار کن", "مراسم شمالی را برگزار کن" }, c = "متوجه نمی‌شوم. با همه این اطلاعات چه می‌کرد؟" }
WoWFQ[86624] = { t = "توضیحی منطقی", d = "همه این ماجرا برایم درست به نظر نمی‌رسد. Umbric می‌تواند سراغ دفترچه برود، اما گمان می‌کنم چیز دیگری هم در جریان است.\nبد نمی‌شود بپرسیم ببینیم کسی در Tranquillien چیز عجیبی شنیده یا نه. من شمال شهر را می‌گیرم و تو جنوب را.\nو... با احتیاط عمل کن، دوست من. فعلا بهتر است کسی را نگران نکنیم.", o = { "از اهالی Tranquillien بازجویی کن و هر سرنخی را یادداشت کن.", "از اهالی شهر بازجویی کن (4)", "Guard Captain Leonic را بکش", "Ranger Belonis را بکش", "Matron Narsilla را بکش", "Quartermaster Lymel را بکش", "در Tranquillien سرنخ پیدا کن", "Strange Shipment را پیدا کن (7)", "Vandalized Cart را پیدا کن (7)", "Matron Propaganda را نابود کن (10)", "Quartermaster Propaganda را نابود کن (10)", "Innkeeper Propaganda را نابود کن (10)", "Guard Propaganda را نابود کن (10)", "Ranger Propaganda را نابود کن (10)", "Sermon Book را پیدا کن (7)", "Guard Schedules را پیدا کن (7)", "Scout Reports را پیدا کن (7)", "با Innkeeper Kalarin گفتگو کن", "دفترچه Kasiea را پیدا کن", "Torn-Out Page را پیدا کن", "Torn-Out Page را پیدا کن", "Torn-Out Page را پیدا کن" }, p = "تحقیقاتت چطور پیش می‌رود؟", c = "به نظر می‌رسد Tranquillien بسیار بیشتر از آن چیزی است که در دید اول می‌نماید." }
WoWFQ[86626] = { t = "آزمایشگاه غارت‌شده", d = "یادداشت‌هایم، پژوهش‌هایم... نباید تنها می‌گذاشتمشان.\nتازه داشتم به رمز Voidstorm پی می‌بردم! هر چه آموخته بودم، فرقه‌گرایان از چنگم ربودند... مگر همه این مدت مرا زیر نظر داشتند؟ منتظر می‌ماندند تا پشت کنم؟\nنمی‌گذارم این ماجرا متوقفم کند. نمی‌توانسته باشند همه چیز را نابود کنند. شاید همین‌ها برای نجات بخشی از آن کافی باشد.", o = { "در آزمایشگاه غارت‌شده Umbric بگرد و هر پژوهش قابل‌نجاتی را بیاب.", "Void Sample را پیدا کن (3)", "Void Sample را بکش", "Void Sample را بکش (2)", "Papers را پیدا کن (99)", "Forgotten Pendant را بررسی کن" }, c = "Twilight's Blade--Antenorian، تو چه کرده‌ای!" }
WoWFQ[86632] = { t = "نبرد برای Tranquillien", d = "Twilight's Blade؟ حالا که مأمورشان لو رفته، حمله در روشنای روز... خودشان خواهند فهمید چه اشتباه بزرگی کرده‌اند.\nخائنان را و موجوداتی را که احضار کرده‌اند بکش. تندیس‌ها و آذوقه‌شان را نابود کن.\nعقب‌نشینی را برایشان گران تمام کن، <name>.", o = { "Tranquillien را از چنگ Twilight's Blade آزاد کن.", "Twilight's Blade را عقب بران", "فرقه‌گرایان Twilight's Blade را بکش", "Voidlingها را بکش (34)", "Obeliskها را نابود کن (20)", "آذوقه‌ها را نابود کن (34)", "تبلیغات را نابود کن (34)" }, p = "امیدواریم آنقدر باقی مانده باشد که بتوان دوباره ساخت.", c = "می‌ترسم این ماجرا هنوز خیلی مانده..." }
WoWFQ[86633] = { t = "فهم Void", d = "شاید یادداشت‌های Kasiea برای همیشه گم شده باشند، اما باید بکوشیم و بدون مقدمه راهی بسازیم. یک مراسم دیگر برای آزمودن دارم؛ آخرین مراسم.\nاگر این جواب ندهد، آن‌گاه پاسخ‌ها در Deatholme است، قلب Twilight's Blade. اما اول...", o = { "در محله مراسم در Windrunner Village به Umbric بپیوند. آنجا 4 Void Shard جمع کن و به مرکز Void بازگردان.", "در محل مراسم به Umbric بپیوند", "اندکی بمان و به Arator گوش کن", "Void Shardها را جذب کن (4)", "نخستین Void Shard را جذب کن", "دومین Void Shard را جذب کن", "سومین Void Shard را جذب کن", "آخرین Void Shard را جذب کن" }, p = "نمی‌توانم تا ابد این را نگه دارم--کمی عجله ممنون می‌شود!", c = "نه! نه... آن‌قدر نزدیک بودم.\n<Umbric خودش را بازیابی می‌کند--نمونه‌ای تمام‌عیار از تمرکز.>\nپس مقصد ما Deatholme است. پایگاه Twilight's Blade." }
WoWFQ[86634] = { t = "گذشته نگهبانی می‌دهد", d = "به این سکوت اعتماد ندارم. بیایید دفاع‌ها را محکم‌تر کنیم. آن گولم‌های arcane کج‌وکوله دور و بر روستا را دیدی؟\nالان شاید زیاد به چشم نیایند، اما با کمی تعمیر سریع خیلی زود سرپا می‌شوند. هم برای نگهبانی خوب‌اند، هم برای پیدا کردن هر ماری که در علف‌ها کمین کرده باشد.\nشروع کنیم. هرچه زودتر گولم‌ها به کار بیفتند، خیالم راحت‌تر می‌شود.", o = { "6 Decrepit Ranger Construct را در مرزهای Windrunner Village فعال کن.", "Decrepit Ranger Constructها را فعال کن (6)" }, p = "همین‌جا بودن عجیب است. این مکان... خب، فکر می‌کنم در واقع هم‌نام من است.", c = "Twilight's Blade همین حالا هم داشت در حاشیه‌ها پرسه می‌زد... درست بود که زود اینجا آمدیم." }
WoWFQ[86635] = { t = "به سوی Deatholme", d = "آن بزدل Antenorian همه ما را به نابودی کشاند. امیدوار بودم کار به اینجا نکشد، اما...\nبه بقیه پژوهش‌های Kasiea نیاز داریم--همان صفحه‌های گمشده که از جسدش دزدیده شد. اما فرقه به جنوب، به ویرانه‌های Deatholme عقب نشسته است.\nشایسته آن خائنان است که در چنین مکان پستی پنهان شده باشند. اما باید ریشه‌کنشان کنیم.", o = { "در Ruins of Deatholme با Magister Umbric دیدار کن.", "به Ruins of Deatholme سفر کن", "با Valeera Sanguinar صحبت کن" }, p = "مراقب پشتت باش. ویرانه‌های Deatholme هنوز خطرناک‌اند.", c = "حوصله ندارم دوباره به اینجا بیفتم... اما تنها همین یک راه است." }
WoWFQ[86636] = { t = "با من در Void قدم بزن", d = "انتظار نداشتم این مکان چنین حفاظت سنگینی داشته باشد. ماجرا بسیار پیچیده‌تر از یک رهبر بانفوذ و گروهی زائر گم‌عقیده است. با این حال... اگر Antenorian را از میدان به در کنیم، حسابی تضعیفشان می‌شود. فرقه بدون رهبر هیچ است.\nValeera آن فرماندار را تا همان غار دنبال کرد. وارد شده. ما مطمئن می‌شویم دیگر بیرون نیاید.", o = { "Deatholme Delve را کامل کن.", "وارد Deatholme Delve شو", "Delvers' Supplies را باز کن", "برای Valeera Sanguinar یک نقش نبردی انتخاب کن", "Lord Antenorian را بکش", "Stolen Knowledge را به دست بیاور" }, p = "بگذار این ماجرا را تمام کنیم. Twilight's Blade باید سقوط کند.", c = "یادداشت‌های Kasiea! بالاخره! باید بروم!" }
WoWFQ[86637] = { t = "هرچه بود، آسایش نبود", d = "وضعیت خطرناک است. Twilight's Blade بسیار بزرگ‌تر--و بسیار نیرومندتر--از آن چیزی است که هر یک از ما تصورش را می‌کردیم.\nخوشحالم که Umbric پیگیری می‌کند، اما باید به Silvermoon خبر بدهیم اینجا چه گذشته است.", o = { "با Silvermoon تماس بگیر.", "با Silvermoon تماس بگیر" }, c = "این‌قدر زود انتظار نیروی کمکی را نداشتم! پس کارت با Magister Umbric تمام شد؟\nبگذار راه بیفتیم." }
WoWFQ[86638] = { t = "ساقه‌های خفه‌کن", d = "تجربه Orweyna را در این امور ندارم. اما اگر Lightbloom با این سرعت پیش رفته، گمان می‌کنم rutaaniها اینجا هم همانند Fairbreeze در گسترشش می‌شتابند.\nشهر دیگر قابل نجات نیست، اما دست‌کم می‌توانیم بکوشیم Lightbloom را در همان دیوارهایش مهار کنیم.", o = { "Lightbloom را در Suncrown Village تنکیل کن.", "موجودات Lightbloom را بکش", "Infused Seedling را بکش (34)", "Incubating Lasher را بکش (20)", "Lightfrenzied Lasher را بکش (13)", "Lightfrenzied Lasher را بکش (13)", "Lightbloat Trampler را بکش (5)", "Bloom Propagator را بکش (10)", "Bloom Propagator را بکش (10)", "Bloom Dominator را بکش (7)", "Lucent Hookbeak را بکش (10)", "Lucent Hookbeak را بکش (10)", "Overfester Hydra را بکش (4)" }, p = "Fairbreeze در برابر این هیچ بود. اینجا... چه شده؟", c = "هرچه از دستمان برآمد زدودیم. فقط امیدوارم کافی باشد." }
WoWFQ[86639] = { t = "آنچه باقی مانده", d = "خودت می‌بینی با چه چیزی اینجا سر و کار داریم. Runestone Shan'dor کمک می‌کند گسترشش را در شمال‌تر متوقف کنیم، اما اگر این Lightbloom دوباره موج بزند، نمی‌دانم بتوانیم جلویش را بگیریم.\nصدای فریاد کمک بازماندگانی را شنیده‌ام که هنوز در گیر آن‌اند. باید پیدایشان کنیم و به امنیت راهنمایی‌شان کنیم!", o = { "در Suncrown Village بازماندگان را پیدا کن و کمکشان کن.", "به بازماندگان Suncrown کمک کن", "Apprentice Erilia را نجات بده", "Magistrix Silanna را نجات بده", "Outrunner Alarion را نجات بده", "Trainee Solanin را نجات بده", "گروه ریشه را نابود کن (20)", "روستاییان را شفا بده (20)" }, p = "به خاطر Light... این بسیار بدتر از هر تصوری بود که در سر داشتم.", c = "برخی زنده مانده‌اند... من سپاسگزارم، آن‌ها هم همین‌طور." }
WoWFQ[86640] = { t = "حس شوم", d = "هرچه سریع‌تر می‌توانستم آمدم. این... ویرانگر است.\nMagisterهایمان را خوانده‌ام تا این سنگ‌نوشته را تقویت کنند. مراقب گسترش Lightbloom خواهند بود.\nگمان می‌کنم Halduron Brightwing و Farstriderها بیشتر از آنچه روستاییان می‌دانند کشف کرده باشند. در هر چیزی می‌توانم روی او حساب کنم. در اردوگاه شمال به او می‌پیوندیم و به‌زودی پاسخ‌هایی خواهیم داشت.", o = { "در Scintilas Outpost دوباره به Lor'themar Theron بپیوند." }, c = "<Lor'themar بی‌حرکت می‌شود؛ نگاهش به ساحل پیش رو دوخته است.>" }
WoWFQ[86641] = { t = "زخم‌های کهنه", d = "البته که Amaniها همین لحظه را برای تجاوز انتخاب کردند، بزدل‌ها! از هر سو محاصره شده‌ایم!\nاین سرزمین از آنِ sin'doreiهاست و نخواهم گذاشت کسی آن را بگیرد. نه گیاهان خشمگین، نه یک فرقه، نه Void، و هرگز نه Amaniها!\nهرچه آن‌جا در دست دارند، باید متوقف شود. هر کاری از دستت برمی‌آید بکن تا نقشه‌شان را بر هم بزنی و آن‌ها را به Zul'Aman، همان‌جا که جای‌شان است، فراری بدهی.", o = { "عملیات چوب‌برداری Amani را در Tor'Watha بر هم بزن.", "عملیات چوب‌برداری ترول‌ها را بر هم بزن", "Trolls T1 را بکش", "Trolls T2 را بکش", "Cre'van را بکش (5)", "اشیا را بسوزان (17)", "آذوقه را نابود کن (17)" }, c = "هرچه دلیلی هم داشته باشند، Amaniها از این تجاوز پشیمان خواهند شد." }
WoWFQ[86642] = { t = "دشمنی نادیده", d = "می‌دانم Lor'themar خشمگین است، اما... این عجیب است، $p. آن‌ها به Suncrown حمله نکردند--Lightbloom کرد. Amaniها آن‌جا چه می‌کنند؟\nحتما توضیحی برای این ماجرا هست. شبیه یک حمله نیست. ببینیم چه می‌توانیم بفهمیم.", o = { "ببین ترول‌ها در Tor'Watha چه می‌کنند و اطلاعاتی پیدا کن.", "عملیات‌های Amani را بررسی کن (5)", "Vanatha را پیدا کن", "Lightbloom Axe را به دست بیاور", "Lightbloom Lumber Stack را به دست بیاور", "Amani Missive را به دست بیاور", "جسد Amani Feller را بررسی کن" }, c = "چه یافته‌ای؟" }
WoWFQ[86643] = { t = "در رد ریشه", d = "Lor'themar حق دارد از این سرزمین دفاع کند، اما به نظرم ذهنش روشن نیست. حضور Amaniها بیش از حد تحریک‌کننده است.\nاین‌ها جور در نمی‌آیند. ترول‌ها با عجله مشغول ساختن سلاح‌های Lightbloom هستند--برای جنگ با که؟ ما نیستیم. به Suncrown حمله نکردند. می‌توانستند، و نکردند.\nباید حقیقت را بیابیم. به سوی جنوب برویم. آن پناهگاهی که کشف کردم باید پاسخ‌هایی داشته باشد.", o = { "در Watha'nan Crypts در Eversong به Arator بپیوند.", "در ورودی Watha'nan Crypts به Arator بپیوند", "اندکی بمان و به Halduron گوش کن", "توتیم‌های محافظ را نابود کن (4)", "Door Blocker Totemها را نابود کن (2)", "توتیم آتش را نابود کن", "توتیم زهر را نابود کن", "با Arator صحبت کن" }, p = "برای همه این‌ها باید پاسخ منطقی‌ای وجود داشته باشد.", c = "Twilight's Blade Zul'Aman را هم می‌ترساند؟ این اصلا تصادفی نیست!" }
WoWFQ[86644] = { t = "خدایان پیش رو", d = "فکر نمی‌کنم باید انتظار استقبالی گرم را داشتم، اما انتظار نداشتم همین‌جا به دام بیفتم.\nAmaniها زیرک‌اند. حتما راهی برای فرار ساخته‌اند. فقط باید پیدایش کنیم. بگرد و ببینیم.", o = { "در Watha'nan Crypts جست‌وجو کن و Zul'jan را دنبال کن.", "اندکی بمان و به Arator گوش کن", "معمای Amani را بررسی کن", "معمای Amani را حل کن", "Bonecarapace Fangs را به دست بیاور", "گلدان 1 را پر کن", "Bloodvein Clot را به دست بیاور", "گلدان 2 را پر کن", "در عمق مقبره پیش برو", "کاشی‌های حکاکی‌شده را تطبیق بده", "تطبیق A", "تطبیق B", "تطبیق C", "تطبیق D" }, p = "راهی برای بیرون رفتن از این‌جا هست--می‌دانم.", c = "انگار این کار برایت آسان بود." }
WoWFQ[86646] = { t = "بن‌بست", d = "این مقبره تا چه عمقی ادامه دارد؟\nباید Zul'jan را پیدا کنیم و به او بفهمانیم که با دشمن مشترکی می‌جنگیم. البته که عقل را می‌پذیرد!\nبرویم. نباید در این هزارتو خیلی جلوتر رفته باشند.", o = { "Vanatha و Zul'jan را به عمق Watha'nan Crypts دنبال کن.", "با Vanatha روبه‌رو شو", "با Vanatha وارد نبرد شو" }, c = "این بی‌معنی است. باید جلویش را بگیریم!" }
WoWFQ[86647] = { t = "تپش خون", d = "هیچ‌کدام از این‌ها لازم نیست. باید کاری کنیم عقل را بپذیرند!\nپدرم می‌داند چه باید کرد. مطمئنم وقتی برایش توضیح بدهم اینجا چه گذشته، عقل را می‌پذیرد. نیازی به خونریزی نیست! ساده است: اگر Amaniها با Twilight's Blade سر جنگ دارند، ما در یک سو می‌جنگیم.", o = { "در Amani Pass به Arator بپیوند." }, c = "باید جلوی این ماجرا را بگیرم." }
WoWFQ[86648] = { t = "Light راهنمای ما", d = "یافته‌های ما در Tor'Watha درست از آب درآمد. وقتی من و Turalyon با نیروها به اینجا رسیدیم، Amaniها قبلا دست به تصرف گذرگاه زده بودند. می‌خواهند مسیر دیگری برای به دست آوردن lightwood از سرزمین ما باز کنند.\nAmaniها جنگ را برگزیده‌اند، همان‌طور که همیشه. این، دست‌کم، تهدیدی است که می‌دانم چگونه با آن کنار بیایم.\nArator هنوز یک نوجوان است. عمق تاریخ میان sin'dorei و Amani را نمی‌فهمد--و انتظارش را هم ندارم.\nآیا در کنار blood elfها و هر آنچه درست است می‌ایستی؟", o = { "نبرد در Amani Pass را فیصله بده: یا با کمک به blood elfها گذرگاه را امن کن، یا بکوش blood elfها را از جنگ منصرف کنی.", "نبرد در Amani Pass را فیصله بده", "نیروهای Sin'dorei را قانع کن (8)", "پرچم‌های Sin'dorei را بکار و پرچم‌های Amani را بسوزان (8)", "پرچم Amani 1", "پرچم Amani 2", "پرچم Amani 3", "پرچم Amani 4", "پرچم الف 1", "پرچم الف 2", "پرچم الف 3", "پرچم الف 4", "قانع کردن 1", "قانع کردن 2", "قانع کردن 3", "قانع کردن 4", "قانع کردن 5", "قانع کردن 6", "قانع کردن 7", "قانع کردن 8", "Rommath RP", "در Amani Pass Arator و Liadrin را پیدا کن", "در بالای Amani Pass Lor'themar را پیدا کن" }, c = "او همان است--کسی که رهبری این تجاوز کوچک را بر عهده دارد." }
WoWFQ[86649] = { t = "غیرقابل‌جبران", d = "این هیولاها چیزی جز کیفری سزاوار نمی‌دانند. برای Silvermoon. برای sin'dorei.\n<Turalyon's eyes blaze with Light.>\nبرای Alleria. این ماجرا تمام خواهد شد!", o = { "نبرد با Amaniها در Amani Pass را به پایان برسان.", "با Turalyon صحبت کن" }, c = "انتظار... این را نداشتم.\n<Lor'themar glances at Turalyon.>\nشاید از حدمان فراتر رفته باشیم." }
WoWFQ[86650] = { t = "شکسته", d = "Lady Liadrin همین‌جا می‌ماند. بقیه ما به Silvermoon بازمی‌گردیم تا گزارش بدهیم.\n<Lor'themar به Turalyonِ ویران‌شده از پا درآمده نگاه می‌کند.>\nبه نظر می‌رسد نبردهای بسیاری پیش رو داریم.", o = { "به Silvermoon City بازگرد.", "با Lor'themar صحبت کن" }, p = "کارهای بسیاری باید انجام شود.", c = "کاش می‌توانستم همراهتان بیایم، اما هنوز کارهای زیادی در Silvermoon مانده است.\nمأموریت‌های خودت را داری. در تماس باش.\nاما Arator... امیدوارم زود پیدایش کنی. Anu belore dela'na، <name>." }
WoWFQ[86708] = { t = "دروازه‌های Zul'Aman", d = "پس از تسلیم Amaniها، از Zul'jan خواستیم lightwood ما را پس بدهد و به سرزمین‌هایش برگردد. با این حال Zul'jan هنوز با سپاهش پشت دروازه‌های Zul'Aman درنگ می‌کند.\nLady Liadrin و Blood Knightهایش گذرگاه را نگه داشته‌اند و Liadrin می‌کوشد اوضاع را با دیپلماسی اصلاح کند، اما خبر می‌دهد که ممکن است تجاوز از نو آغاز شود.\nاو در این ماجرای شکننده از تو کمک می‌خواهد.", o = { "در Amani Pass با Lady Liadrin دیدار کن." }, c = "آتش‌بسمان شکننده است، اما پابرجاست. فعلا." }
WoWFQ[86710] = { t = "خط باید همین‌جا کشیده شود", d = "امید داشتم که Zul'jan پس از رویارویی‌مان، lightwood را رها کند و به‌سرعت به سرزمین‌هایش بازگردد.\nاما کنار آمدن با Amaniها هیچ‌وقت کار ساده‌ای نبوده است.\nدیپلماسی تنها راه پرهیز از خونریزی بیشتر است، اما Zul'jan دیگر حرف مرا نمی‌شنود.\nشاید حرف تو را بشنود؟", o = { "با Zul'jan صحبت کن و اوضاع را آرام کن.", "با Zul'jan صحبت کن", "Kill Credit را بکش", "اوضاع را آرام کن", "Void Beast را بکش" }, p = "نگاه یک غریبه شاید به او کمک کند عقل را بپذیرد.", c = "وقتی فهمیدم Zul'jan رهبر Amaniها نیست، احساس آسودگی کردم.\nاما این \"Zul'jarra\" شاید بدتر باشد.\nبه هر حال. باید از آن دروازه بگذریم و میزان تهدید Twilight's Blade برای Eversong را بسنجیم." }
WoWFQ[86734] = { t = "دیپلماسی", d = "همه ما درباره اوضاع نظر خواهیم داد.\n<Lor'themar نگاهی به Umbric و Rommath می‌اندازد.>\nهمان‌طور که می‌بینی، تنش‌های زیادی در کار است.\nلطفا چند لحظه برای گفتگو فرصت بدهید.", o = { "به گفتگو گوش کن.", "به گفتگو گوش کن" }, p = "چیزهای زیادی برای گفتگو داریم.", c = "بعضی‌ها با تصمیمم مخالفت خواهند کرد. اما نمی‌گذارم خانه‌مان را از دست بدهیم. اگر باید مهمانان موقتی را در خانه بگیریم، پس باشد." }
WoWFQ[86735] = { t = "سنگ‌فرشی از خاکستر", d = "حالا که کار فیصله یافت، بهتر است خودت را با Silvermoon آشنا کنی. چند شهروند مهم دارم که دوست دارم از حضورت اینجا باخبر شوند--بهتر است به دیدارشان بروی.\nانگشتر نشانم را به آن‌ها نشان بده--خواهند فهمید با اجازه من اینجایی. اما لطفا مواظب باش کجا می‌روی و در شهر بیرونی بمان تا مشکلی پیش نیاید.", o = { "انگشتر نشان Lor'themar را در گوشه و کنار شهر نشان بده.", "در Wayfarer's Rest سر بزن", "شبکه درگاه‌ها را بررسی کن", "با Skymaster در Silvermoon صحبت کن", "به صندوقدار اصلی بانک سر بزن", "به Reliquary سر بزن", "به Guard Captain Goldblade سر بزن", "با Vanguard of the Light احوالپرسی کن" }, p = "با همه حرف زدی؟", c = "یادت باشد، تو اینجا مهمان هستی. از کمکت قدردانیم، اما تا در این دیوارها هستی باید از قوانین ما پیروی کنی." }
WoWFQ[86736] = { t = "سنگ‌فرشی از خاکستر", d = "حرف‌های بیشتری برای رد و بدل کردن با Turalyon دارم، اما در این میان، بقیه شهر باید بدانند که در حاشیه بیرونی، مهمانان موقتی خواهیم داشت. دوست دارم با چند شهروند مهم دیدار کنی و خبر را برسانی.\nوقتی آن بیرونی، فرصت را غنیمت بشمار و با Silvermoon آشنا شو. از آخرین باری که آمده بودی، در بازسازی‌اش پیشرفت‌های چشمگیری داشته‌ایم.", o = { "با شهروندان اطراف شهر دیدار کن.", "در Wayfarer's Rest سر بزن", "شبکه درگاه‌ها را بررسی کن", "با Skymaster در Silvermoon صحبت کن", "به صندوقدار اصلی بانک سر بزن", "به Reliquary سر بزن", "به Magistrix Nizara سر بزن", "با Vanguard of the Light احوالپرسی کن" }, p = "با همه دیدار کردی؟", c = "هرچند حضور Alliance و Vanguard ممکن است برای برخی اضطرابی افزوده باشد، تحمل‌شان لازم است... فعلا." }
WoWFQ[86737] = { t = "نسیمِ خوش، شکوفهٔ Light", d = "در سال‌های اخیر، لکه‌های کوچکی از رشد وحشی که نامش را \"Lightbloom\" گذاشته‌ایم، در سراسر Eversong شکفته شده‌اند. برای گیاه‌شناس‌های محلی ما، بیش از همه چیزی عجیب بوده است.\nبا این حال، Magistrix در Fairbreeze برای سامان دادن به Lightbloom همان‌جا درخواست کمک دارد. تمام دستان توانمند من بر مهار Voidstorm متمرکز است--اما اگر Magistrix خودش از پس برنیاید، موضوع نیازمند توجه فوری است.\nدوست دارم خودت رسیدگی کنی. Magister Rommath می‌تواند برای در تماس ماندن، یک پروژکتور arcane به تو بدهد.", o = { "به Fairbreeze Village سفر کن.", "پروژکتور arcane را از Rommath بگیر", "اندکی بمان و به Liadrin گوش کن", "به Fairbreeze Village برس" }, c = "خدا را شکر--همه چیز کاملا از کنترل خارج شده است!" }
WoWFQ[86738] = { t = "Sharpmaw", d = "این جانورانی که دور و بر روستا می‌گردند مزاحم‌اند، اما مشکلی بزرگ‌تر در پیش داریم.\nلینکسی وحشی نزدیک‌ها پرسه می‌زند که نامش را گذاشته‌ایم Sharpmaw. قبلا با روستا فاصله می‌گرفت، اما وضعیت فعلی او را جسورتر کرده. این حوالی بچه‌های زیادی داریم و نگهبانان بیش از یک بار آن هیولا را دیده‌اند که مثل خوراکی آماده ربوده‌شدن به آن‌ها چشم دوخته است.\nقبل از اینکه جدی به آدم‌های من حمله کند، جلویش را بگیر!", o = { "Sharpmaw را بکش.", "به Sharpmaw نزدیک شو", "Sharpmaw را بررسی کن" }, p = "آن هیولا را هنوز نکشته‌ای؟", c = "چی؟ گیاهان غول‌پیکر؟ باز هم یک مشکل دیگر... دست‌کم آن هیولا برای همیشه از بین رفته. ممنونم." }
WoWFQ[86739] = { t = "لطف‌هایی در Fairbreeze", d = "عجیب‌ترین موقعیتی است که تا حالا در آن افتاده‌ام--روستای ما در حال تصرف شدن است!\nدوست دارم این‌جا همه‌چیز مرتب و سر و ته باشد، اما این حیوانات... از بیابان‌ها به داخل آمده‌اند انگار صاحب شهرند. به حیوانات خانگی دوست‌داشتنی‌مان حمله می‌کنند، وسایل‌مان را واژگون می‌کنند و آشوب به پا می‌کنند. هنوز یک مشکل را حل نکرده‌ام که دیگری سر بلند کرده. من فقط یک الف هستم--نمی‌توانم از پس همه این‌ها به تنهایی برآیم!\nدستی برسانی، نه؟ این... الف... ترول... آدم، هنوز انگشتی تکان نداده.", o = { "به بازگرداندن نظم به Fairbreeze Village کمک کن.", "Erratic Light Wyrm را بکش", "Hawkstriderها را بران (4)", "Lynxها را برای جابه‌جایی به دام بینداز (3)", "به شهروندان کمک کن (3)", "Darion Swiftdawn را بکش", "Kill Credit: Collect Book را بکش (5)", "Mr. Fluff را بکش" }, p = "هرچه زودتر روستا به آرامی برگردد، زودتر نفس راحت می‌کشم.", c = "خیلی ممنونم. شاید حالا بتوانم روستا را تا حدی به نظم برگردانم!" }
WoWFQ[86740] = { t = "ساکنان آواره", d = "به نظر می‌رسد حیات وحش اینجا از چیزی آشفته شده است. شاید دلیل آن است که آواز جهان مرا به اینجا فراخواند: تا دلیلش را کشف کنم و اصلاحش کنم.\nحیات وحش آشفته‌شده را مطالعه کن. یافته‌هایت را به من برسان. اگر چیز غیرعادی‌ای هست، می‌خواهم بدانم. با Magistrix صحبت خواهم کرد. شاید با هم بتوانیم پرده از این راز برداریم.", o = { "3 آشوب‌برانگیزِ حیات وحش آواره و 3 گیاه عجیب را در Fairbreeze Village مطالعه کن.", "آشوب‌ها را بررسی کن (3)", "گیاهان عجیب را بررسی کن (3)", "Trampled Bush را بررسی کن", "Territorial Dispute را بررسی کن", "Hasty Nest را بررسی کن", "Strange Lightbloom Plant را بررسی کن", "Strange Lightbloom Plant را بررسی کن", "Strange Lightbloom Plant را بررسی کن", "Kill Credit: Examine Plants را بکش", "Kill Credit: Examine Plants را بکش (2)", "Kill Credit: Examine Plants را بکش (3)" }, p = "شاید بتوانیم این مشکل را با هم حل کنیم.", c = "این Lightbloom--به نظر می‌رسد عامل همه دردهای اینجاست." }
WoWFQ[86741] = { t = "Lightbloom در کمین", d = "به نظر می‌رسد حیات وحش از جنوب رانده شده است. حتما آنجاست که پاسخ‌ها را پیدا کنیم.\nبیا--با جادویم مسیر را روشن می‌کنم و ردپا را دنبال خواهیم کرد.", o = { "ردپای حیات وحش آواره را دنبال کن.", "با Orweyna گفتگو کن", "ردپا را از Fairbreeze بیرون دنبال کن", "ردپا دنبال شد", "ردپا بیشتر دنبال شد" }, c = "این موجودات همه از همین‌جا می‌آیند. این Lightbloom... آواز جهان مرا به همین‌جا می‌کشاند." }
WoWFQ[86742] = { t = "کشتِ عجیب", d = "این مکان شبیه هیچ چیز دیگری نیست که تا حالا دیده باشم. رشد گیاهان اینجا بی‌همتاست.\n$p، بیا Lightbloom را با دقت بیشتری بررسی کنیم. شاید بتوانیم با هم رازهای این مکان را آشکار کنیم.", o = { "3 رست گیاهی Lightbloom را در Lightbloom Ath'Ran بررسی کن.", "رست‌های Lightbloom را بررسی کن (3)", "Kill Credit: Flowers Examined A را بکش", "Kill Credit: Flowers Examined B را بکش", "Kill Credit: Flowers Examined C را بکش", "Arator را پیدا کن و به او بپیوند", "Lightblinded Rutaani Grovewarden را بکش", "Light-Pulsing Seed را به دست بیاور", "در مکان امن‌تری به Arator بپیوند" }, p = "این هیچ منطقی ندارد.", c = "rutaaniها چنین نیستند! دست‌کم در سرزمین من نه. چیزی روی آن‌ها اثر گذاشته. این رفتار عادی نیست." }
WoWFQ[86743] = { t = "هرس Lightbloom", d = "موجودات این Lightbloom ما را مزاحم می‌بینند. حیات وحش اطراف و ساکنانی را که به‌طور طبیعی اینجا هستند تهدید می‌کنند.\nباید از شمارشان بکاهیم و به این تهدید پایان بدهیم.", o = { "موجودات Lightbloom را در Lightbloom Ath'ran بکش.", "موجودات Lightbloom را بکش", "Irradiant Thornmaw را بکش (7)", "Lightbloom Petalwing را بکش", "Lightbloom Hydra را بکش (13)", "Light Wyrm را بکش (50)", "Lightbloom Lasher را بکش (50)", "Lightfed Growth را بکش (13)" }, p = "این موجودات به‌شدت عجیب‌اند... انگار چیزی آن‌ها را می‌راند.", c = "دست‌کم فعلا تا حدی به این ناحیه آرامی می‌بخشد." }
WoWFQ[86744] = { t = "در جست‌وجوی حقیقت", d = "بر روی این دانه عجیبی که جمع کرده‌ایم قدرت روان خواهم کرد، تا ببینم می‌توانم بفهمم اینجا چه اتفاقی افتاده است.\nشاید این کار rutaaniها را بشوراند. مواظب باش کسی مرا قطع نکند. دلیل فراخوانده‌شدن من به اینجا همین بود--الان می‌دانم. اما باید بفهمم چه کاری لازم است انجام شود.", o = { "از Orweyna دفاع کن.", "با Orweyna گفتگو کن", "از Orweyna دفاع کن" }, p = "آه... شاید پاسخ‌هایی در دست داریم.", c = "rutaaniها می‌کوشند رشد Lightbloom را هرچه دورتر و گسترده‌تر پخش کنند. اما چرا؟" }
WoWFQ[86745] = { t = "Silvermoon باید بداند", d = "این رشد--Lor'themar باید از این باخبر شود. نگرانم اگر از کنترل خارج شود چه خواهد شد.\nو نفوذ Light... پدرم هم باید بداند.", o = { "با Silvermoon تماس بگیر.", "با Silvermoon تماس بگیر" }, p = "باید با Silvermoon تماس بگیریم و آنها را در جریان بگذاریم.", c = "دلم نمی‌خواهد ماجرا را همین‌طور رها کنم... اما Silvermoon حالا اطلاعات کافی برای مهار Lightbloom دارد، تا منتظر بررسی‌های Orweyna بمانیم.\nتا آن موقع... بدون Umbric نمی‌توانیم به ماجرای Sunwell رسیدگی کنیم." }
WoWFQ[86781] = { t = "رو در رویی با گذشته", d = "<Umbric با جدیتی سنگین نقشه Eversong را بررسی می‌کند.>\nTranquillien علامت خورده، همان‌طور که مکان‌های دیگری هم علامت خورده‌اند.\n<Umbric stops, voice tightening.>\nWindrunner Village. علامت خورده است.\nTwilight's Blade به پایگاه‌شان در Deatholme عقب نشسته، اما شاید خانه‌ام در خطر باشد. باید پیش از تعقیبشان، مطمئن شویم قوم من در Windrunner Village در امنیت‌اند.", o = { "در Windrunner Village به گروه بپیوند.", "به Silvermoon سر بزن", "در Windrunner Village به گروه بپیوند" }, c = "به نظر می‌رسد اینجا همه چیز سر جایش است... فعلا." }
WoWFQ[86832] = { t = "آهنگری شایسته", d = "بابت همه کمک‌هایت ممنونم، $p. عجیب است که بازمانده سپر پدرم را در دست بگیرم و بدانم که تا آن روز، او چنین پشتیبانِ دیگران بود.\nاحساس می‌کنم فقط روی پرخاشگرش را دیده‌ام. می‌دانم نیتش خوب است، اما به نظرم...\nآن راه، راه من نیست.\nبه هر حال، به Silvermoon بازگردیم و این تکه‌هایی که جمع کرده‌ایم را به آهنگری شایسته‌ای بسپاریم.", o = { "به Silvermoon بازگرد.", "درگاه را باز کن", "با درگاه به Silvermoon برو", "Arator را بدرقه کن" }, p = "<name>، نمی‌توانم از بابت همراهی‌ات در این سفر با من و Arator به‌اندازه کافی تشکر کنم.", c = "در Burning Steppes واقعا کار خوبی کردیم، <name>، و تکه‌های سپر Turalyon را بازپس گرفتیم.\nArator مشتاق است بازساخته‌شدنش را ببیند." }
WoWFQ[86833] = { t = "دژی از نو ساخته", d = "$p، وقت آن رسیده که ببینیم با این تکه‌های سپر Turalyon چه می‌توانیم بکنیم.\nهرچند شکست، در روزگار خود به‌شدت نیرومند بود و می‌تواند در برابر Void کمک بزرگی برای Turalyon باشد.\nو شاید لحظه‌ای هم برای شفا و رهاسازی باشد.", o = { "به Arator کمک کن سپر پدرش را بازسازی کند.", "Faol می‌رود", "با Arator صحبت کن", "به Arator در بازسازی Turalyon's Shield کمک کن", "[DNT] Kill Credit را بکش", "حال Arator را بپرس", "[DNT] گفتگو با Turalyon", "[DNT] رد کردن" }, p = "بابت کمکم در این کار ممنونم، <name>.", c = "<name>، دست‌کم می‌توانم بگویم ماجرا آن‌طور که امید داشتم پیش نرفت.\nامید داشتم بتواند ببیند... بپذیرد که هنوز می‌تواند تغییر کند.\nاما به نظر نمی‌رسد پذیرای چنین چیزی باشد--دست‌کم فعلا نه." }
WoWFQ[86884] = { t = "تنکیل و سوزاندن", d = "صرف تنکیل این موجودات کافی نیست. اگر از جسدهایشان غفلت شود، Light از بازمانده‌ها می‌تراود و از راه خاک به گیاهان اطراف می‌رسد.\nباید تدابیر شدیدتری اندیشید. استخوان‌های موجوداتی را که می‌کشی جمع کن. اگر بسوزانیم، شاید بتوانیم از گسترش بیشترشان از راه ریشه‌های این جنگل جلوگیری کنیم.", o = { "10 Corrupted Bone از حیات وحش آلوده به Lightbloom جمع کن.", "Lightbleached Rootbone را جمع کن (10)" }, p = "درنگ مکن. هرچه بیشتر برای تنکیل این رشد صبر کنیم، sin'dorei بخش بیشتری از این جنگل را از دست می‌دهند.", c = "دردناک است ببینی چیزی زاده Harandar چنین ویرانی بر مکانی این‌چنین می‌کارد. این ریشه‌ها شاید Aln'hara را در دامن نگیرند، اما به هر روی به سوی او می‌رویند." }
WoWFQ[86885] = { t = "مهار جریان", d = "وقتی Farstriderها نخستین بار Lightbloom را یافتند، گمان می‌کردیم فقط تغییر جنبه‌ای است--اذیت کوچکی از نفوذ Sunwell. کاش آن زمان آنچه را حالا می‌دانیم می‌دانستیم.\nاین ریشه‌راه‌های دیوانه‌شده از Light باید تا Harandar ادامه یابند. اگر نبندیمشان، فرقی نمی‌کند چند تا از این نفرت‌انگیزها را بیندازم. ریشه‌راه‌ها را ببند و شاید شانسی برای مبارزه داشته باشیم.", o = { "5 Lightfrenzy Portalway را بسوزان.", "Lightfrenzy Portalway را بسوزان (5)" }, p = "منتظر چه هستی؟ هر لحظه که می‌گذرد، بیشترشان از راه می‌رسند. همین حالا هم شانسمان اندک است.", c = "تاکون همه‌اش. برای هر ریشه‌راهی که می‌سوزانی، دوتای دیگر جای دیگر سبز می‌شود. انگار خودشان خودشان را می‌زایند و در چند لحظه می‌پراکنند.\nبه نظرم با تیر و جادو از پس این نمی‌بریم، حتی با کمک Orweyna. نه Alndust کافی داریم، نه haranir به اندازه کافی، که از گسترش این جنون جلوگیری کنیم." }
WoWFQ[86887] = { t = "عقب‌نشینی شتاب‌زده", d = "راهی برای جلوگیری از گسترش بیشتر Lightbloom در جنگل دارم، اما چندان لطیف نیست. در شرایط عادی هرگز به ذهنم نمی‌رسید در چنین بخش سرزنده‌ای از Eversong به آتش‌سوزی مهارشده دست بزنم... اما جنون به‌شدت سریع می‌پیچد و راه‌هایمان رو به پایان است.\nبه Farstriderهایم فرمان عقب‌نشینی داده‌ام، اما برخی پاسخ نداده‌اند. باید rangerهایی را که در گیرودارهای خطرناک گیر افتاده‌اند پیدا کنی و در به‌سلامت خارج شدنشان یاری رسانی.", o = { "3 Farstrider گرفتار را نجات بده.", "Swarming Shinesipper را بکش", "Swarming Lightsaptor را بکش", "Swarming Shinemaw را بکش" }, p = "وقت کم داریم، <name>. اگر Farstriderها هنوز در میدان باشند، نمی‌توانم نقشه‌ام را اجرا کنم.", c = "بیشتر Farstriderها به موضع ما عقب نشسته‌اند. آن‌ها که مانده‌اند آماده‌اند به محض آغاز مراسم، بی‌صدا خارج شوند.\nوقتمان تمام است. یا حالا، یا هرگز." }
WoWFQ[86891] = { t = "آخرین چاره", d = "با عقب‌نشینی نیروهای زمینی‌مان، موضع‌مان در چند دقیقه در هم می‌شکند. وقت اجرای نقشه‌مان است.\nRommath و Magisterها گوهری جادویی به ما داده‌اند که می‌توان با آن سنگ‌نوشته‌های Lash'ra را از کف درآورد. آن را بگیر و سنگ‌ها را با جادوی درونش آغشته کن. این، زمینه‌ساز مراسم Magisterهاست: منفجر کردن سنگ‌نوشته‌ها و خاکستر کردن همه Lash'ra.\nفقط باید امید داشته باشیم که Lightbloom در آتش سوزان دوام نمی‌آورد.", o = { "3 Phoenixfire Runestone را اضافه‌بار کن.", "Palehill Runestone را اضافه‌بار کن", "Lakegrove Runestone را اضافه‌بار کن", "Barksnarl Runestone را اضافه‌بار کن" }, c = "هرچه از دستمان برمی‌آمد، کردیم.\nحالا تنها مانده دفاع از Magisterهاست، و امید که این برای متوقف کردن گسترش جنون کافی باشد." }
WoWFQ[86892] = { t = "زنده بمان", d = "عقب‌نشینی‌مان به زمین امن‌تر از چشم دور نمانده. rutaaniها در هر حرکت ما را زیر نظر دارند و حالا قصد عبور از رود را دارند.\nباید هرچه می‌توانیم برای Rommath و Magisterها وقت بخریم. اگر اینجا شکست بخوریم، شاید کل Eversong از دست برود.\nاستوار بایست. سست مشو. و حداکثر تلاشت را بکن که نمیری.", o = { "از یورش Lightbloom جان به در ببر.", "به Rommath بگو مراسم را آغاز کند", "از یورش Lightfrenzy جان به در ببر", "[DNT] Kill Credit را بکش", "[DNT] Kill Credit را بکش" }, p = "نمی‌دانیم جنون کی از کرانه دریاچه می‌گذرد و به موضع‌مان می‌رسد. بهتر است Rommath مراسم را زودتر آغاز کند تا دیرتر.", c = "من... باورم نمی‌شود. هم‌تباران من بر روی زمین، شانه به شانه با ساکنان سطح، و با جادوهای Aln...\n<Orweyna فکش را محکم می‌کند و لبخندی به تو می‌زند.>\nاما وقت احساسات نداریم. باید Ruia را به سزایش برسانیم و به این جنون پایان بدهیم." }
WoWFQ[86894] = { t = "هدیه Aln'hara", d = "Ruia همیشه مدافعی پرشور بود، اما این رفتار از حد می‌گذرد. حتما Lightbloom بر او اثر گذاشته و به این اقدام‌های خطرناک می‌راندش.\nاما لازم نیست ما هم مثل او شویم. لازم نیست این جنگل هم مثل ریشه‌های Shaladrassil به دست شکوفه بیفتد.\nHara'ti به‌قدر کافی Alndust آورده‌اند تا متحدانمان را در برابر فساد استوار کند و از گسترش بیشتر جنون جلوگیری کند. تو و من با هم هدیه Aln'hara را در سراسر جنگل می‌پراکنیم. این جنون دیگر پیش نمی‌رود.", o = { "Alndust را به کار بگیر تا با جنون Lightbloom در Lightbloom Lash'ra بجنگی.", "جنون Lightbloom را در هم بشکن", "Haranir Packleaderها را نیرومند کن (10)", "Lightfrenzy Shinesipper را بکش (40)", "Lightfrenzy Devourer را بکش (20)", "Lightfrenzy Demolisher را بکش (10)", "Lightfrenzy Spore-Pod را نابود کن (14)" }, p = "Alndust ماده‌ای پیش‌پاافتاده نیست. باید در مصرفش دست‌ودل‌باز نباشیم. اما برای قومم، بدون درنگ هر چه دارم نثار می‌کنم.", c = "haranirها همیشه نیرومندند. اما با درخشش هدیه الهه بر ما، توقف‌ناپذیریم." }
WoWFQ[86896] = { t = "Light راهی پیدا می‌کند", d = "من در جانوران Eversong کارشناسم و با اطمینان می‌گویم که بخش بزرگی از حیات وحش اینجا اندازه‌هایی کاملا معمولی دارند.\nاما این saptorهای دیوانه‌شده از Light قطعا و قاطعانه چنین نیستند. یک گاز از آن آرواره‌های خاردار، اگر Farstriderها غافلگیر شوند، می‌تواند جان شش نفر را بگیرد.\nrangerهای من با کوله‌ای پر از تیر، در کنار haranirها مشغول تنکیل این کف‌ها هستند. مواظب باش آن tyrannosaptorهای سر به فلک کشیده، غافلگیرشان نکنند.", o = { "3 Lightfrenzy Tyrannosaptor را در Lightbloom Lash'ra بکش.", "Lightfrenzy Tyrannosaptor را بکش (3)" }, c = "با کارهای تو و متحدان تازه haranirمان، rangerهای من الگوهای درنده‌خویانه زیادی برای الگو گرفتن دارند. باید به آموزش برخی تکنیک‌های شما در Retreat فکر کنم." }
WoWFQ[86897] = { t = "سرکوب جنون", d = "روز تقریبا از آنِ ماست. sin'dorei هر جوانه تازه‌ای را که شکفته شود تنکیل می‌کنند و Hara'ti بیابان‌های اطراف را از نفوذ جنون در امان نگه می‌دارند. تنها چیزی که مانده، جدا کردن سرِ گمراه این مارِ lightbound است.\nRootwarden Ruia با هر حرکت ما مخالفت کرده و هر حرفمان را در نعوغ فرو برده است. اما او هنوز یک Rootwarden است؛ Rootwarden‌ای که قدرت یک میزبان Lightbloomِ جنون‌آمده را در فرمان خود دارد.\nاو نیرومند است. اما با Aln'hara قدم نمی‌زند.\nوقت آن است که به این ماجرا پایان دهیم.", o = { "با Lightwarden Ruia روبه‌رو شو.", "Lightwarden Ruia را بکش", "Kill Credit [DNT] را بکش" }, c = "تمام شد. هرچند شاید Lightbloom هرگز به‌طور کامل پس ننشیند، مغز متفکرش به ریشه‌راه رانده شد. با آرام شدن جنون و در امان ماندن جنگل‌های اطراف از پیشروی‌اش، خیالمان راحت است که Eversong دیگر گزند گسترش Lightbloom را نخواهد دید.\nکردیمش. بردیم!" }
WoWFQ[86898] = { t = "خیزش Haranirها", d = "تمام شد. جنون در هم شکست، Rootwarden گریخت و sin'dorei کنترل جنگل‌هایشان را پس گرفتند.\nبه سختی باورش می‌کنم، اما... موفق شدیم، <name>. به لطف Aln'hara، راهی رو به جلو یافتیم.\nحالا قوم Halduron ما را به لانه‌شان دعوت می‌کنند. از شهرهای سطحی شما خوشم نمی‌آید، اما...\nتو این‌قدرها به من کمک کرده‌ای، دوست من. وقتش است که Hara'ti هم دست یاری دراز کند.", o = { "در Gardens of Remembrance در Silvermoon City با Orweyna و Halduron دیدار کن." }, c = "برای نخستین بار در نسل‌ها، haranirها بر سطح آفرینش Aln'hara گام می‌زنند. زمان خواهد گفت آفرینش او هم چگونه از ما استقبال می‌کند.\nنبردها هنوز خیلی مانده. Void به دروازه‌های شما چنگ می‌زند و قوم شما را تهدید می‌کند. اما این را بدان، دوست من: از این روز به بعد، هر تهدیدی که به نعمت‌های Aln'hara دست دراز کند، با Hara'ti روبه‌رو خواهد شد، اینجا یا در اعماق زمین." }
WoWFQ[86997] = { t = "نزاع کتاب‌های جادو", d = "تو، همان‌جا!\nزمزمه‌های قهرمانی‌های به‌اصطلاح تو به گوشم رسیده، اما مطمئنم دروغ است. چون اگر راست بود، یعنی به موفقیت‌هایی بیش از من، Tytalor Goldenblade--بهترین، باهوش‌ترین و خوش‌چهره‌ترین mage این آکادمی--دستی یافته‌ای.\nپس اگر بزدل نیستی، به تو چالش می‌کشم تا ارزشت را ثابت کنی. کتاب‌های arcane برایت گرم‌کردنی خوب‌اند... البته اگر زنده بمانی. صفحه‌هایشان را از هم بدر و ثابت کن که کامل فریبکار نیستی.", o = { "9 Torn Spellbook Page از Arcane Tomeها در Sunstrider Isle جمع کن.", "Torn Spellbook Page را جمع کن (9)" }, p = "خب؟ صفحه‌ها را در دست داری، یا اعتراف می‌کنی فریبکاری؟", c = "تکان‌دهنده است. واقعا تکان‌دهنده. شاید بعد از همه این‌ها حرفی از حقیقت در تو باشد--اما فقط شاید." }
WoWFQ[86998] = { t = "مرحله تمرین", d = "اه! واقعا از پس کتاب‌های جادو برآمدی؟ به نظر می‌رسد سنجاب کور هم گاهی فندقی پیدا می‌کند.\nولی زیاد به خودت بال نده! دنباله‌روهای من آن‌جا این‌قدر راحت طعمه دست‌وفوت‌های تو نمی‌شوند. وقتی طبق معمول شکست خوردی، حتما به خاطر می‌آورم که این لحظه، لحظه‌ای بود که غرور بر تو چیره شد.", o = { "6 mage را در Sunstrider Isle مغلوب کن.", "mageها را مغلوب کن" }, p = "اه! پس حتی در شکست دادن بی‌کفایت‌ترین دنباله‌روهایم هم ناکام ماندی و سینه‌خیز برگشتی؟", c = "باید اعتراف کنم، تو را دست‌کم گرفتم. به نظر می‌رسد تو چیزهای بیشتری از دست‌وفوت کردن داری." }
WoWFQ[87002] = { t = "آرزوهای علمی", d = "چه جالب. واقعا تا اینجا پیش رفته‌ای و گمان می‌کنی چیزی را ثابت کرده‌ای. بگذار روشن کنم--هیچ‌کدام از کارهایت با توانایی من قابل مقایسه نیست. ساده‌ترین چالش‌ها را به‌سختی گذرانده‌ای، اما حالا نوبت من است. بالای این برج به من بپیوند تا دقیقا نشان بدهم چقدر از من پایین‌تری.", o = { "Tytalor Goldenblade را در Sunstrider Isle مغلوب کن.", "از Arcane Translocator استفاده کن", "Tytalor Goldenblade را مغلوب کن" }, c = "امروز مرا مغلوب کردی، اما حرفم را به خاطر بسپار... دوباره برمی‌خیزم و از به‌خطر انداختن من پشیمان خواهی شد. من Tytalor Goldenblade هستم و این شکست فقط موقتی است!" }
WoWFQ[87392] = { t = "توطئه محموله", d = "تابش Sunwell ممکن است بدرخشد، اما Light آن پلیدی‌ای را که در این شهر می‌جوشد نزدوده است. قاچاقچیان مثل موش در خیابان‌ها می‌خزند، از نومیدان می‌دزدند و بی‌استخوان‌ها را پولدار می‌کنند.\nبا این حال، از چیز کثیف‌تری هم زمزمه‌هایی هست--تجارتی در کالاهایی چنان پست که حتی Venture Company هم از آن پس می‌زد. کسی لازم دارم که هر شرکت حمل‌ونقل دریایی را زیر نظر بگیرد و بفهمد کدام‌یک لقب قاچاق سازمان‌یافته را گرفته است.\nآیا با من می‌ایستی، یا در حالی که پوسیدگی می‌پیچد روی‌گردان می‌شوی؟", o = { "شرکت‌های حمل‌ونقل دریایی را در Fairbreeze Village بررسی کن.", "جایی برای شنود Sunrun Salvage پیدا کن", "جایی برای شنود Duskflight Exports پیدا کن", "جایی برای شنود Tideborne Freight پیدا کن", "Abandoned Note را بردار" }, p = "خب، آن کارگران بندر محترم ما چه گفتند؟", c = "آه، یادداشتی درباره \"محموله ویژه\". چه لطافت محتاطانه‌ای--به‌اندازه آتش‌بازی یک گابلین بی‌محابا آشکار.\nبه نظر می‌رسد Tideborneها در این ماجرا لنگ انداختند و چاره‌ای جز غرق شدن در آن نداریم. اگر یعنی شیرجه به اعماق، پس باشد." }
WoWFQ[87393] = { t = "جست‌وجویی موجه", d = "Tideborne Freight، اینطور است؟ نامی بیش از حد صیقلی، مثل شمشیری مزین که از خونی که ریخته حواس را بپراند. قاچاق از راه بندر... اما گمان می‌کنم این کار به چیزهایی بسیار خطرناک‌تر از آنچه می‌پنداریم گره خورده است.\nباید شتاب کنیم پیش از آنکه بادبان برافرازند و در مه‌ها گم شوند. سلاح‌هایت تیز و حواس‌هایت تیزتر باشد. بفهمانند که دست درازی به من، اشتباهی سنگین بود.", o = { "12 ملوان Tideborne Freight را در Sunsail Anchorage \"بازجویی\" کن.", "ملوان‌های Tideborne Freight را \"بازجویی\" کن" }, p = "هنوز برگشتی؟ بگو ببینم. درباره Tideborneها چه کشف کردی؟ و هیچ جزئیاتی را هم جا نینداز", c = "البته که دوست دارند چشم‌های کنجکاو را دور نگه دارند.\nحافظ چیزی هستند. حالا باید دقیقا بفهمیم آن چیست." }
WoWFQ[87394] = { t = "زیر نظر گرفتن تأمین‌کنندگان", d = "این یادداشت از گناهکاری می‌تراود، اما حرف‌های خالی Tideborne Freight را نمی‌اندازد. به مدرکی انکارناپذیر نیاز دارم--دلیلی این‌چنین محکم که حتی قضات رشوت‌خورده‌شان هم نتوانند روی‌گردانی کنند. اینجاست که تو وارد ماجرا می‌شوی.\nاین دستگاه ضبط arcane را بگیر و به سوی اسکله‌ها برو. بارها و خدمه‌شان را ثبت کن--هر چیزی که بوی قاچاق بدهد.\nیک تصویر گاهی هزاران حرف دارد، و من قصد دارم تک‌تک کلمات را حساب‌شده به کار ببرم.", o = { "در Sunsail Anchorage مدرک ضبط کن.", "Side View Recorder را جاگذاری کن", "Upper View Recorder را جاگذاری کن", "Front View Recorder را جاگذاری کن", "کشتی را زیر نظر بگیر" }, p = "برگشتی، و با ضبط‌ها، امیدوارم.", c = "ببین--دستِ رو.\nریختن بارها به اقیانوس؟ به‌وضوح دارند شواهد را پاک می‌کنند، که فقط یک معنا دارد: به چیزی مهم داریم نزدیک می‌شویم." }
WoWFQ[87395] = { t = "زیر آب‌های شور", d = "انداختن جعبه‌ها به اقیانوس؟ چه عاجزی تمام‌عیاری.\nهرچه می‌خواهند پنهان کنند حتما چیزی محکم است--آن‌قدر که اگر به دستش بیاوریم، کل نقشه‌شان را می‌گشاید.\nنفس عمیق بکش و پیش از آنکه جریان آب با خودش ببرد، بیرونش بکش. هر رشته‌ای که می‌کشیم، نقشه‌شان بیشتر باز می‌شود. به‌زودی چیزی جز ویرانی‌ای که خودشان ساخته‌اند باقی نمی‌ماند.", o = { "12 Submerged Cargo Item را در Sunsail Anchorage بیرون بکش.", "Submerged Cargo را بررسی کن", "Unstable Arcana را جمع کن (12)" }, p = "پس دوستانمان در Tideborne Freight با این عجله می‌خواستند چه را پنهان کنند؟ خزیدنشان برای همیشه نیت واقعی‌شان را پنهان نمی‌کند.", c = "Unstable Arcana و naga؟ این دیگر اصلا قاچاق نیست--فاجعه‌ای است در انتظار وقوع.\nTideborneها در ماجراجویی‌هایی می‌کنند که بهتر بود دست نمی‌زدند. به نظر می‌رسد حالا مسئولیت حل کردنش، پیش از آنکه به فاجعه بدل شود، با ماست." }
WoWFQ[87396] = { t = "دستِ رو", d = "تصمیم Tideborne به انداختن جعبه‌ها در اقیانوس خطای ساده‌ای نبود. یک تحویل حساب‌شده بود.\nبه تعقیبشان ادامه بده و مطمئن شو nagaها یادشان می‌آید وقتی جرئت دست درازی به ما را دارند، چه عواقب سنگینی در انتظارشان است.", o = { "10 naga از Tideborne را در Sunset Strand مغلوب کن.", "nagaهای Tideborne را مغلوب کن" }, p = "به تعقیبشان بپرداز!", c = "خوب بود. شاید nagaها دیگر کارشان تمام باشد، اما کار ما هنوز خیلی مانده.\nTideborne Freight همچنان سکان را در دست دارد، و وقتش رسیده که این کنترل را قطع کنیم." }
WoWFQ[87397] = { t = "تلفات محموله", d = "اگر nagaها موفق شوند باقی‌مانده انرژی arcane را از آن Unstable Arcanaها بدزدند، دقیقا به همان قدرتی می‌رسند که در جست‌وجویش هستند.\nنابودشان کن، بسوزان، خردشان کن--هر چه لازم است بکن. مواظب باش حتی یک تکه هم برای سوءاستفاده nagaها یا Tideborneها نماند. حتی نمی‌خواهم اثری از ضعیف‌ترین انرژی arcane باقی بماند.", o = { "5 Smuggled Crate را در Sunset Strand نابود کن.", "Smuggled Cargo را نابود کن (5)" }, p = "مطمئنم خداحافظی آبرومندی با آن بار کرده‌ای.", c = "کاری که لازم بود را کردی. اگر بارها از بین رفته‌اند، این یک پیروزی است--اما کارمان هنوز تمام نشده.\nTideborneها هنوز باید در برابر اعمالشان پاسخگو باشند." }
WoWFQ[87398] = { t = "رویارویی با قاچاقچیان", d = "nagaها از سر ناچاری عمل کردند. اما خدمه Tideborne از سر غرور می‌رانند. با خوشخیالی روی کشتی‌شان نشسته‌اند، از دست‌نیافتنی بودن خود مطمئن و مشغول شمردن ثروت ناحوانشان. وقت آن است که به این کار پایان بدهیم.\nCaptain Bloodwake باید به ازای هر جعبه، هر معامله و هر تجاوز، پاسخگو باشد. آماده‌ای حقیقت را بیرون بکشی؟", o = { "Captain Dorynth Bloodwake را در Sunsail Anchorage مغلوب کن.", "با Grappling Hook سوار کشتی شو", "Captain Dorynth Bloodwake را مغلوب کن" }, c = "خوب بود. مطمئنم در آینده هم آدم‌هایی مثل او پیدا می‌شوند، اما دست‌کم برای امروز، این بندر به لطف تو در امنیت است.\nامیدوارم در آینده هم بتوانم رویت بشمارم، شریک." }
WoWFQ[87399] = { t = "رو در روی خورشید", d = "این sanctum خیلی پیش از ماجرای Fairbreeze روی Lightbloom مطالعه داشت. تا آن لحظه دلیلی برای نگرانی از پژوهش‌هایشان نداشتیم.\nبا این حال، آخرین پیامی که فرستادیم هرگز پاسخی دریافت نکرد. و حالا که به اینجا آمده‌ایم، اوضاع اصلا خوب به نظر نمی‌رسد.\nاما اول باید بخشی از حیات وحش را از میان برداریم. نمی‌توانیم ریسک آلودگی داشته باشیم.", o = { "8 حیوان مهاجم را بکش.", "حیوانات مهاجم را بکش" }, p = "شکار چطور پیش می‌رود؟", c = "کاری ناخوشایند است، اما این موجودات به اینجا تعلق نداشتند. برای هر پژوهشگر تازه‌ای خطر می‌آفریدند.\nحالا به سراغ مشکل اصلی می‌رویم." }
WoWFQ[87400] = { t = "پراکنده در پره‌های آفتاب", d = "به باغبانان فرصت داده‌ایم بدون مزاحمت به کارشان ادامه دهند. امیدوارم تا وقتی Silvermoon فرصت بازسازی کند، این مکان پابرجا بماند.\nاما حالا باید بفهمیم پژوهشگران گمشده کجایند. در باغ‌های انتهایی روی تأثیر mana بر گیاهان مطالعه می‌کردند. شاید نشانه‌ای از آن‌ها آنجا پیدا کنیم.", o = { "نشانه‌هایی از سرنوشت پژوهشگران Sanctum پیدا کن.", "نشانه‌های پژوهشگران را پیدا کن (3)", "Odd Flower را بردار", "Research Log را بردار", "Mirveda Sunpetal را بکش" }, c = "حله می‌کنم این به دست یک captain برسد. و درست نگهداری شود که پخش نشود." }
WoWFQ[87401] = { t = "پیش‌آمد باغبان", d = "به نظر می‌رسد درِ sanctum قفل است. احتمالا از داخل.\nبه باور من یک سازه arcane برای جابه‌جایی بارهای سنگین و نگهداری عمومی در کنار treantها به کار می‌رود. هسته‌اش باید قفل در را از کار بیندازد و مثل کلید اصلی عمل کند. گمان نمی‌کنم بدون دردسر آن را بدهند، پس مراقب باش.", o = { "یک سازه جادویی پیدا کن و هسته‌اش را بردار.", "Humming Core را بردار" }, p = "بفرمایید؟", c = "عالی. این باید ما را به داخل ساختمان اصلی برساند." }
WoWFQ[87402] = { t = "Light چاره می‌سازد", d = "باید وارد Sanctum شویم. همین حالا.\nریشه‌های روی آن در را بسوزان! و آماده باش--پشتش نمی‌تواند خبر خوشی باشد.", o = { "در Sanctum of the Sun را باز کن و با آنچه آن‌سوست کنار بیا.", "در را باز کن", "Hungering Lightroot را بکش" }, p = "نمی‌توانیم درنگ کنیم.", c = "آنچه آن‌سوی آن درها بود، وحشت بود. استفاده از Light در چنین شکلی...\nممنونم. پیش از آنکه دوباره از این مکان استفاده شود، با شعله‌ها پاکش می‌کنیم." }
WoWFQ[87455] = { t = "محاکمه‌ها و حساب‌کتاب‌ها", d = "اگر برگردیم عقب، بهتر بود در سرزمین بی‌طرف می‌گساری می‌کردیم.\nمن و Gidwin وقتی جنگ چهارم شعله‌ور شد، در Silvermoon تعطیلات بودیم. از شهر گریختیم اما یک... قبض می‌گساری نسبتا سنگین جا گذاشتیم.\nGidwin رفته به همان مکانی که اقامت داشتیم تا یک وسیله گران‌قیمتی که جا گذاشته بودیم پیدا کند، اما دیر کرده. می‌شود بروی پیدایش کنی تا من این طلبکار را سرگرم نگه دارم؟ تا حالا باید برگشته می‌بود.", o = { "Gidwin Goldbraids را در Silvermoon پیدا کن." }, c = "<A muffled voice reaches you.>\nنه نه، خودم گرفتمش! عقب بکش!" }
WoWFQ[87456] = { t = "یادگاری‌های پراکنده", d = "وقتی قبلا من و Tarenar از شهر گریختیم، چند چیز جا گذاشتیم.\nقبض می‌گساری پرداخت‌نشده، بله. اما برای بعضی دوستانمان یادگاری هم خریده بودیم.\nمی‌شود لطفا دنبالشان بگردی؟ جایی همین وسط این به‌هم‌ریختگی هستند.", o = { "یادگاری‌ها را در Silvermoon پیدا کن.", "Art and Architecture of Silvermoon: Vol. 3 را پیدا کن", "Satchel of Herbs را پیدا کن", "Nondescript Bottle of Water را پیدا کن" }, p = "همه یادگاری‌ها را پیدا کردی؟ برای بقیه گروه‌مان در Suramar چیزهای دیگری هم گرفته بودیم، اما وقتی فرار کردیم وقتی برای پست کردن این‌ها نداشتیم.", c = "با توجه به مدتی که این‌جا جا گذاشته بودیم، به‌نظر خوب سرِ جای‌شان هستند.\n<Gidwin holds up the bag of herbs.>\nمطمئن نیستم Fiona هنوز دنبال این‌ها باشد یا نه، اما از این... اِم... حسن نیت خیلی دیرهنگام قدردان خواهد بود." }
WoWFQ[87457] = { t = "کاری که از آن برمی‌آییم", d = "آن عنکبوت! درست همان لحظه که از در وارد شدم، روی من ماده ریخت. از عنکبوت‌ها و آن‌همه nerubian که این روزها می‌زنیم، بیش از حد چسبیده‌ام!\nاز گوشه چشمم چیزی دور گردنش دیدم. یک اثر باستانی است که هنگام جنگ با Legion یافته بودیم. بهای خوبی می‌آورد.\nفقط باید سر آن عنکبوت را از تنش جدا کنی!", o = { "Squatter را بکش و Antique Necklace را در Silvermoon بردار.", "Antique Necklace را بردار" }, p = "این گردنبند در اردوگاهی بود که از شیاطین پاکش کردیم. حتما برای مراسمی بود، اما مانع شدیم نفرینش کنند.", c = "عالی شد، <name>. ممنونم.\nبه آن الف نگو پیچیده شدم، می‌شود؟" }
WoWFQ[87458] = { t = "تسویه بدهی‌ها", d = "به نظرم همین‌ها تمامش بود. باور نمی‌کنم از جنگ چهارم این‌قدر گذشته باشد. با این عجله جا ماندیم.\nبگذار آن گردنبند را به Tarenar برسانیم. به‌اندازه کافی منتظر مانده است.", o = { "در Silvermoon نزد Tarenar Sunstrike بازگرد." }, c = "بابت کمک به تمام کردن این ماجرا ممنونم، <name>. بهای این گردنبند به‌راحتی قبض قدیمی می‌گساری‌مان را می‌پوشاند.\nGiddy زیاد دردسر نشد، نه؟" }
WoWFQ[88919] = { t = "به درون Darkway", d = "شاید بدلِ Ulen فرار کرده باشد، اما گمان می‌کنم می‌دانم فرقه مشغول چه کاری بوده است.\nTwilight's Blade حتما در تغییر مسیر جریان mana در Suramar دست دارد. بدون اینکه به مکان‌های درست برسد، آگاهی‌مان کند می‌شود، گولم‌هایمان پژمرده می‌شوند و کل جامعه‌مان ریسک قطع mana می‌کند.\nفقط یک مکان هست که بتوانند از آن‌جا چنین کنترلی بر ley lineهای ما اعمال کنند، و آن هم Arcway است.\nبرو. پیدایشان کن و در هم بشکنشان.\nوقتی کار تمام شد، در Silvermoon دیدار می‌کنیم.", o = { "Twilight Imposter Gulkat را در Darkway Delve بکش.", "وارد Darkway شو", "Infiltrator Gulkat را بکش" }, c = "خوب انجامش دادی، champion.\nگولم‌هایمان دوباره راه می‌افتند، سربازانمان می‌توانند دوباره سلاح‌هایشان را احضار و شارژ کنند و ما برای جنگ بسیج می‌شویم." }
WoWFQ[88920] = { t = "Kaldorei‌ها", d = "باید پیش از آنکه جهان از هم بپاشد، Darkwell را بازپس بگیریم و L'ura را شکست بدهیم.\nبه یک ارتش نیاز داریم. نه. به ارتش‌های بسیار.\nباید به سراغ الف‌های دیگر برویم. بهتر است با kaldoreiهای Bel'ameth آغاز کنیم. Oculeth می‌تواند یک هیئت کوچک را به آنجا منتقل کند و ما درخواستمان را مطرح کنیم.\nبا این حال... خون بسیاری میان الف‌ها ریخته شده. دشمنی‌هایی که دور می‌روند و ژخ می‌زنند. به امید بچسب، <name>. تنها چیزی است که برایمان مانده.", o = { "به نقشه Arator گوش کن و سپس از Portal Telemancer Oculeth به Bel'ameth برو.", "به نقشه Arator گوش کن", "با درگاه به Bel'ameth برو" }, p = "آماده حرکتی، Champion؟", c = "چه گروهی آورده‌ای به سرزمین‌های من، <race>." }
WoWFQ[88922] = { t = "Quel'dorei‌ها", d = "<name>، تا kaldoreiها بسیج می‌شوند، می‌توانم از حضور تو به‌عنوان شاهد استفاده کنم تا از گروهی دیگر کمک بخواهم.\nبرای آنچه در پیش است به quel'doreiها نیاز خواهیم داشت، هر اندازه هم که برخی sin'doreiها اعتراض کنند.\nOculeth قبول کرده برای دو نفرمان درگاهی باز کند تا به خاله‌ام، Vereesa Windrunner، برسیم؛ همان‌جا که در Eversong چشم‌به‌راهمان است.\nsin'doreiها با من نمی‌آیند. تو می‌آیی؟", o = { "با درگاه Oculeth به Eversong Woods برو.", "اندکی بمان و گوش کن", "از درگاه به Silverglade Refuge استفاده کن" }, c = "<name>، مطمئنم خاله‌ام، Vereesa Windrunner، را به یاد داری. در ویرانه‌های Dalaran همراه ما بودی وقتی بینش‌هایش از تاخت‌وتاز Void بر Sunwell نخستین بار ظاهر شد.\nاو و Silver Covenantش، بازمانده quel'doreiهای همان روزگار، در نبرد پیش رو بسیار گران‌بها از آب درمی‌آیند." }
WoWFQ[88928] = { t = "Shal'dorei‌ها", d = "Champion، آمدنت به‌وقت بود. برای بسیج ارتش‌های Suramar پیام فرستادم، اما هنوز نرسیده‌اند.\nاگر جایی میلنگید باید فرمانده‌ام مرا خبر می‌کرد، اما هیچ خبری نشده.\nقصد دارم به Suramar بروم و ببینم قضیه چیست. همراهی می‌کنی؟ شاید به مهارت‌هایت نیاز داشته باشم.", o = { "با درگاه Oculeth به Suramar سفر کن.", "از Portal Oculeth به Suramar استفاده کن" }, c = "نمی‌دانم First Arcanist به چه اشاره می‌کند. مدتی است در صلح به سر می‌بریم." }
WoWFQ[88938] = { t = "نمادهای گذشته", d = "هشدار Arator تکان‌دهنده است. وقتی به Silvermoon برگردیم، غم فراوان و حتی تهدیدهای فراوانی در انتظارمان خواهد بود.\nگمان می‌کنم اگر بدون آمادگی وارد شویم، Aethas و Sunreaverهایش راهمان را سد می‌کنند.\nبرای همین، چند بازمانده گران‌بها از تاریخ مشترکمان، پیش از فروپاشی Dalaran، را نگه داشته‌ام. می‌شود لطفا برایم جمعشان کنی، <name>؟", o = { "Relicهای High King Anasterian Sunstrider را جمع کن.", "اندکی بمان و گوش کن", "Crown of the High King را پیدا کن", "Anasterian's Book of Law را پیدا کن" }, p = "پیش از سقوط Dalaran فرصت نگهداری چیز زیادی را نیافتیم. اما هر شیء بازپس‌گرفته‌شده، تاریخ و معنا و عبرت‌هایی با خود دارد--عبرت‌هایی که هر شهروند Quel'Thalas باید در یک نگاه آن‌ها را دریابد.", c = "یادگارهای آخرین High King در Quel'Thalas. او کسی بود که همه quel'doreiها و sin'doreiها به او احترام می‌گذاشتند.\nقصد دارم این یادگارها را به خانه اصلی‌شان بازگردانم." }
WoWFQ[88939] = { t = "آرامش برای بی‌قراران", d = "پیش از آنکه بتوانیم با زندگان آشتی کنیم، باید مردگان را به آرامش برسانیم.\nسال‌ها پیش، Dalaran را از هر الفی که با Horde متحد بود پاک‌سازی کردم. به پای اعمال warchief آن روزها که به مرگ شوهرم انجامید، آن‌ها را مقصر می‌دانستم.\nحالا، سال‌ها بعد، آن ارواح هنوز رهایم نمی‌کنند. می‌شود آرامشان کنی و بازمانده‌هایشان را جمع کنی؟ من با رساندن این بازمانده‌ها به Silvermoon اندکی جبران می‌کنم. سزاوار بازگشت به خانه‌اند.", o = { "10 Remains of the Fallen از پاک‌سازی‌شدگان Dalaran جمع کن.", "Remains of the Fallen را جمع کن (10)" }, p = "من اجازه دادم این‌قدر طولانی قومم را شکنجه کنند. من هم سهمی از این گناه دارم.", c = "ممنونم، <name>.\nوقتش است که این ارواح را به خانه‌شان برسانم." }
WoWFQ[88941] = { t = "برای Quel'Thalas", d = "وقتش است به Silvermoon بازگردیم. شکی نداریم که ما را خائن و قاتل خطاب خواهند کرد.\nبرایم مهم نیست چگونه دیده شویم. مهم این است که Quel'Thalas زنده بماند.\nبه ما می‌پیوندی، <name>؟\nاز حرف‌های Arator که می‌فهمم، بیش از اندازه از احترام Silvermoon را به دست آورده‌ای. اگر در بی‌دردسر وارد شدن به شهر کمکی کنی، احساس افتخار می‌کنم.", o = { "همراه با Vereesa Windrunner در دروازه‌های Silvermoon با Sunreaverها روبه‌رو شو.", "در دروازه Silvermoon به Vereesa بپیوند" }, c = "ممنونم، <name>.\nحالا بیا پیش از آنکه دیر شود، برای دفاع از این شهر نقشه بریزیم. باز هم." }
WoWFQ[88942] = { t = "الف‌ها به جنگ می‌روند", d = "درباره نیروهایی که در نبرد پیش رو با آن‌ها روبه‌رو می‌شویم، چیزهای زیادی آموخته‌ایم.\nSuramar بدهی‌ای را که به خاطر کمک‌شان در روزهای تنگدستی به sin'dorei بدهکاریم، به یاد دارد. حالا که نیروهایمان جمع شده و گولم‌هایمان آماده‌اند، برای دفاع از این شهر، گویی شهر خودمان است، آماده‌ایم.\nبیا، <name>. به Lor'themar بازگردیم. وقت بحث درباره راهبرد نبرد است.", o = { "به Sanctum of Light در Silvermoon City بازگرد." }, c = "فرقه‌گرایان؟ به نظر می‌رسد Xal'atath مصمم است در هر فرصت زیر پای ما را بکند.\nباید شکرگزار باشیم که همچنان مهارت‌های تو را دست‌کم می‌گیرد.\nبا آماده شدن Nightborneها، یعنی نیروهایمان جمع شده‌اند. مواضع را می‌گیریم و بهترین راه به‌کارگیری نیروها را برنامه‌ریزی می‌کنیم.\nممنونم، champion." }
WoWFQ[88977] = { t = "بازسازی جرم", d = "آه، تو همان‌جا! به نظر خردمندانه‌ای که بتوانی به من کمک کنی، برخلاف فلان ساده‌لوحِ تیرانداز که گمان می‌کند خزیدن در خاک مشکلمان را حل می‌کند.\nناخواسته دفترچه بسیار مهمی را گم کرده‌ایم--از آن جنس‌هایی که استادم اگر گم کرده بودم، مرا به شیء دیگری تبدیل می‌کرد!\nلطفا با ساعت arcane من، پژواک‌های گذشته را احضار کن و این لحظه‌ها را بررسی کن. به این ترتیب دفترچه‌ام را درست پیدا می‌کنیم، بدون آنکه به روش‌های ابتدایی Vardis تن بدهیم.", o = { "با Arcane Timepiece 3 Frozen Moment را در West Sanctum بررسی کن.", "از Arcane Timepiece استفاده کن", "Frozen Momentها را بررسی کن (3)", "Magister Meledor را بکش", "Magister Meledor را بکش", "Magister Meledor را بکش" }, p = "ناممکن است. جادویم تاکنون هرگز یاریم نکرده... به نظر می‌رسد به بن‌بست رسیده‌ایم.\nمغلوب شدن از چیزی این‌قدر ساده، اما به‌شدت مؤثر... عذاب‌آور است.", c = "عالی--باز هم تصویرهای درخشان و ارواح خشمگین، اما هنوز خبری از دفترچه نیست.\nکنار برو. من این بیهودگی را تمام می‌کنم و ردپایش را درست می‌گیرم." }
WoWFQ[88978] = { t = "در رد ردپا", d = "در حالی که فلان mage با مغز اژدهایی وقتش را با جادوی بی‌مصرفش تلف می‌کند، ما واقعا این پرونده را حل می‌کنیم.\nاحتمالا حیات وحش محلی دفترچه را قورت داده. وقت شکمشان را دریدن است و ببینیم می‌توانیم پس بگیریمش.\nاگر داخلشان باشد، پیدا می‌کنیم... برخلاف فلانی که اگر منِ متکبرش را روی زمین هم حک کرده باشند، ردپایش را پیدا نمی‌کند.", o = { "8 مدرک را در West Sanctum جمع کن.", "Digested Object را جمع کن (8)" }, p = "یعنی چه که هیچ‌کدام دفترچه را نداشته‌اند؟ این اصلا چطور ممکن است؟\nمنطق را به سخره می‌گیرد! اگر حیات وحش برنداشته، پس به خدای Twisting Nether کجا رفته؟", c = "آن نادان... آن نادان مطلق." }
WoWFQ[88979] = { t = "گرفتار در حین جرم", d = "سگ، از بین همه موجودات؟ این دزدی بود که تعقیبش می‌کردیم؟\nو حالا باید نجاتش بدهیم از یک lynx؟ واقعا این روز باری عجیب و... کلافه‌کننده‌ای گرفته است.\nبه هر حال، دفترچه را پس می‌گیریم... هرچند دل‌نگرانم این سگ واقعا سنگینی اعمالش را درک می‌کند.", o = { "Hot-Headed Lynx را در West Sanctum مغلوب کن.", "Hot-Headed Lynx را مغلوب کن", "Chewed-Up Journal را به دست بیاور" }, p = "موفق شدی دفترچه را پس بگیری؟", c = "یک سگ، یک lynx، و حالا دفترچه‌ای نابود. واقعا در عمرم مصیبت‌های کوچک‌تری دیده‌ام.\n<Meledor دفترچه آب‌دندان‌خورده را بین انگشتانش می‌گیرد.>\nبه نظر می‌رسد سرنوشت دفترچه خیلی پیش از آنکه چشم به آن بیندازیم رقم خورده بود. دیگر نجاتش ممکن نیست. باز هم اعتماد من به هر چیز غیر از دقت arcane بی‌حاصل از آب درآمد." }
WoWFQ[89193] = { t = "Arator", d = "Archbishop Alonsus Faol پیامی باقی گذاشته و خواسته با شما درباره طرحی برای کمک به Arator و Vanguard of Light صحبت کند.", o = { "با Alonsus Faol گفتگو کن." }, c = "از آمدنت ممنونم، <name>. به کمکت نیاز دارم؛ همان‌طور که بسیاری از priestها و paladinهای ما.\nیک paladin به‌ویژه." }
WoWFQ[89199] = { t = "کاری کوچک", d = "از کوتاهی در تعارفات ببخشید، چون این وضعیت نیازمند اصلاح فوری است.\nهمین بس که بدانید من Aradis هستم، wardsmith در Silvermoon. ما انجمنی از Magisterها هستیم که از دفاع‌های شهر نگهبانی می‌کنیم.\nدوره نقاهت از یک... زخم نبرد کوچک را می‌گذرانم و برای شارژ عصای wardbreaker به کمک نیاز دارم. دستمزد می‌گیرید، و شاید فرصت‌های بیشتری برای کمک به من پیش بیاید.\nجزئیات را همان حین کار در اختیارتان می‌گذارم، به شرط آنکه بیش از حد کند نباشید.", o = { "Depleted Wardbreaker را بردار، سپس با 4 مخزن arcane شارژش کن.", "Depleted Wardbreaker را بردار", "Wardbreaker را شارژ کن (4)" }, p = "لطفا wardbreaker را با دقت جابه‌جا کن. تحمل نمی‌کنم آسیب‌دیده‌اش ببینم.", c = "مفید بودن، در Silvermoon صفتی گرامی است. تو خوب پیش می‌روی." }
WoWFQ[89200] = { t = "بازکردن طلسم‌ها", d = "Dawnblaze اسناد باج‌خواهی را در اتاق کارش نگه می‌دارد. البته با طلسم‌های سنگین محافظت می‌شود.\nخود طلسم‌ها به‌طرزی مسخره ساخته شده‌اند. اما او با استفاده از conduitهای arcane که در سراسر شهر کارگذاشته، به آن‌ها توان اضافه می‌رساند. حلقه اول زنجیر را یافته و برای مطالعه به اینجا آورده‌ام.\nآن هم طلسم دارد، اما سست. این تئوری را دارم که اگر conduitها به ترتیب از کار بیفتند، سپرهای اتاق کار Dawnblaze آسیب‌پذیر می‌شوند.\nخرابکاری‌شان کن، بعد اسناد را پس بگیر. فهمیدی؟", o = { "با Wardbreaker شارژشده سپرهای محافظ 5 Warded Conduit را نابود کن.", "Warded Conduitها را خرابکاری کن (5)", "Conduitها را دنبال کن (5)", "[DNT] Kill Credit: Ward 1 را بکش", "[DNT] Kill Credit: Ward 2 را بکش", "[DNT] Kill Credit: Ward 3 را بکش", "[DNT] Kill Credit: Ward 4 را بکش", "[DNT] Kill Credit: Ward 5 را بکش" }, c = "همان‌طور که انتظار می‌رفت، تئوری‌ام درست از آب درآمد.\nتنها کاری که مانده، شکستن طلسم آخر و بیرون کشیدن آن اسناد از دست Dawnblaze است." }
WoWFQ[89201] = { t = "نقشه‌ای برتر", d = "ورودی اتاق کار Dawnblaze در تراسی درست پایین‌تر از ماست.\nاز آنجا که جادویم تا این نزدیکی به طلسم‌هایش پروجکت می‌شود، یعنی جادوی محافظ این مکان تضعیف شده... همان‌طور که پیش‌بینی کرده بودم.\nطلسم بزرگ‌تری را که ورودی را بسته است بشکن و اسنادی را که برای توهین به من جعل کرده پیدا کن. پس از آن، بازگشت سریعت را به دفترم انتظار خواهم داشت.", o = { "با Wardbreaker وارد اتاق کار Magister Dawnblaze شو، سپس Incriminating Documents را پیدا کن.", "طلسم Dawnblaze را نابود کن", "Incriminating Documents را پیدا کن" }, p = "آن اسناد را بازپس خواهم گرفت.", c = "بهتر است در ماجراجویی‌هایی که خودت را غرق می‌کنی محتاط‌تر باشی." }
WoWFQ[89202] = { t = "لانه را به هم بریز", d = "Aradis به تو گفت باج‌خواهی دروغ بود؟ البته که گفت. او برای رسیدن به جایگاه من تلاش می‌کند. این رسیدها او را نابود می‌کند.\nاو یک warlock است و ما قوانینی درباره جادوی fel داریم. ممنوع نیست، اما باید با احتیاط به کار رود. Aradis اهل احتیاط نیست. سوءاستفاده از جادو، شیاطین غیرمجاز، قاچاق fel، رشوه... فهرست جنایت‌هایش بلند است.\nاما لازم نیست حرف مرا باور کنی. Aradis در این شهر دشمنان زیادی برای خودش خریده است. اگر او را در Row پیدا کنی، مردی به نام Jaeth می‌تواند برایت همه چیز را درباره warlock عزیزمان تعریف کند.", o = { "درباره محل Jaeth از 8 Row Rat بازجویی کن.", "از Row Ratها بازجویی کن (8)", "Duplicate Documents را پیدا کن" }, c = "وقتی با نام خودم سراغم را می‌گیری، فرض می‌کنم کار خاصی داری. پس بگو دیگر." }
WoWFQ[89203] = { t = "سود دوسویه", d = "<Jaeth با تکان دادن دست، وسط حرف من را می‌پرد.>\nخیلی خب، Dawnblaze تو را فرستاده. یعنی کاری در میان است. تعجبی ندارد که نخواهد با آمدن به Row ردای‌شان را کثیف کند. این تیپ آدم‌ها هرگز نمی‌آیند.\nهر کسی که در Silvermoon آن بالاها باشد، خنجری از پشت به دیگری می‌زند. وقتی خنجری حرفی است، به ما پول می‌دهند که به جای‌شان بزنیم. آن‌ها به قدرتی که دنبالشند می‌رسند و ما سکه‌ای به اندازه یک هفته زندگی دیگر می‌گیریم.\nاین بار خنجر به پشت کی می‌رود؟", o = { "اسناد متهم‌کننده درباره Aradis را به Jaeth نشان بده.", "اسناد را به Jaeth نشان بده" }, p = "بگو دیگر. جزئیات را خالی کن.", c = "هفته پیش هم خواست کارم را تمام کند. پیش از فرارش، خنجر را به شکمش نشاند.\nتعقیبش کردم، اما مکانش آن پایین اسکله با جادوی fel طلسم شده بود. اگر Dawnblaze راهی برای داخل شدن دارد، با کمال میل کارش را تمام می‌کنم." }
WoWFQ[89204] = { t = "تخفیف پنج‌انگشتی", d = "Aradis wardbreakerش را به تو داده؟ چه آدم احمقی. این‌ها را در بازار سیاه مثل کلیدهای استادانه می‌فروشند. گران هم هستند، اما باید با جادویی که می‌خواهی بشکنی هماهنگشان کنی، و آن کار راحتی نیست.\nبه نظر می‌رسد مال تو خالی است. این را می‌شود حل کرد. اگر چند وسیله جادویی گران‌بها از اطراف شهر بدزدیم، رفیقم آن بالا می‌تواند از قدرتشان بگیرد و wardbreaker را با جادوی fel پر کند.\nآن موقع Aradis دیگر جایی برای قایم شدن ندارد.", o = { "به Jaeth کمک کن وسایل جادویی را از مغازه‌های Bazaar بدزدد.", "ارتقاها در انتظارند", "آهنگری در انتظار است", "کالاهای عمومی در انتظارند", "حواس Lendranil را پرت کن", "Thrumming Amulet را بردار", "حواس Lothene را پرت کن", "Basket of Spell Reagents را بردار", "حواس Belil را پرت کن", "Arcane Sword را بردار" }, p = "این بخش آسان ماجراست.", c = "تمیز و بی‌نقص. از بچگی برای گذران زندگی دزدی کرده‌ام، اما زیاد پیش نمی‌آید که شریک جرم داشته باشم." }
WoWFQ[89205] = { t = "تراشیدن کلید", d = "همه ماجرا را برای Zanien تعریف کردم. او مدت‌هاست warlock تربیت می‌کند--و اگر کسی از ناسازها متنفر باشد، اوست.\nمطمئن است می‌تواند wardbreaker را دوباره شارژ کند. دستورهایش را دنبال کن و بعد از آن باید آماده راه افتادن باشیم.", o = { "Wardbreaker را با جادوی fel هماهنگ کن.", "Wardbreaker را جایگذاری کن", "Thrumming Amulet را جادوزدایی کن", "Arcane Sword را جادوزدایی کن", "Spell Reagents را جادوزدایی کن", "Recharged Wardbreaker را بردار" }, p = "آن عصا حالا باید بتواند این طلسم را بشکند.", c = "تعجب می‌کنم اگر Aradis همین حالا در همین‌جا سنگر نگرفته نباشد. اما اگر نیست، مطمئنم به‌زودی می‌بینیمش.\nطلسم‌های این‌قدر مجلل همیشه زنگ خطر در دل‌شان بافته‌اند." }
WoWFQ[89206] = { t = "شکستن در و ورود", d = "صدایش را می‌شنوی؟ به نظر از طبقه پایین می‌آید. انگار کسی در رنج است.\nآخرین ربودن از Row تازه بوده. شاید اینجا جایی است که آدم‌های ربوده‌شده را نگه می‌دارد.\nآدم‌های من. دوستانم.\nحتی اگر Aradis رخ نشان ندهد، نمی‌گذاریم آن‌ها را اینجا نگه دارد. این طلسم را بینداز. وارد می‌شویم.", o = { "طلسم fel محافظ اتاق خصوصی Aradis را نابود کن.", "طلسم fel را نابود کن", "Soul Shardها را نابود کن (6)" }, p = "داریم بیرونش می‌آوریم.", c = "<Jaeth نبض گردن Sarvi را می‌گیرد و بعد با خشم آه می‌کشد.>\nدیگر رفته است. برادرش را می‌شناسم. حله می‌کنم او را به برادرش برگردانند.\nاما اول، کاری می‌کنیم Aradis خون بدهد." }
WoWFQ[89207] = { t = "موش هم گاز می‌گیرد", d = "همه این آدم‌ها را می‌شناسم. کارگرند، نه جنگاور. Aradis به سراغ کسانی رفته که نمی‌توانند از خودشان دفاع کنند. برای همین وقتی خواست مرا ببرد و فهمید هدف اشتباهی را برگزیده، پا به فرار گذاشت.\nبعد از این همه سروصدا، حتما فهمیده که اینجاییم.\nمراقب باش. تا رخ نشان داد، مرد.", o = { "Magister Aradis را بکش.", "Magister Aradis را بکش" }, c = "تا وقتی Silvermoon چشمش را بر ما می‌بندد، Row همیشه در خطر است.\nاما فعلا، کمی امن‌تریم. خوش بیاید که رفت." }
WoWFQ[89208] = { t = "آنچه به ما بدهکارند", d = "همه کسانی که این بیرون‌اند باید سالم باشند. Sarvi... خودم برمی‌گردانمش به Row. اگر اینجا رهایش کنیم، نگهبانان فقط جسدش را می‌برند دور.\nکاش همین کار را با Aradis هم بکنند، اما مطمئنم نمی‌کنند.\nبرویم. برویم پیش Dawnblaze و حقمان را بگیریم. جایش را یادم است.", o = { "به Magister Dawnblaze خبر بده که کار تمام شد.", "به Dawnblaze خبر بده کار تمام شد", "به Approach نزدیک شو" }, p = "می‌بینم که قاتل عزیزمان را به خدمت گرفتی. خوب بود.", c = "کار کردن با شما لطف داشت، <name>." }
WoWFQ[89276] = { t = "خوراکی Light", d = "کلاسیک‌ها به یک دلیل کلاسیک‌اند، عزیزم. آدم نمی‌تواند بدون گزینه‌ای درست‌وحسابی از mana برای مهمان‌هایش، میزبانی درخور بکند.\nMagisterها می‌توانند بیاورند، اما mana تازه‌مکیده بهتر است. mana wyrmهای جنوب Eversong درخششی فربه و دلفریب دارند که من به‌خصوص دوستش دارم.\nلطف کن و مقداری برایمان بگیر.", o = { "از 6 Scintillant Wyrm در Tranquil Repose جادو بکش.", "Scintillant Wyrmها را مکش (6)" }, p = "وقت طلاست، عزیزم.", c = "آه، همین عالی است." }
WoWFQ[89277] = { t = "روشن کردن فضا", d = "عشق Saltheril عزیزمان به چراغ‌های قدیمی را می‌فهمم، اما طلسم روشنایی‌ای که به کار برده برای چنین مناسبت باشکوهی بیش از حد عوامانه است.\nMagisterهای من می‌توانند طلسمی خیره‌کننده‌تر بسازند. فقط مقداری الیاف از Lightbloom برایم جمع کنی تا تبدیل‌شان کنم به مواد جادویی.\nاثرش حیرت‌انگیز خواهد بود.", o = { "8 Luminous Fiber از موجودات اطراف Lightbloom Ath'Ran جمع کن.", "Luminous Fibers را جمع کن (8)" }, p = "فقط مقدار کمی لازم داریم. کار جادویی‌مان به‌شدت بهینه است.", c = "خوب بود، عزیزم. Haven به‌زودی می‌درخشد." }
WoWFQ[89278] = { t = "مواظب وظیفه‌مان", d = "هرچند دربار وقت‌مان را می‌گیرد، وظایف را نمی‌توانیم فراموش کنیم. مهمان‌هایمان راحت‌تر به شادمانی می‌پردازند اگر مطمئن باشند دفاع‌های Eversong استوار است.\nMagisterها موظف‌اند سنگ‌نوشته‌های سراسر Eversong را نگه دارند. لطفا برایمان بررسی‌شان کن و اگر طلسمی نیاز به توجه دارد خبرمان کن.", o = { "استواری 4 طلسم سنگ‌نوشته را در اطراف Eversong Woods بررسی کن.", "طلسم‌های سنگ‌نوشته را بررسی کن (4)", "NPC #242987 را بکش", "NPC #242988 را بکش", "NPC #242989 را بکش", "NPC #242990 را بکش" }, c = "عزیزم، چه وسواس دلپذیری. به دربار اطمینان می‌دهم که هیچ‌چیز جز ترس نیازشان نیست." }
WoWFQ[89289] = { t = "لطف دربار", d = "آه، <name>، <class> محبوب من! از دیدنت دوباره خوشحالم.\nاستعداد ذاتی‌ای برای این‌جور مراسم‌ها داری. اشراف از حضورت خرسندند و لطفت دارد خزانه‌شان را می‌گرداند.\nبگذار کار خوب را همان‌طور پیش ببریم، شود؟ کمکم کن یکی از متحدان نمایندگانمان را انتخاب کنی تا این هفته به Haven دعوتش کنی. کنجکاوم ببینم چه نمایشی به پا می‌کنی.\nبه‌عنوان مهمان ویژه شخصی من، لطفت دنباله لطف من دیده می‌شود.", o = { "متحدی از Magisterها، Blood Knightها، Farstriderها یا Shades of the Row انتخاب کن تا این هفته به Soiree ی Saltheril دعوتش کنی.\nانتخاب تو تعیین می‌کند این هفته کدام فراکسیون \"Fortify the Runestones\" را به Warband شما پیشنهاد می‌دهد.", "دعوت‌نامه انتخاب شد" }, p = "محتاط باش، همیشه. sin'dorei از بسیاری ظرافت‌ها برآشفته می‌شوند.", c = "انتخابی عالی.\nهمین حالا پیش‌خدمتم را می‌فرستم دنبالشان." }
WoWFQ[89383] = { t = "یک جوجه ماجراجو", d = "یکی از جوجه‌هایم وقتی آن سازه غول‌پیکر از کنار مرغداری گذشت از ترس فرار کرد! پیش از آنکه جلویش را بگیرم، از حصار پرید بیرون و به جنگل زد!\nکوچک و تند است و حتما همین حوالی قایم شده. لطفا پیش از هر چیز دیگری پیدایش کن و برگردان پیش من.", o = { "Hawkstrider Fledgling گمشده را در Stillwhisper Pond پیدا کن.", "Hawkstrider Fledgling برگردانده شد" }, p = "جوجه را پیدا کردی؟", c = "خوب بود، <name>. حصار را محکم‌تر می‌کنم تا دیگر فرار نکند." }
WoWFQ[89384] = { t = "گله‌ای گرسنه", d = "بعضی‌ها فکر می‌کنند پرورش hawkstrider کار آسانی است، اما قطعا چنین نیست. اشتها و سلیقه‌های hawkstriderها بدنام‌انه بدسلیقه است!\nبیشتر وقت‌ها به هرچه پیششان بگذارم منقار بالا می‌کنند. اما این موقع از سال؟ ران قورباغه. عاشق این چیزهای لیز بودند. نمی‌توانند ازشان بگذرند!\nهمان پایین تپه، برکه‌ای است که مملو از همین خوراکی‌های پالنگی است. می‌شود لطفا برایم مقداری بگیری؟", o = { "ران قورباغه از Gloombelly Toadهای Stillwhisper Pond جمع کن.", "Juicy Frog Leg را جمع کن (6)" }, p = "قورباغه‌ای پیدا نکردی؟ hawkstriderها گرسنه‌اند!", c = "گفته‌اند ران قورباغه مزه‌ای بین ماهی و مرغ دارد. من... به نظرم این تجربه میزبان خوب را به hawkstriderها واگذار می‌کنم. ممنون از کمکت!" }
WoWFQ[89385] = { t = "نخستین قدم در والدگری", c = "نه همه کسانی چنین پایایی برای این موجودات نشان می‌دهند.\nدوست دارم چیزی ویژه به‌عنوان قدردانی از کمکت به تو بدهم. به نظرم بیش از حد ثابت کرده‌ای که می‌توان به تو سپردش.\nیک تخم hawkstrider. هنوز نشکفته، اما یک موجود کوچک درونش است--پیچ‌وتاب می‌خورد، کنجکاو است و مشتاق دیدار کسی که با عشق بزرگش می‌کند. از او مراقبت کن، و او هم به‌خوبی از تو مراقبت خواهد کرد." }
WoWFQ[89386] = { t = "تحولی در آشیانه", d = "hawkstrider راحت یعنی hawkstrider خوشحال. انتظار نداریم تمام روز بایستند. جای دنجی برای آشیانه‌کردن می‌خواهند!\nگیاهی است به نام golden sunleaf که پشت همان برآمدگی می‌روید. نرم‌ترین فرش بستر را می‌سازد--hawkstriderها عاشقش‌اند. می‌شود برایم مقداری جمع کنی؟", o = { "Golden Sunleaf را در Stillwhisper Pond جمع کن.", "Golden Sunleaf را جمع کن (6)" }, p = "golden sunleaf را پیدا کردی؟", c = "آه، شب‌های خواب خوشی پیش‌رو دارند با این! از تو ممنونم." }
WoWFQ[89388] = { t = "Voidstorm", d = "Magister Umbric نقشه‌ای برای نفوذ به Voidstorm و درگیر کردن مستقیم نبرد با Devouring Host دارد.\nکار آسانی نیست و تیمی کوچک اما نیرومند جمع می‌کند تا به قلب دشمن بزنند.", o = { "در Sanctum of Light در Silvermoon با Magister Umbric صحبت کن." }, c = "امیدوارم برای چالش آماده باشی. این کار آسانی نخواهد بود." }
WoWFQ[89402] = { t = "Harandar", d = "در حالی که Devouring Host بیشتر وقت و توجه ما را گرفته، پشت‌مان بی‌پوشش مانده به تهدیدهای کمین‌کرده. این Lightbloom که Eversong را آلوده کرده روز به روز بدتر می‌شود. اگر از کنترل خارج شود، شاید درگیر جنگ دو جبهه‌ای شویم--یا بدتر، در حالی که سرمان به Void گرم است، خانه‌مان را قورت بدهند.\nآن زن عجیبی که وسط Lightbloom می‌گشتی... به نظر با او آشنایی. پیدایش کن. شاید پاسخ‌هایی داشته باشد.", o = { "در Fairbreeze Village با Orweyna صحبت کن." }, c = "خوشحالم که دوباره می‌بینمت، دوست من.\nکاش در شرایطی کمتر پریشان دیدار کرده بودیم." }
WoWFQ[90493] = { t = "قلب Tranquillien", d = "نمی‌گذاریم Twilight's Blade این کار را بی‌پاسخ بگذارد. شهروندان بی‌گناهی در سراسر شهر هستند که هیچ ربطی به این فرقه نداشتند. حرف فرماندار را شنیدی: هر کس نپیوندد، اعدام می‌شود.\nمن این را برنمی‌تابم.\nبرو--به هر شهروندی که می‌توانی کمک کن. از میدان خطرشان بیرون بکش. اگر به آن‌ها حمله می‌شود، مهاجم را زمین بزن. تا من اینجام، Tranquillien سقوط نمی‌کند.", o = { "8 شهروند بی‌گناه Tranquillien را نجات بده.", "شهروندان Tranquillien را نجات بده (8)" }, c = "تو امن هستی، و شهروندان خسته‌جان Tranquillien هم. خدا را شکر که Light این‌چنین می‌سازد." }
WoWFQ[90494] = { t = "Magister گمشده", d = "Umbric وقتی درگیری بالا گرفت رفته Antenorian را دنبال کند، اما از آن موقع هیچ‌کس او را ندیده است.\nاعتماد دارم از پس خودش بربیاید، اما میان مرگ Kasiea و خیانت Antenorian، می‌ترسم آن‌قدر به انتقام فکر کند که اگر تیغی از راه برسد نبیند. می‌شود برایم پیدایش کنی؟\nمن همین‌جا می‌مانم تا مطمئن شوم این شهروندان در امنیت می‌مانند.", o = { "Magister Umbric را پیدا کن.", "Umbric را پیدا کن", "Secretary Faloria را بکش", "Jeweled Key را بردار", "Plans of Infiltration را بردار", "Spare Pamphlets را بردار" }, p = "نمی‌گذارم از این کارشان بگذرند.", c = "نقشه‌ای از Eversong؟ با نشانه‌گذاری چندین روستا به دست Twilight's Blade!" }
WoWFQ[90509] = { t = "خائنان Tranquillien", d = "برخی از محترم‌ترین شهروندان شهر، خائن؟\nTwilight's Blade از کی اینجاست؟ چند دیده‌بان گم شده؟ چند جنایت گزارش نشده مانده؟ چند بی‌گناه به دست کسانی که به‌شان اعتماد داشتند، به خدمت گرفته شده؟\nباید جلویشان گرفته شود. خائنان را از پا درآور. نشان‌شان بده که Tranquillien خانه فرقه‌گرایان نیست.", o = { "Ranger Lethvalin، Matron Narsilla و Guard Captain Leonic را از پا درآور.", "Ranger Lethvalin را بکش", "Matron Narsilla را بکش", "Guard Captain Leonic را بکش" }, p = "نمی‌گذاریم این خائنان جان سالم به در ببرند!", c = "برای جبران خرابکاری این‌جا کارهای بیشتری لازم است، اما این قدم خوبی بود. ممنونم." }
WoWFQ[90544] = { t = "دزد به دنبال پارس", d = "<Luma روبرویت ایستاده، گوش‌ها هوشیار، سپاسگزار کمکت.\nپارس کوتاهی می‌کند، دمش یک بار تکان می‌خورد و چند قدم جلو می‌رود، بعد می‌ایستد.\nبرمی‌گردد و منتظر می‌ماند. زبان بدنش التماس می‌کند: \"برویم، دنبالم بیا!\">", o = { "دنبال Luma برو.", "دنبال Luma برو" }, p = "<Luma به نظر می‌رسد که منتظر تایید و رضایت توست.>", c = "<Luma پاداش کوچکی را در دست تو می‌گذارد، انگار که از کمکت قدردان است.\nشاید دیگر جای نگرانی از این‌همه دزدی در توده گنج‌ها نباشد.>" }
WoWFQ[90546] = { t = "paladinهای گمشده", d = "چند تن از برادران و خواهرانمان در Light به درخواست کمک Magisterها در Sanctum of the Moon پاسخ داده بودند. به ظاهر Twilight's Blade در آن حوالی دیده شده است.\nمنتظر خبرشان بودیم، اما هیچ خبری نشده.\nبا توجه به توان گروهی که رفته بود، من و Salandria خواستیم پیش از بررسی ماجرا کمی نیروی کمکی داشته باشیم. دستی می‌رسی؟", o = { "در Sanctum of the Moon به Taelia بپیوند." }, c = "خب، فرقه‌گرایان دیگر مخفی‌کاری نمی‌کنند. اما از paladinهای گمشده ما خبری نیست." }
WoWFQ[90547] = { t = "paladinهای گمشده", d = "چند تن از برادران و خواهرانمان در Light--از جمله دوستم Dawnheart--به درخواست کمک Magisterها در Sanctum of the Moon پاسخ داده بودند. به ظاهر Twilight's Blade در آن حوالی دیده شده است.\nمنتظر خبرشان بودیم، اما هیچ خبری نشده.\nبا توجه به توان گروهی که رفته بود، من و Taelia خواستیم پیش از بررسی ماجرا کمی نیروی کمکی داشته باشیم. دستی می‌رسی؟", o = { "در Sanctum of the Moon به Salandria بپیوند." }, c = "فرقه‌گرایان به‌طرزی پررو خودشان را نشان می‌دهند، اما از Dawnheart و بقیه خبری نیست." }
WoWFQ[90548] = { t = "نامه Twilight", d = "باید بفهمیم Twilight's Blade اینجا دنبال چیست. همچنین باید از این فرقه‌گرایان خلاص شویم تا Magisterها بتوانند به کار ساختن سنگ‌نوشته‌ها برگردند.\nهر فرقه‌گرایی که می‌توانی از پا درآور. ببین کدام‌شان اطلاعاتی قابل استفاده دارند.", o = { "6 نامه جمع کن.", "Twilight's Blade Missive را جمع کن (6)" }, p = "چه یافتی؟", c = "خوب انجامش دادی. اگر بخواهیم دوستان گمشده‌مان را پیدا کنیم، باید بیشتری بیابیم." }
WoWFQ[90549] = { t = "نشانه‌های کشمکش", d = "Twilight's Blade در تصرف این‌جا به‌طرزی پررو عمل می‌کند. هیچ‌کدام از این Magisterها اطلاعاتی برایمان ندارند.\nما این سمت پل را نگه می‌داریم و از هر Magistری که فرار کند محافظت می‌کنیم. تو برو آن‌جا و دنبال نشانه‌هایی از paladinهای گمشده بگرد. آیا ربوده شده‌اند؟ جنگیدند یا غافلگیر شدند؟ هنوز سلاح دارند؟\nحس بدی دارم؛ وقت کم داریم.", o = { "دنبال نشانه‌هایی از paladinهای گمشده بگرد.", "سلاح‌ها را پیدا کن", "Kill Credit: Collect Sword را بکش", "Kill Credit: Collect Shield را بکش", "Kill Credit: Collect Shield 2 را بکش", "Kill Credit: Collect Shield 3 را بکش", "Kill Credit: Collect Sword 2 را بکش", "Kill Credit: Collect Mace 1 را بکش" }, p = "نشانه‌ای از paladinهای گمشده پیدا کردی؟", c = "خب، چیزهای بیشتری می‌دانیم. یک مدتی اینجا بودند اما بی‌سلاح ربوده شده‌اند. حالا باید بفهمیم به کجا بردندشان." }
WoWFQ[90550] = { t = "خورشیدی ماتم‌زده", d = "<جسد این Blood Knight به‌طرز فجیعی مثله و به جادوی Void آلوده شده است. جنگید، اما نتوانست جان به در ببرد.\nSalandria باید از این باخبر شود.>", o = { "جسد را به Salandria گزارش کن." }, c = "این خوک‌ها... تاوان مرگ Sombersun را خواهند داد!" }
WoWFQ[90551] = { t = "اطلاعات اسیر", d = "باید بفهمیم paladinها را به کجا بردند. ساده‌ترین راه این است که بپرسیم... البته کمی تحت فشار.\nهدفی خلوت پیدا کن، زمینش بزن، و بعد بکشش به گودال آن‌سوی Sanctum. من و Taelia شهروندان را به امنیت می‌رسانیم و همان‌جا به تو می‌پیوندیم.", o = { "یک فرقه‌گرای خلوت را به دام بینداز و به Hollow Grove ببر.", "Isolated Shadecaster را به دام بینداز", "فرقه‌گرا را به Hollow Grove برسان" }, p = "فرقه‌گرایی به دام انداختی؟", c = "خوب است. حالا می‌توانیم چند پاسخ بیرون بکشیم." }
WoWFQ[90552] = { t = "بازجویی", d = "باید بفهمیم Dawnheart و بقیه را به کجا بردند. این یکی به نظر حرف نمی‌زند... اما چاره‌اش داریم.", o = { "از فرقه‌گرای اسیر بازجویی کن.", "با Salandria صحبت کن تا آغاز شود", "از اسیر بازجویی کن", "Kill Credit: Punch را بکش (7)", "Kill Credit: Threaten را بکش (7)", "Kill Credit: Persuade را بکش (7)", "15%", "30%", "45%", "60%", "75%", "90%" }, p = "مطمئنی باز هم کمی فشار لازم نیست؟", c = "Ruins of Deatholme. بهتر است تا رسیدنمان زنده باشند!" }
WoWFQ[90553] = { t = "پایان تیغه‌ها", d = "این هیولاها باید تاوان کارهایشان را بدهند!\nهر فرقه‌گرای Twilight's Blade که می‌بینی از پا درآور. برای همیشه Eversong را از آن‌ها پاک می‌کنیم!", o = { "15 فرقه‌گرا را بکش.", "فرقه‌گرایان را بکش" }, p = "برایشان رحم نکن!", c = "Eversong را از کثافاتشان پاک کردیم." }
WoWFQ[90554] = { t = "خاکستر در ردپایت", d = "باید به این فرقه‌گرایان بفهمانیم که این‌جا جای آن‌ها نیست.\nپرچم‌هایشان را برکن و کتاب‌ها و آذوقه‌شان را نابود کن. هر کاری از دستت برمی‌آید برای نابود کردن اردوگاهشان بکن!", o = { "اردوگاه Twilight's Blade را در Deatholme ویران کن.", "اردوگاه را ویران کن", "Kill Credit: Destroy Banner را بکش (13)", "Kill Credit: Destroy Large Book را بکش (13)", "Kill Credit: Destroy Weapon Rack را بکش (13)", "Kill Credit: Destroy Crate را بکش (20)" }, p = "اردوگاه را نابود کردی؟", c = "خوب بود. حتی اگر خزیده برگردند، چیز زیادی پیدا نمی‌کنند." }
WoWFQ[90555] = { t = "نعمت آزادی", d = "دوستانمان در همین حوالی نگه داشته شده‌اند. نمی‌دانیم در چه حالی‌اند، اما دعا می‌کنم دست‌کم زنده باشند.\nبه من کمک کن paladinهای گمشده‌مان را در Ruins of Deatholme پیدا کنم و آزادشان کنم.", o = { "paladinها را در Ruins of Deatholme آزاد کن.", "Sunwalker Atohmo را نجات بده", "Archivist Colin را نجات بده", "Crusader Flaresong را نجات بده", "Crusader Lightspear را نجات بده", "Crusader Newbery را نجات بده", "Crusader Whitney را نجات بده", "Bloodknight Ithelis را نجات بده", "Motega Firemane را نجات بده", "Crusader Dawnheart را نجات بده" }, p = "همه را پیدا کردی، <name>؟", c = "با همه این حرف‌ها، نتیجه خوبی بود. کاش... خب. نتوانستیم همه را نجات دهیم، اما بیشترشان نجات پیدا کردند. فکر کنم در چنین وضعیتی همین هم برای هر کسی کافی است." }
WoWFQ[90556] = { t = "قطع کردن سر", d = "رهبرشان را در هم می‌شکنیم! به نام عدالت و Light!", o = { "Overseer Mognak را بکش.", "Overseer Mognak را بکش", "paladinهای نجات‌یافته را بیرون Deatholme دیدار کن" }, p = "انشاالله دیگر نسلشان به این حوالی سر نزند!", c = "برای گمشده‌ها عزاداری می‌کنیم و برای جان‌به‌دربردگان جشن می‌گیریم. ممنونم، <name>." }
WoWFQ[90570] = { t = "به ویرانه‌های Deatholme", d = "به لطف این \"دوست\"مان، می‌دانیم paladinهای گمشده به Deatholme برده شده‌اند. باید پیش از آنکه دیر شود پیدایشان کنیم!\nمن و Salandria همان‌جا به تو می‌پیوندیم.", o = { "در Deatholme با Taelia و Salandria دیدار کن." }, c = "خوب--رسیدی. حالا برویم paladinها را نجات دهیم." }
WoWFQ[90573] = { t = "مستحکم کردن سنگ‌نوشته‌ها: Magisterها", d = "تعدادی سنگ‌نوشته در سراسر Eversong Woods کار گذاشته‌ایم؛ هر یک با جادوی arcane محافظ شارژ شده تا از Lightbloom بکاهد.\nهرچند بسیار مؤثرند، سنگ‌نوشته‌ها برای کارکردن به قدرت عظیمی نیاز دارند. باید مرتب با latent arcana تغذیه شوند وگرنه سست می‌شوند.\nما Magisterها موظفیم از سنگ‌نوشته‌ها نگهداری کنیم--به‌ویژه وقتی چشم این Haven به ما است. قدرت arcane‌شان را دوباره شارژ کن و ازشان در برابر تهدیدها دفاع کن.", o = { "Latent Arcana را از مأموریت‌های هفتگی Soiree ی Saltheril و Misplaced Tomeها جمع کن، سپس با آن یک Runestone در Eversong Woods را شارژ و از آن دفاع کن.", "Latent Arcana از Misplaced Tomeها جمع شد", "سنگ‌نوشته دفاع شد", "تعداد پیشنهادی بازیکنان: 5" }, p = "باید مطمئن شویم سنگ‌نوشته‌ها شارژ و محافظت می‌شوند.", c = "قدرت تو را فقط تیزی ذهنت پایه دارد، عزیزم. حله می‌کنم همه بدانند امروز چه شاهکار کردی." }
WoWFQ[90574] = { t = "مستحکم کردن سنگ‌نوشته‌ها: Blood Knightها", d = "Magisterها تعدادی سنگ‌نوشته در سراسر Eversong Woods کار گذاشته‌اند؛ هر یک با جادوی arcane محافظ شارژ شده تا از Lightbloom بکاهد.\nالبته سنگ‌نوشته‌ها برای کارکردن به قدرت عظیمی نیاز دارند. می‌توان با latent arcana تغذیه‌شان کرد، اما همین قدرت دشمنانی را می‌کشد که دنبال تصاحبش‌اند.\nما Blood Knightها موظفیم از سنگ‌نوشته‌ها دفاع کنیم--به‌ویژه وقتی چشم این Haven به ما است. قدرت arcane‌شان را شارژ کن و ازشان در برابر تهدیدها دفاع کن.", o = { "Latent Arcana را از مأموریت‌های هفتگی Soiree ی Saltheril و Coalesced Light جمع کن، سپس با آن یک Runestone در Eversong Woods را شارژ و از آن دفاع کن.", "Latent Arcana از Coalesced Light جمع شد", "سنگ‌نوشته دفاع شد", "تعداد پیشنهادی بازیکنان: 5" }, p = "نگهداری از امنیت Eversong اهمیتی حیاتی دارد.", c = "کارهایت برایمان افتخار دارد، <name>. امروز خوب جنگیدی." }
WoWFQ[90575] = { t = "مستحکم کردن سنگ‌نوشته‌ها: Farstriderها", d = "Magisterها چند سنگ‌نوشته در سراسر Eversong کار گذاشته‌اند؛ هر یک با جادوی arcane شارژ شده که از Lightbloom جلوگیری کند.\nمطمئنا حدس زده‌ای: سنگ‌نوشته‌ها برای کارکردن به قدرت هنگفتی نیاز دارند. Magisterها با latent arcana تغذیه‌شان می‌کنند، اما این جور قدرت‌ها خیلی حواس‌ها را پرت می‌کنند. حواس بد.\nما Farstriderها موظفیم از Eversong در برابر چنین تهدیدهایی دفاع کنیم--به‌ویژه وقتی Haven به ما چشم دوخته. برو سنگ‌نوشته‌ها را شارژ کن و هر چه جلویت را گرفت در هم بشکن.", o = { "Latent Arcana را از مأموریت‌های هفتگی Soiree ی Saltheril و Ranger's Cacheها جمع کن، سپس با آن یک Runestone در Eversong Woods را شارژ و از آن دفاع کن.", "Latent Arcana از Ranger's Cacheها جمع شد", "سنگ‌نوشته دفاع شد", "تعداد پیشنهادی بازیکنان: 5" }, p = "باید این سنگ‌نوشته‌ها را امن نگه داریم.", c = "خوب بود. می‌دانی چطور مأموریتی را سر و ته می‌کنند. چند تازه‌کار ranger دارم که می‌توانند از تو چیزهایی بیاموزند." }
WoWFQ[90576] = { t = "مستحکم کردن سنگ‌نوشته‌ها: Shades of the Row", d = "سنگ‌نوشته‌های توی Eversong را دیده‌ای؟ خرس‌های سنگی مملو از جادوی arcane که Lightbloom را دور نگه می‌دارند.\nمن اهل جادو نیستم، اما فرصت را که ببینم می‌شناسم. این سنگ‌نوشته‌ها برای کارکردن به قدرت زیادی نیاز دارند. اگر کمکشان کنیم شارژ بمانند، خیلی‌ها به ما بدهکار می‌شوند--و لطف از طلا هم باارزش‌تر است.\nنقشه این است: من مقداری latent arcana برایت جور می‌کنم، تو می‌ریزی تو سنگ‌نوشته‌ها، هر چه جلویت را گرفت کتک‌کاری می‌کنی، بعد در تجلیل‌ها می‌خوابیم. معامله‌ایم؟", o = { "Latent Arcana را از مأموریت‌های هفتگی Soiree ی Saltheril و Dead Dropها جمع کن، سپس با آن یک Runestone در Eversong Woods را شارژ و از آن دفاع کن.", "Latent Arcana از Dead Dropها جمع شد", "سنگ‌نوشته دفاع شد", "تعداد پیشنهادی بازیکنان: 5" }, p = "سنگ‌نوشته‌ها که خودشان را شارژ نمی‌کنند.", c = "ها! تعجب نمی‌کنم که انقدر قشنگ از پسش برآمدی، اما باز هم. همین حالا هم آدم‌ها به ما مثل معجزه‌گران نگاه می‌کنند.\nهمه‌اش به لطف تو، <name>." }
WoWFQ[90669] = { t = "طلا طلاست", d = "هی! تو، همان‌جا.\n<Sarvi با اشاره تو را نزدیک‌تر می‌کشد و صدایش را پایین می‌آورد.>\nدنبال کاری؟ یک Magister پنج سکه طلا به من داد تا یک ماجراجو پیدا کنم برای کاری. گفت اگر کار انجام شود، پنج تای دیگر می‌دهد. ماه‌ها با این غذا می‌خورم.\nتو همان می‌خواهی. اگر می‌خواهی تو هم مزد بگیری، اتاق کارش آن‌طرف‌ترهای بندر است. جای مقلب و درخشانی است--از دستش نمی‌دهی. اسمش هم Aradis است.", o = { "در اتاق کارش نزدیک Silvermoon Harbor با Magister Aradis صحبت کن." }, c = "آه، پس آن اراذل موفق شد.\nقطعا با کفایتی به نظر می‌رسی. حرف بزنیم، شود؟" }
WoWFQ[90818] = { t = "Murder Row: زبان‌های بی‌پرده", d = "حس بوی fel در این حوالی چندان دور از انتظار نیست. هنوز warlockهایی در شهر هستند و اتاق‌های مکش قدیمی fel. اما شواهدی که یافته‌ام از این حرف‌ها بیشتر است. حس... متفاوتی دارد. آشوبناک.\nاین کار باید گسترده باشد، یعنی کسی دارد حرفش را می‌زند.\nمن آن‌قدر در جست‌وجو بوده‌ام که دیده شدنم قطعی است، اما شاید تو بتوانی بی‌سروصدا به چند گپ‌وگفت عادی در شهر گوش بسپاری. اگر چیز مفیدی فهمیدی، پیش من بیاور.", o = { "در اطراف Royal Exchange به 3 گفتگو گوش بسپار.", "اطلاعات جمع شد (3)", "شنود از اشراف", "شنود از شاگردها", "شنود از دربدها" }, p = "آدم‌ها وقتی فکر می‌کنند کسی نمی‌شنود، خیلی چیزها را لو می‌دهند.\nهیچ‌وقت مطمئن نباش که کسی نمی‌شنود.", c = "<اخم Belath از حالت همیشگی‌اش هم اخموتر می‌شود.>\nترس آدم‌ها را به کارهای نومیدانه می‌کشاند، اما جادوی fel سلاحی نیست که سبک از آن گذشت.\nاین قدرت بهایی دارد که آن‌ها نمی‌فهمند--و برای در تاب آوردن خطراتش هم آموزش ندیده‌اند." }
WoWFQ[90819] = { t = "Murder Row: بازی کردن نقش", d = "بر اساس یافته‌هایمان، گمان می‌کنم fel از Murder Row می‌آید. کسی آن‌جا یادگاری‌های Legion را می‌شکند و جادو را داخل mana wyrmها می‌ریزد برای مکیدن پنهان--و مردم هم مثل دست‌فروش می‌خرندش.\nباید بفهمیم آن کیست.\nاین wyrm core را ببر توی Row و دنبال بیشترش بگرد. وعده سکه باید راهت به حرف کسی درست بیندازد.", o = { "Cracked Wyrm Core را ببر، سپس در Murder Row جست‌وجو کن و سرچشمه wyrmهای fel قاچاقی را پیدا کن.", "Cracked Wyrm Core را بردار", "از تاجران Murder Row بازجویی کن (3)", "Smugglers 1", "Rogues 2", "Soothsayers 3", "Smuggler's Signet را بردار", "Soothsayer's Signet را بردار", "Rogue's Signet را بردار", "Den of Indulgence پیدا شد", "Vira پیدا شد", "با Vira صحبت کن", "Shipping Manifest را بردار" }, p = "اهالی Murder Row سخت‌گیرند، اما هر اطلاعاتی که به دست بیاوریم گران‌بهاست.", c = "گفت کسی به نام Zaen؟\nاو اراذل معروف Row است. قاچاق fel از راه Silvermoon Harbor دقیقا به سبک اوست. دوست ندارد کسی مراقبش باشد.\nخوب بود که آن shipping manifest را برداشتی." }
WoWFQ[90821] = { t = "Murder Row: رازهای پنهان در بندر", d = "آن manifest مهر Silvermoon Harbor را دارد. به نظر می‌رسد Zaen قاچاقچیانش را در بندر گذاشته تا محموله‌های fel relicهایش از بازرسی بگذرند.\nاگر خط آذوقه‌شان را در بندر قطع کنیم، تا Zaen را پیدا و کارش را برای همیشه تمام کنیم، عملیات fel می‌ایستد. تا آن موقع رفتن سراغ واسطه‌ها بیهوده است.\nفریب تا اینجا ما را کشاند؛ پس ادامه‌اش می‌دهیم. به بندر برو و بگو محموله Zaen را می‌آیی بردار. از همان‌جا پیش می‌رویم.", o = { "با dockmaster در Silvermoon Harbor حرف بزن و محموله fel relicهای Zaen را تحویل بگیر.", "در بندر به Belath بپیوند", "با dockmaster صحبت کن", "Folded Receipt را بردار", "Dockworker آزاد شد" }, p = "Zaen مغز متفکر این ماجراست، یا دست‌کم به نظر می‌رسد. برای پایان واقعی این نقشه باید با او درگیر شویم.\nقطع خط felشان در بندر جلوی بدتر شدن اوضاع را می‌گیرد تا پیدایش کنیم.", c = "\"Illicit Rain\"؟ شاید پایگاه عملیاتی Zaen.\nآن رسید از Suramar حرف می‌زند. پس fel relicها باید از Broken Isles دزدیده و از راه خط تجاری‌ای که کسی گمانش را نمی‌کند به Silvermoon کشیده می‌شوند.\nزیرکانه است." }
WoWFQ[90822] = { t = "Murder Row: با یک ضربه fel", d = "همه تکه‌های پازل را داریم. Zaen fel relicها را از Broken Isles قاچاق می‌کند، با پر کردن Silvermoon Harbor از قاچاقچیان خودش. relicها در Murder Row پردازش می‌شوند، بعد جادوی fel داخل mana wyrmها تزریق می‌شود برای فروش و مکیدن.\nعملیاتی این‌قدر پیچ‌درپیچ حیرت‌انگیز بود اگر اهدافش این‌قدر بی‌محابات نبود. Zaen از ترس مردم می‌خورد. برایش مهم نیست که کی را بالا می‌کشد و کی را له می‌کند، تا طلای بیشتری به جیبش برود.\nپایانش بدهیم. Illicit Rain را در Murder Row پیدا می‌کنیم و پاکش می‌کنیم.", o = { "عملیات قاچاق fel داخل Murder Row را متلاشی کن.", "عملیات قاچاق fel در Murder Row را متوقف کن" }, p = "به نظر می‌رسد از زمان ما، اتفاقی در Murder Row افتاده. جمعیتی جمع شده‌اند.\nبا احتیاط جلو برو. من با توام.", c = "با کسی که باقی نمانده اداره‌اش کند، این عملیات fel باید تمام شده باشد... دست‌کم فعلا.\nکار کردن با شما لطف داشت، <name>." }
WoWFQ[90835] = { t = "Murder Row: شایعه‌ها در جریان", d = "با احتیاط شهر را بگرد. هر چه در Silvermoon به نظر می‌رسد، نیست.\nIllidariها در جریان بررسی‌ای هستند که نباید علنی از آن حرف بزنیم. اما تو درخور و توانمند به نظر می‌رسی... شاید بتوانی یاری‌مان کنی.\nفرمانده‌ام، Belath Dawnblade، سرپرست بررسی است. آخرین باری که شنیدم، تراس‌های بالای Bazaar را بررسی می‌کرد.\nپیدایش کن، اگر می‌خواهی خودت را به کار بگیری.", o = { "Belath Dawnblade را در تراس‌های بالای Bazaar پیدا کن." }, c = "آمدنت به‌وقت بود.\nکوتاه می‌گویم: به باور من موج تازه‌ای از استفاده از جادوی fel در Silvermoon در گرفته و باید جلویش گرفته شود." }
WoWFQ[90837] = { t = "Murder Row: رد fel", d = "همیشه احساس جادوی fel نیرومندی در سراسر Silvermoon می‌کنم، اما این نخستین سرچشمه‌ای است که مکانش را پیدا کردم. بقیه بسیار کم‌رنگ بودند، یا عمدا پنهان. خوش‌یمن است که این یعنی حالا یک ناحیه مشخص برای گشتن دقیق‌تر داریم.\nباید شواهد بیشتری جمع کنیم. این حوالی را بگرد و ببین سرچشمه‌های پنهان fel بیشتری پیدا می‌کنی یا نه. بخشی موقتی از بینش خودم را به تو می‌بخشم تا کم‌رنگ‌ترین رد fel هم برایت آشکار شود.", o = { "5 سرچشمه جادوی fel را نزدیک Royal Exchange پیدا کن.", "سرچشمه‌های جادوی fel پیدا شد (5)", "Stained Worker's Shirt را بردار", "Bottled Fel Dust را بردار", "Blackened Metal Fragment را بردار", "Handwritten List را بردار", "Drained Wyrm Core را بردار" }, p = "چیزی پیدا کردی؟", c = "همم... تکه‌های Legion، گرد و غبار fel، و شواهدی که هر دو مخفیانه در شهر جابه‌جا می‌شوند. تجارت مجاز fel دست به چنین کاری نمی‌زند.\nو بعد هست coreهای mana wyrm که هر دو یافتیم. خشکیده و مکیده، اما هنوز fel به‌شان چسبیده است." }
WoWFQ[90871] = { t = "پیمان Silversun", d = "Champion.\nپس از بحث و مذاکره فراوان، حتی فریاد و سه دوئل، Sunreaverها و Silver Covenant به مسیر کاری برای آینده هر دو تن دادند.\nبا توجه به کمکی که به رسیدن به این روز کردی، دوست داریم شاهد رسمی‌شدن و امضای پیمان‌های صلح‌مان باشی. آیا افتخار روشن کردن Flames of Remembrance را به ما می‌دهی؟", o = { "در رسمیت بخشیدن به The Silversun Compact مشارکت کن.", "Flame of the Covenant را روشن کن", "Flame of the Sunreavers را روشن کن", "The Silversun Compact را مرور کن" }, p = "زمان‌های عجیبی است. عجیب به‌راستی.", c = "تمام شد. امروز نخستین روز پیمان Silversun است. انشاالله سوگندهایی که امروز امضا می‌کنیم در روزهای سخت ما را به کار درست پایبند نگه دارد." }
WoWFQ[90876] = { t = "دستِ بی‌میل", d = "Champion، مهم دانستم که در این لحظه اینجا باشی تا نه من و نه آن همکار سابق سرگردانم به علت شکست‌های فراوانش منحرف نشویم.\nهمچنین شاهدی می‌خواهم اگر به شرارت کشیده شد.\nلطفا چند تا از وسایل را بیرون می‌آوری تا مجبور نشوم دستم به‌شان بخورد؟", o = { "در آماده کردن Umbral Atrium مشارکت کن.", "Harmonial گردگیری شد", "میز آزمایش تمیز شد", "Proclamation مرور شد" }, p = "آن‌قدر غره نیستم که نپذیرم کمی... دلتنگی سبک برای لطیفه‌گویی‌هایی که روزی با آن همکار داشتم.\nMagister Umbric روزی واقعا سرچشمه نقدها و پیشنهادهای فراتر از انتظار بود و به پیشرفت دانش جادویی‌مان کمک می‌کرد.", c = "پس شهر را نجات می‌دهیم و در عوض اجازه دارند وسایل قدیمی‌ام را برگردانند.\nاز هر کس دیگری، این توهین بود. از Rommath؟ عالی‌ترین ستایش.\nآه، حتی alembic قدیمی‌ام را هم نگه داشته... چه لطافتی." }
WoWFQ[90907] = { t = "نخستین کسی که می‌داند", d = "یادداشت‌هایی که از ترس می‌گویند، از بی‌تصمیمی--از حقیقتی مرموز؟ این خوب نیست، $p. از هر حسابی که بکنیم، به نظر می‌رسد فرقه‌ای موفق شده به Tranquillien نفوذ کند.\nاگر آن یادداشت راست می‌بود، Kasiea داشت از آن می‌گذشت.\nباید به Antenorian بگوییم. می‌خواهد شهر را امن کند و مطمئن شود آدم‌هایش سالم‌اند.", o = { "به Lord Antenorian، فرماندار Tranquillien، نتیجه تحقیقاتت را خبر بده.", "در دفتر Lord Antenorian دیدار کنید", "از Secretary Faloria بازجویی شد", "Strange Lockbox بررسی شد", "Lord Antenorian باخبر شد" }, p = "امیدوارم شهر دوست‌داشتنی‌مان با تو خوب رفتار کند. اگر هر نگرانی داری، پیش من بیاور.", c = "دلگرم‌کننده است که این نگرانی‌های مهم را پیش من می‌آوری." }
WoWFQ[91084] = { t = "سایه‌های کمین‌کرده", d = "هرچند فعلا از Ruia و Lightbloom سر بلند کردیم، کارها باقی است. بزرگان می‌خواهند درباره جایگاه تازه Hara'ti در جهان گردهم بیایند، حالا که از سایه گذشته‌مان قدم بیرون گذاشته‌ایم.\nسربازماندن و ترس‌مان یک‌شبه نمی‌رود. اما این قدم اول مهمی است.\nما خوب خواهیم بود، <name>. بگذار من و Orweyna با بزرگان کار کنیم. وقتی وقتش برسد، Hara'ti در کنارت خواهند بود. فعلا، به گمانم کارهای فوری‌تری داری.", o = { "نزد Regent Lord Lor'themar Theron در Sanctum of Light در Silvermoon City بازگرد." }, c = "وقتی Halduron به شورای جنگ زد و توی آن گفت از دنیاهای پنهان و جنگاوران باستانی، گمان کردم دیوانه شده. اما حالا که haranirها را با چشم خودم دیده‌ام...\nشانس آورده‌ایم که چنین متحدان بالقوه‌ای داریم. و بگویم، شانس آوردیم که تو بودی که این رابطه را بست.\nکارهای بیشتری برایمان مانده. اما شک ندارم Hara'ti در روزهای پیش رو متحدانی حیاتی برای Silvermoon خواهند بود." }
WoWFQ[91090] = { t = "آفت‌های مزاحم", d = "موجودات اطراف به عفونتی از Light دچار شده‌اند و به سمت Sunbath کشیده می‌شوند. مهمان‌هایمان را آزار می‌دهد. این مشکل است، وقتی کسی می‌خواهد از آرامش دنیا لذت ببرد.\nاعتراف می‌کنم، وقتی یکی از آن‌ها وسط شنا به پایت می‌خورد، کمی دلهره‌آور است.\nلطفا sungrubهای مهاجم را از پیوستن به ما بازدار، و به آسمان برو آن پروانه‌های لجباز را بپران.", o = { "10 Sungrub را بکش و 10 Persistent Butterfly را با پرواز بپران.", "Persistent Butterflyها پرانده شد (10)", "Sungrub را بکش (10)" }, p = "حشره‌ها دردسرساز شدند؟", c = "انقدرها هم بد نبود، نه؟\nVal کمی نمایشی است، اما تو عالی انجامش دادی." }
WoWFQ[91137] = { t = "گم‌شده در Light", d = "به نظر می‌رسد بعضی از مهمان‌های ماجراجویمان از گردش‌شان برنگشته‌اند. Val گفت صبح روز قبل rutaani‌ای را دید که حوالی‌مان می‌گشت، اما مطمئن بودم فقط می‌خواهد به روزمان رنگ درام بدهد.\nLightbloom به Sanctum شمالی نفوذ کرده و باقی‌مانده مشکلاتش به سمت ما سرازیر است.\nمهمان‌هایمان برای فرار از دردسرهای دنیا اینجا هستند... این همه می‌تواند برایشان جدی‌تر از تحمل‌شان شود.\nاگر خودت رسیدگی کنی، من مطمئن می‌شوم Val مهمان‌ها را سرگرم نگه دارد.", o = { "Liya Waterbloom را بکش و گردشگران را به خانه بفرست.", "Liya Waterbloom را بکش" }, p = "سلامت برگشتند؟", c = "آزار دادن مهمان‌هایمان قدمی فراتر از حد بود.\nاو به sunbath دست درازی کرد و تاوانش را داد.\nممنونم، دوست تازه خانواده Solaar!" }
WoWFQ[91271] = { t = "یک ماهی!", d = "غذای لذیذی هست که با عشق می‌خواهم برای مهمان‌هایم درست کنم. با ماهی درست شروع می‌شود، بعد خردش می‌کنیم، در ترکیبی از مرکبات و چاشنی‌های خوش‌عطر ویژه‌مان می‌ریزیم و می‌گذاریم در مزه‌های باشکوه خواب ببیند.\nبه کوتاهی یک تک تک دم، تبدیل می‌شود به شاهکاری جادویی برای حواس!\nحالا حالا‌ها حرف شهریم، می‌دانی. می‌شود لطفا ماهی بین‌ظیر را برایمان بگیری؟", o = { "بهترین ماهی را برای غذا بگیر.", "Absolutely Adequate Fish را بگیر", "ماهی را به Valdekar برسان", "Fairly Fine Fish را بگیر", "ماهی را به Valdekar برسان", "Pretty Plump Fish را بگیر", "ماهی را به Valdekar برسان", "Fabulous Fish را بگیر" }, p = "حس خوبی درباره این یکی دارم!", c = "شاهکار کردی، <name>! ماهی درست‌وحسابی، تپل و خوش‌نسبتی آوردی!\nروزی شاد!" }
WoWFQ[91281] = { t = "Midnight", d = "یکی از تصویرهای Lady Liadrin را که در سراسر Azeroth ظاهر شده‌اند پیدا کن.", o = { "به نزدیک‌ترین Image of Lady Liadrin سفر کن.", "Image of Lady Liadrin را پیدا کن" }, c = "خوشحالم که آمدی، <name>. عاجزانه به کمکت نیاز داریم." }
WoWFQ[91284] = { t = "راهی که هنوز برگزیده نشده", d = "دارم تلاش می‌کنم بفهمم کدام راه زندگی را دنبال کنم، اما دائم دودل می‌شوم. Farstriderها، Blood Knightها، Magisterها... همه‌شان حیرت‌انگیز به نظر می‌رسند و نمی‌توانم انتخاب کنم.\nامیدوار بودم اگر با هرکدام حرف بزنم و توصیه‌نامه بگیرم، شاید بالاخره بفهمم جایم کجاست. کمکم می‌کنی؟", o = { "توصیه‌نامه‌ها را از مربی‌های Farstrider، Blood Knight و Magister جمع کن.", "Farstrider Recommendation را بگیر", "Blood Knight Recommendation را بگیر", "Magister Recommendation را بگیر" }, p = "واقعا امیدوارم جایی را که به آن تعلق دارم پیدا کنم...", c = "وای... باورم نمی‌شود هر سه توصیه‌نامه را گرفتم. همه حرف‌های مهربانی زدند، اما حالا بیشتر از قبل دودلم!\nبه نظرت... می‌شود لطفا در انتخاب کمکی کنی؟" }
WoWFQ[91288] = { t = "آزمون شکار", d = "پس توصیه‌نامه Farstrider می‌خواهی؟ این‌ها را مثل نوارهای جشن سرِ هر کسی نمی‌گذاریم.\nاگر می‌خواهی بدستش بیاوری، باید همان کاری را بکنی که هر تازه‌کاری می‌کند. پوست لینکس بیاور پیشم، تمیز و مرتب.\nنه میان‌بر، نه بهانه. ببینیم استخوان داری یا نه.", o = { "8 Invasive Lynx Pelt را در Sunstrider Isle جمع کن.", "Invasive Lynx Pelt را جمع کن (8)" }, p = "پوست‌ها را گرفتی یا هنوز تسلیم شده‌ای؟", c = "خب، ببین. برش‌های تمیز، بی‌کثافتی... شاید بچه بیشتر از حد تصورم جون داشته باشد.\nبگیر، این توصیه‌نامه‌ات. بگو یک Farstrider هرگز فراموش نمی‌کند که کی جای خودش را گرفت--و بگو نشانه‌گیری‌شان را تیز نگه دارند. ما چشممان هست." }
WoWFQ[91291] = { t = "آزمون خون", d = "آه، پس توصیه‌نامه یک Blood Knight می‌خواهی، اینطور است؟ در این صورت باید ارزشت را... پیش من ثابت کنی.\nفقط کسانی با توان و شرف راستین به صف ما می‌پیوندند! آماده شو. چالش ساده‌ای نیست، اما اگر مرا مغلوب کنی، توصیه‌نامه‌ام را با کمال میل می‌دهم!", o = { "Jesthenis Sunstriker را در Sunstrider Isle مغلوب کن.", "از Arcane Translocator استفاده کن", "Jesthenis Sunstriker مسابقه دوستی شد" }, p = "خب، خودت چه فکر می‌کنی؟", c = "تأثیرگذار! بیشتر از حد انتظارم درونت جون است.\nتوان و شرف و پشتکار خودت را ثابت کردی--صفت‌هایی که هر Blood Knight باید داشته باشد.\nاین توصیه‌نامه را بگیر و با افتخار همراهت کن. این انجمن همیشه دنبال اهل‌جایگاه‌هاست." }
WoWFQ[91292] = { t = "آزمون arcane", d = "آه، پس توصیه‌نامه یک Magister می‌خواهی؟ بسیار خب... اما اول باید درک‌ات از arcane را ثابت کنی.\nبه بلورهای نزدیکی که برای آموزش داریم برو، جادوی‌شان را بیرون بکش و در این عصا بریز. نشان بده که می‌توانی افسار arcane را در دست بگیری و تو را لایق توصیه‌نامه‌ام می‌بینم.\nاگر شکست خوردی، زحمت برگشتن را نکش. وقتم برای این جور پیش‌پاافتادگی‌ها بیش از حد گران است.", o = { "Arcane Transfer Staff را 4 بار در Sunstrider Isle شارژ کن.", "Arcane Transfer Staff شارژ شد (4)" }, p = "خب؟ عصا شارژ شد یا داریم هر دو عمرمان را تلف می‌کنیم؟", c = "همم، به نظر می‌رسد کمی بیشتر از حد گمانم استعداد داری.\nعصا به‌درستی شارژ شد. خوب بود، هرچند مطمئنم حتی عرق هم نکردی.\nاین توصیه‌نامه را بگیر و به یاد داشته باش--arcane احترام می‌خواهد، نه فقط قدرت." }
WoWFQ[91301] = { t = "چطور شاگردت را تربیت کنی", d = "همه چیز را که خواستند انجام دادم--آزمون‌ها و درس‌ها--و همه گفتند خوب بود... اما هنوز نمی‌دانم واقعا کجا تعلق دارم.\nهر راهی به چشم خودش درست بود و حالا قلبم به سه طرف کشیده می‌شود.\nلطفا... می‌شود در انتخاب کمکی کنی؟", o = { "توصیه‌نامه برگزیده را به Instructor Thalendir در Silvermoon City تحویل بده.", "Kyltus همراهی شد", "توصیه‌نامه تحویل شد" }, c = "آه... پس پسر بالاخره انتخاب کرد. قلب دارد--شاید هم زیادی.\nبله. این ثبت و محترم شمرده می‌شود. تو بیشتر از یک پیک بودی--به شکل‌دادن یک زندگی کمک کردی. ممنونم." }
WoWFQ[91328] = { t = "مواد مخفی", d = "مهمان‌های بذخ ما آن‌قدر از آذوقه‌مان می‌خورند که ذخیره Solaarian sintalia ویژه‌مان به خطر افتاده است.\nمزه فربه belanise با عطر مست‌کننده‌اش، به‌اندازه ترشی برنده محلی برایش عالی است. با دقت آماده و در ترکیب نوشیدنی‌های ویژه‌مان خیسانده و سرو می‌شود--مزهای که آدم را می‌کشد!\nراستش فقط بین خودمان باشد، اگر گیاهان را درست نشانی نکنند، این ترکیب می‌تواند حسابی کشنده باشد. وگرنه... خوشمزه، جانی، پاک‌کننده، باشکوه!", o = { "6 Belanise Blossom و 5 Sinara Berry برای Solaarian Sintalia جمع کن.", "Belanise Blossom را جمع کن (6)", "Sinara Berry را جمع کن (5)" }, p = "با دقت جمع می‌کنی؟", c = "جادو! بی‌نقص! حتی اگر آرزوم بود، نمی‌توانستی ماهرتر از این باشی.\nفکر جالبی است. می‌شود داشت؟" }
WoWFQ[91342] = { t = "اگر می‌خواهی درست انجام شود", d = "با این همه دردسر پیش روی Eversong، دست Farstriderها پرمشغله است!\nمن arcanist قابل‌اعتمادی هستم. همیشه به Farstriderها اعتقاد داشتم--چرا استعدادم را در راهشان نگذارم؟ این‌همه کار را با دست می‌کنند، در حالی که کمی جادو برایشان وقتِ ماجراجویی بیشتری می‌خرد!\nافسوس، ایده جاروی جادویی‌ام نتیجه‌ای که انتظار داشتم نداد. آن‌قدر عاصی‌اند که به جای تمیز کردن به تازه‌کارها حمله می‌کنند!\nشاید این کار برای پنجه‌های خاکی بهتر است.", o = { "8 Ornery Sweeper را بکش.", "Ornery Sweeper را بکش (8)" }, p = "Captain Dawnrunner به من هشدار داده بود که همه مشکلاتم را با جادو حل نکنم... واضح است که هنوز خیلی چیز باید بیاموزم.", c = "جارو کردن هنوز لازم است، اما دست‌کم حالا دیگر کسی حمله نمی‌کند." }
WoWFQ[91345] = { t = "به برج شمالی", d = "Ranger Valsarin سرآشپز در Farstrider Hold است. در آشپزخانه آبرومند است، اما عشقش آشپزی در دل طبیعت است.\nروزی بود که می‌شد هر مسیری در Eversong گشت و خوراکی‌های یک وعده خوب را یافت. رؤیای یک Farstrider! با کمی زحمت می‌توانیم به بازگشت جنگل کمک کنیم، و از اصلاح خاک آغاز می‌شود.\nدر North Tower به Valsarin بپیوند تا بیشتر برایت بگوید.", o = { "در North Tower با Ranger Valsarin دیدار کن." }, c = "امیدوارم دست‌به‌خاک شدن را دوست داشته باشی." }
WoWFQ[91347] = { t = "یورش Hawkstriderها", d = "باورش سخت است که این‌جا روزی Dead Scar بود.\nاینجا، نزدیک شهر، زمین تقریبا کامل بازگشته. که خوب است، چون دهان‌های زیادی برای غذا داریم.\nhawkstriderها یاوران بی‌نقصی برای آماده کردن خاک‌اند. پنجه‌های سخت‌شان به‌راحتی بذر می‌پراکنند و حشرات را می‌کوبند!\nپایین، در Tranquil Repose به من بپیوند تا یکی زین کنم برایت.", o = { "سوار Saddled Hawkstrider شو و Tranquil Repose را برای باغبانی آماده کن.", "با Recruit Valsarin صحبت کن", "Tranquil Repose آماده شد", "خاک شخورده شد (50)", "کرم‌ها لگدمال شد (20)", "بذرها پخش شد (10)", "نزد Recruit Valsarin بازگرد", "Mysterious Bloom را بررسی کن" }, p = "هیچ‌چیز مثل بذر کاشتن نیست.", c = "نمی‌دانم با آن شکوفه‌های بزرگ چه کنم... اما هر کاری می‌کنیم، زمین به نظر خوشش می‌آید." }
WoWFQ[91348] = { t = "قرار mana و wyrm", d = "mana wyrmها شاید به جذابیت لینکس‌ها یا hawkstriderها نباشند، اما برای جاری ماندن جادو در جنگل حیاتی‌اند.\nروی ley lineها جمع می‌شوند تا پوست بیندازند، اما گاهی کمی عاصی می‌شوند. و ما باید کمکشان کنیم! با قدرت!\nچند کانال ley راه‌انداخته‌ام تا کار راه بیفتد. wyrmهایی را پیدا کن که به کمک نیاز دارند، و آن‌قدر کتکشان بزن تا پوست arcane‌شان بریزد. نگران نباش--همه آن mana بالاخره به جنگل برمی‌گردد!", o = { "8 Agitated Wyrm را با قدرت در پوست‌اندازی‌شان همراهی کن.", "Agitated Wyrmها همراهی شدند (8)", "نزد Ranger Astarae بازگرد", "Mysterious Bloom را بررسی کن" }, p = "نگران نباش! سریع سر جایشان برمی‌گردند.", c = "یک پوست‌اندازی موفق دیگر... چند هفته دیگر باز هم همین‌جاییم تا تکرارش کنیم!" }
WoWFQ[91349] = { t = "بخش تاریک جنگل", d = "بخش زیادی از جنگل بازگشته، اما جنوب... هر چه Eversong به سرش آمده--Scourge، fel، و حالا Twilight's Blade--همه آن جادو در خاک می‌چکد. در موجودات جمع می‌شود تا کاملا از پا درآیند...\nسازنده‌های من فساد در این حیوانات را تشخیص می‌دهند. می‌توانیم آن‌ها که بیش از حد رفته‌اند را تنکیل کنیم و بقیه را نجات دهیم. کار خوشایندی نیست... اما برای خوبی Eversong است!", o = { "8 موجود را برای فساد آزمایش کن و با نتیجه روبه‌رو شو.", "حیوانات آزمایش شدند (8)", "غرش بررسی شد", "Bear Cubها نجات داده شدند (2)", "Mysterious Bloom را بررسی کن" }, p = "کار سخت‌گیرانه‌ای است، اما بالاخره به آرامی می‌رسد.", c = "چه بچه‌های بی‌چاره‌ای... فقط با فیض آن جادوی عجیب زنده ماندند!\nبهتر می‌دانم که به افسانه‌های قدیمی دل نبندم... اما اگر این نبود، پس چه بود؟" }
WoWFQ[91350] = { t = "مأموریتی واقعی", d = "قرار بود Captain Dawnrunner به Enclave سر بزند و بعد به ما بپیوندد. او به‌توانی هر ranger دیگری است! خبر بدی است اگر گیر افتاده باشد.\nFarstrider Enclave معمولا محل آموزش‌های طبیعت است. اما با این همه دردسر، همه به جای‌های دیگر اعزام شده‌اند. شاید آن بالا تنها باشد و در خطر جدی!\nوقتی برای از دست دادن نیست. می‌روم Captain‌ام را نجات دهم و خودم را به‌عنوان یک Farstrider ثابت کنم!", o = { "Captain Dawnrunner را در Farstrider Enclave پیدا کن." }, c = "این می‌شود وقتی کسی نباشد که جارو کند!\nهمه می‌خواهند ماجراجو باشند، اما کسی نمی‌خواهد جارو کند." }
WoWFQ[91383] = { t = "مرتب و سر و ته", d = "Captain Dawnrunner حالش خوب است، به خاطر خورشید. تنها خطر... این بود که قول‌ومرج‌هایمان را عقب انداختیم.\nقهرمانانه نیست، رمانتیک نیست، اما نمی‌شود با Farstrider Enclave در این وضعیت ادامه داد. rangerهای اینجا دستشان از همه‌جا کوتاه است. همه می‌توانیم سهمی بگیریم تا دوباره سر و تهش کنیم.\nباورم نمی‌شود همه‌اش به جارو برمی‌گردد. این است که واقعا بودن یک Farstrider یعنی.", o = { "5 Messy Nest را پاک کن و 5 Dusty Web را جارو کن.", "Messy Striker Nestها پاک شد (5)", "Dusty Lurker Webها جارو شد (5)" }, c = "rangerهای من امروز دارند نان در آورشان را می‌خورند، به‌راستی." }
WoWFQ[91384] = { t = "مأموریت بازیابی", d = "در سراسر جنگل Farstrider اعزام کرده‌ایم تا با Amani، Lightbloom، Void بجنگند... اما با همه این قهرمانی‌ها، کسی نمانده که از حیات وحش مراقبت کند! یا از ساختمان! یا حساب آذوقه‌ها!\nو حالا Enclave عزیزمان شبیه پن hawkstriderها شده. من دیگر کافی است!\nشاید خودم نتوانم کمکی کنم، اما به شما اطمینان دارم که هر چه برداشته شده را پس بگیرید و این مکان را دوباره آبرومند کنید.", o = { "12 Scattered Supply را از اطراف Farstrider Enclave بازیابی کن.", "Scattered Supplies را جمع کن (12)" }, p = "اگر می‌خواهیم برای بقیه Eversong مفید باشیم، اول باید پشت سرمان را جمع کنیم.", c = "شروع خوبی است. فقط به دسته‌ای کوچک نیاز است که کمی زحمت بکشد." }
WoWFQ[91385] = { t = "روح یک ranger", d = "Taemin امروز خودش را به‌توانی هر Farstrider دیگری ثابت کرد. اما می‌ترسم او این‌طور نبیند.\nبا خیال‌های بلند به rangerها پیوست--همه آن قصه‌های ماجراجویی شمشیرزنانه، همه آن افسانه‌های عاشقانه قدیمی. اما در نهایت، بودن یک ranger بیشتر... قول‌ومرج است. سخت، خسته‌کننده، مهم.\nچرا نرو با او حرف بزنی و مطمئن شوی زیاد دل‌شکسته نیست؟", o = { "Recruit Taemin را پیدا کن.", "با Arcanist Taemin صحبت کن", "رد شکوفه‌ها را دنبال کن", "رد شکوفه‌ها را دنبال کن", "رد شکوفه‌ها را دنبال کن", "رد شکوفه‌ها را دنبال کن", "رد شکوفه‌ها را دنبال کن", "رد شکوفه‌ها را دنبال کن", "رد شکوفه‌ها را دنبال کن", "رد شکوفه‌ها را دنبال کن", "رد شکوفه‌ها را دنبال کن", "به Spirit of Lake Elrendar سلام کن" }, p = "زیبایی جنگل؟ هرگز کهنه نمی‌شود.", c = "افسانه‌ها واقعی‌اند... Eversong باید از ما خرسند باشد!" }
WoWFQ[91386] = { t = "جنون اندازه", d = "این... توریست‌ها! این بی‌فرهنگ‌های ناسپاس!\nاین Vanguard of Light کسب‌وکار زیادی به Silvermoon آورد، به‌راستی. اما هیچ‌کدام واقعا نمی‌فهمند مهارت Thalassian یعنی چه. به هنر الف‌ها احترام نمی‌گذارند--فقط یادگاری‌های براق و خیره‌کننده می‌خواهند!\nمن نه پرنده‌ای خوش‌رقص‌ام که به دلبخواه‌شان برقصم... اما نمی‌توانم روی‌گردان شوم، نه؟ شاید یک دستیار این کار دشوار را آسان‌تر کند.", o = { "به Solwin Brightstitch در دوختن لباس برای Pushy Paladinها کمک کن.", "Fabric Shears را بیاور", "Plush Velour را بیاور", "Glittering Chiffon را بیاور", "Plush Velour را بیاور... دوباره", "Suramar Sequins را بیاور", "مشتری پررو را روی‌گردان کن" }, p = "کاش فقط یکی از این خوک‌ها کمی قدردان بود... افسوس، به نظر می‌رسد همین خواسته کوچک هم خیلی زیاد است.", c = "باشه... فقط چون کنجکاو مهارتش هستم.\nبیشتر از کمی ادب لازم است تا نظر من درباره این paladinهای مزاحم عوض شود." }
WoWFQ[91388] = { t = "نخ‌های کمیاب", d = "پatron ما--یعنی Gaari به هر روی--باید خوش‌شانس باشد. این mana wyrmها خوش‌سلیقه‌ترین ابریشم Eversong را می‌بافند. Magisterهایی می‌شناسم که برای لباس روبانی از این حرف‌ها هر کاری بکنند، و حالا ما داریم از آن برای وصله‌کاری استفاده می‌کنیم. به هر روی.\nوقتی wyrmها سیر از انرژی arcane شدند، می‌توانی ابریشم را از آن‌ها بکشی و در این قرقره‌ها بریزی.\nاگر نمی‌خواهند ابریشم‌شان را بدهند، شاید لازم باشد، اِه... کتکش بزنی. اما قول گرفته‌ام که کاملا اخلاقی است.", o = { "8 Full Bobbin of Manasilk را از wyrmهای تضعیف‌شده در North Sanctum بکش.", "Full Bobbin of Manasilk را بکش (8)" }, p = "این بخش آسان ماجراست، البته.", c = "آه... manasilk درخشان و زیبا. چنین سرشار از امکان." }
WoWFQ[91389] = { t = "لباس آدم را می‌سازد", d = "فقط ماده نیست که شنل arcanoweave را این‌قدر ارزشمند می‌کند؛ خود فرآیند بافت هم چنین است.\nوصله کردن یکی، به‌ویژه یکی که این‌همه تاریخ و انرژی arcane نهفته در خود دارد... در واقع دارم وارد پرخطرترین کار خیاطی عمرم می‌شوم. بالاخره یک گواه واقعی برای مهارت‌هایم.\nهیجان‌زده‌ام. امیدوارم چیزی منفجر نشود. وقتی آماده شدی داخل به من بپیوند.", o = { "داخل به Solwin بپیوند، و هر تجلی‌ای که سر راه می‌آید را دفع کن تا او شنل را وصله کند.", "با Solwin صحبت کن تا وصله‌کاری آغاز شود", "Arcanoweave Cloak تعمیر شد", "Gaari پیدا شد" }, c = "چه شاهکاری... خوشحالم که به دست کسی است که این‌قدر دوستش دارد." }
WoWFQ[91427] = { t = "وهن Mausoloa!", o = { "Mausoloa Desecration را بکش (3)" } }
WoWFQ[91430] = { t = "اندام‌های فراری!", o = { "Runaway Crystalها را لگدمال کن (5)" } }
WoWFQ[91452] = { t = "گستره دانش", d = "همیشه رؤیای Farstrider شدن را داشتم--ماجرا! عاشقانه! زیبایی طبیعت! وقتی برای کمک صدا زدند، فهمیدم باید بپیوندم.\nCaptain Dawnrunner اول مرا به کتابخانه داد، اما با این همه ماجرا، همه باید انعطاف داشته باشند.\nبرایم مهم نیست، اما امید داشتم پیش از فرستادن به مأموریتی واقعی، همه کتاب‌های معوقه را جمع کنم. اگر پیدایشان کردی، می‌شود برایم به کتابخانه بیاوری؟\nو به اختیار خودت بخوانشان! کتاب‌های جالبی در کار است!", o = { "3 کتاب معوقه را از اطراف Farstrider Hold بازیابی کن و به کتابخانه برگردان.", "Herbalist's Handbook: Eversong Medicinals را بردار", "Index of Ranger Corps Recipes Vol. VII را بردار", "Songs for the Silver Streams را بردار", "کتاب‌ها را به Farstrider Library برگردان", "کتاب محبوب Taemin را بررسی کن" }, p = "واقعا برای گذر از این روزها همه باید دست به دست هم بدهند.", c = "شاید پیش‌پاافتاده به نظر برسد، اما پیش‌پاافتادگی‌ها جمع می‌شوند." }
WoWFQ[91457] = { t = "فراوانی: Watha'nan Crypts", o = { "رویداد را کامل کن." } }
WoWFQ[91462] = { t = "به برج مرکزی", d = "Ranger Asterae یکی از دامپزشکان ماست. معمولا از لینکس‌ها مراقبت می‌کند، اما پوست‌اندازی mana wyrmها برای سلامت جنگل بیش از حد حیاتی است که بی‌مراقبت بماند.\nwyrmها جریان جادو را از ley lineها به بقیه جنگل تنظیم می‌کنند. وقتی ley lineها به هم ریخت، فصل پوست‌اندازی‌شان هم ریخت. آن‌قدرها هم که قبل بود خطرناک نیست، اما گاهی به کمک نیاز دارند.\nدر Central Tower به Asterae بپیوند. او بیشتر برایت می‌گوید.", o = { "در Central Tower با Ranger Asterae دیدار کن." }, c = "خوب آمدیم. اینجا بیشتر از همیشه mana wyrm هست." }
WoWFQ[91463] = { t = "به برج جنوبی", d = "هرچند تازه‌کار است، Taemin سخت‌ترین مأموریت را دارد. Eversong Woods بیشتر بازگشته، اما هر چه جنوب‌تر، اوضاع خطرناک‌تر.\nبا این حال mage توانایی است. و به بینی جادویی‌اش نیاز داریم.\nوقتی کار اینجا تمام شد پایین به تو می‌پیوندیم. Captain Dawnrunner قرار بود پشتیبانی بدهد. تا حالا باید رسیده باشد.", o = { "در South Tower با Arcanist Taemin دیدار کن." }, c = "م-من نگران نیستم. این است که بودن یک Farstrider یعنی!" }
WoWFQ[91493] = { t = "این که سفارش من نبود", d = "<زخم گازگرفتگی ساعد Hathvelion را نابود کرده است.>\nSnapdragonها... موجوداتی بی‌رحم برای کشتن و تغذیه. زهرشان با حرکت تو حرکت می‌کند. nagaها به‌ترین حیوان خانگی را پرورش داده‌اند.\nمن با خبری از Lyssara Duskmourne اینجایم. مسیرهای کشتیرانی Sunsail Anchorage را nagaها خراب کرده‌اند و آن مسیرها همین‌جا به هم می‌رسند.\nچند محموله را رهگیری کردم. می‌شود در جست‌وجویشان کمک کنی؟ تیمم هنوز در میدان است، اما به‌زودی خبر می‌دهند.", o = { "5 Intercepted Shipment را بررسی کن.", "محموله‌های رهگیری‌شده را بررسی کن (5)", "Vintage Vintage را بردار", "Magical Mango را بردار", "Unstable Arcana را بردار", "Perfectly Fine Grain را بردار", "Discarded Wand را بردار" }, p = "blood elfها می‌توانستند فقط از جادو برای تجارت استفاده کنند. اما یک جعبه چوبی استوار اعتماد دیگری دارد.\n<Hathvelion به میز کنارش می‌کوبد و لبخند می‌زند.>\nبه‌علاوه شنیده‌ام خوراکی و نوشیدنی بعد از حمل با جادو مزه‌شان از بین می‌رود.", c = "گمان Lyssara درست از آب درآمد. nagaها باید از هر گوشه Eversong در حال جمع کردن جادوی arcane باشند. باید بلافاصله جلویش را بگیریم." }
WoWFQ[91494] = { t = "زباله برای یکی، گنج برای دیگری", d = "هنرهای arcane تخصص من نیست. من به جادوی ملموس مسلط‌ترم--گیاهان، مخلوط‌ها، تقطیر، داروهای سطحی، استخراج، بخیه، مسکن...\nبه هر روی--آن عصا. به چشم بی‌سواد من قابل استفاده است. چرا روی ظرف arcana آزمایشش نمی‌کنی؟ شاید در برابر nagaها به کارمان بیاید. اگر واقعا خراب است، هیچ ضرری ندارد.", o = { "Discarded Wand را روی Container of Unstable Arcana آزمایش کن. سپس عصا را در Daggerspine Landing نیرومند کن.", "Discarded Wand آزمایش شد", "Arcana مکیده شد", "Arcane canister را بکش (15)", "Arcane canister vfx aura را بکش (100)", "Mana wyrm را بکش (13)", "Naga caster را بکش (9)" }, p = "شاید عصا برای صاحب قبلی‌اش ضعیف بود. به هر روی، می‌توانیم به کار درستی‌اش بیندازیم.", c = "می‌توانی فقط بگویی حسم درباره آن عصا درست بود.\n...البته مواظب باش. حالا شارژ شده است. تصادفی نیندازیش." }
WoWFQ[91495] = { t = "چهره‌های آشنا در خطر", d = "بادهای خوش راهت را باز کنند. آرزویم به حقیقت پیوست--Eversong شکفته است. اما مثل قبل، شرارت هر چه خوب است را تهدید می‌کند.\nدو شهروند از وقتی nagaها آمده‌اند بی‌خبرند: Enith--کنجکاوترین apothecary در Goldenmist، و Varnis--شاگردی است که از شهر آمده. پیدا کردنشان بر عهده من است.\nهم‌سنگرم Vedoran حتما هنوز در میدان است. نمی‌دانم شاید چیز مهمی یافته باشد. مراقبش می‌شوی؟", o = { "Apothecary Enith، Apprentice Varnis و Ranger Vedoran را در Daggerspine Landing پیدا کن.", "Apothecary Enith را نجات بده", "Apprentice Varnis را نجات بده", "Ranger Vedoran را نجات بده" }, p = "Farstriderها از کمکت سپاسگزارند.", c = "آرامش‌بخش است که بدانی سلامت‌اند. امیدوارم حال Varnis خوب شود. دیدم که سفید رو برگشت و حاضر نشد حرف بزند. وسایلش را جمع کرد و رفت.\nممنونم، <name>. امیدوارم هیچ شهروند دیگری وسوسه ورود به پایگاه nagaها نشود!" }
WoWFQ[91504] = { t = "انباشت arcane", d = "خب، حرف Numia را شنیدی. اگر استراحت نکنم کمانم را دو نیم می‌کند.\nRanger Vedoran از فعالیت‌هایی در فانوس دریایی خبر داد. دسته‌ای از mana wyrmها آنجا جمع شده‌اند و البته، nagaهای بیشتر.\nاگر سر مار آنجاست، ببرش! rangerهای من، Vedoran و Krann'an، همراهت می‌روند. و عصا را هم با خودت ببر. ارزشش را نشان داد. با این شارژ، به هر چه بربخورد محکم می‌کوبد.", o = { "Princess Naz'jena را در Daggerspine Point بکش.", "Princess Naz'jena را بکش", "از Empowered Wand در برابر Princess Naz'jena استفاده کن" }, c = "خود فانوس دریایی به‌خاطر انباشت انرژی‌های arcane، هم نهفته هم جمع‌شده، از هم می‌پاشید. چه فاجعه‌ای در کمین است. بلافاصله گزارشی به Regent Lord Lor'themar می‌رسانم.\nبه لطف تو، rangerهای من و شهر نجات پیدا کردند. برایش، لطفا استراحت کن و بنوش.\n...عصا منفجر شد؟! به نظرم حالا فهمیدیم چرا دور انداخته بودندش.\nمی‌دانی، یک کمان هرگز خودش آتش نمی‌گیرد." }
WoWFQ[91505] = { t = "خنجر در پشتم", d = "nagaها سابقه سوءاستفاده از جادوی arcane دارند. پایم شرط می‌بندم این بار هم فرقی نمی‌کند--arcane خون‌شان و سرچشمه قدرتشان است. زیرکانه است که حالا عمل می‌کنند، وقتی Eversong در محاصره تهدیدهای دیگر است.\nاز وقتی Farstrider شدم، مراقبت از ساحل غربی Eversong بر عهده من است. تیم ضربتی‌ام از قبل دور Goldenmist کمین کرده‌اند. خوش‌یمن است که nagaها هنوز به شهر کاری ندارند، اما خیلی بیشتر از حد راحت نزدیک‌اند.\nمسیرمان روشن است: پاکشان کن!", o = { "12 Daggerspine naga را در Daggerspine Landing بکش.", "Daggerspine nagaها را بکش" }, p = "نمی‌گذاریم nagaها به Goldenmist نزدیک‌تر شوند.", c = "ترس و مرگ را به قلب‌های زاده‌آب‌شان کاشتی! خوب بود.\nمراقب پایگاه‌شان می‌مانیم و نمی‌گذاریم دوباره بسازند." }
