WoWFQ[91627] = { t = "پناهگاه Saltheril", d = "<name>، به گمانم؟ بسیار خب. آوازه تو پیش از تو آمده است.\nLord Saltheril صمیمانه‌ترین سلام‌ها را می‌فرستد، همراه دعوتی مؤدبانه به ملکش در جنوب Silvermoon.\nبخشی از محوطه به بهشتی فربه برای اهل مجالس درست‌وحسابی و گپ‌وگفت‌های خوش تبدیل شده است. به باور او، تو نگاه... ویژه‌ای به ماجرا می‌آوری.\n<او با اندکی تحقیر مؤدبانه تو را از بالا تا پایین نگاه می‌کند.>\nدریافت دعوت‌نامه افتخاری کمیاب است. سرورش امید دارد بپذیری.", o = { "در Saltheril's Haven با Lord Saltheril صحبت کن." }, c = "آه، <name>. به Haven من خوش آمدی--پناهگاهی از آشوب دنیا، از روزهای Anasterian.\nبعضی‌ها گمان می‌کنند این فقط مهمانی‌ای پوچ است، اما در همین محوطه طلایی و زیبا، تصمیم‌هایی روی میز با شراب گرفته شده که سرنوشت نسل‌ها را عوض کرده است." }
WoWFQ[91628] = { t = "مهمانان گرامی", d = "خوشحالم که می‌توانی همراهمان باشی. امروز آغاز مناسبت بسیار ویژه‌ای است.\nsin'dorei با میز جنگ غریبه نیست، اما اشرافشان ترجیح می‌دهند خودشان را گم‌کرده‌تر نشان دهند. در جنگ، تاج نمایندگانی می‌فرستد تا دل اشراف را بخرند. اگر راضی باشند، شاید به تلاش جنگ طلا قرض دهند.\nخیلی شبیه دل‌بری است، با همه بازی‌های حسادت‌آمیزی که حدس می‌زنی.\nپس بازی را شروع کنیم، شود؟ این دعوت‌نامه‌ها را برسان تا ما هم اینجا کارهای پایانی را بکنیم.", o = { "دعوت‌نامه‌های Lord Saltheril را به Magisterها، Blood Knightها، Farstriderها و \"تاجران\" در Silvermoon برسان.", "از مهمانان بپرس", "Magisterها دعوت شدند", "Blood Knightها دعوت شدند", "Farstriderها دعوت شدند", "\"تاجران\" دعوت شدند" }, p = "حضورت همین حالا هم سرها را می‌چرخاند. این می‌شود نمایشی بزرگ.", c = "آه، پس آوازه بهره‌وریت واقعیت دارد.\nعالی. حالا می‌توانیم بازی را آغاز کنیم." }
WoWFQ[91629] = { t = "احترام فراوان", d = "دعوت به Haven من بسیار سخت‌گیرانه است، به‌خصوص در چنین روزگاری. فرستادن حتی یک پیشنهاد موقتی، افتخاری بزرگ است.\nلطف من در میان اشراف وزن زیادی دارد. اگر از متحد یکی از نمایندگانمان دعوت کنم، یعنی به او ارج می‌نهم--و اگر من ارج بنهم، مهمانان اشراف هم چنین می‌کنند.\nاما اگر بگذارم خودت یک دعوت‌نامه انتخاب کنی، بی‌لذت‌تر نیست؟\nبرو هر وسوسه‌ای که پیشنهاد می‌کنند ببین، بعد انتخاب کن.", o = { "به مغازه‌های Saltheril's Soiree سر بزن، سپس متحدی از Magisterها، Blood Knightها، Farstriderها یا Shades of the Row انتخاب کن تا این هفته دعوتش کنی.\nانتخاب تو تعیین می‌کند این هفته کدام فراکسیون \"Fortify the Runestones\" را به Warband شما پیشنهاد می‌دهد.", "به مغازه Magisterها سر بزن", "به مغازه Blood Knightها سر بزن", "به مغازه Farstriderها سر بزن", "به مغازه Rowها سر بزن", "دعوت‌نامه انتخاب شد" }, p = "هر دعوت‌نامه‌ای که دوست داری انتخاب کن.", c = "همین حالا پیش‌خدمتم را می‌فرستم دنبالشان." }
WoWFQ[91693] = { t = "بازی پیچیده", d = "ظاهر همه چیز است. اگر دربار ببیند از گروهی خاص حمایت می‌کنم، دنباله‌رو می‌شوند.\nاین نشانه‌های لطف من را بگیر و به هر کس از مهمانان گرامی که خودت صلاح می‌دانی بده. گمان می‌کنم اگر همراهی‌شان را برگزینی، دعوتت کنند در نقشه‌هایشان شریک شوی و سهمی از منافع ببری.", o = { "3 نشانه از Saltheril's Favor را به فراکسیون‌هایی که این هفته یاری می‌کنی بده.", "Saltheril's Favor اهداء شد (3)" }, p = "تلاش کن مهمانانمان را در انتظار نگذاری.", c = "شکوه‌مند است.\nواقعا امیدوارم در فصل دربار، کمی هم برای تفریح وقت بگذاری. من آدم‌های اخم‌آلود و نتیجه‌محور را قدر می‌دانم، اما تو می‌توانی کمی هم لبخند بزنی." }
WoWFQ[91822] = { t = "درخواست Regent", d = "Lor'themar خواسته حضورمان را. جزئیات را دقیق نگفته، اما مکانی که برگزیده خودش گویاست.\nSilvermoon Harbor. آرام و دور از چشم. جای معمولی برای دیپلماسی یا مراسم نیست. نه، حس چیز دیگری می‌دهد. هر چه در سر دارد، در هیچ سند رسمی نوشته نخواهد شد.\nبیا. برویم ببینیم Regent Lord چه در سر دارد.", o = { "بفهم Lor'themar چه نقشه‌ای دارد.", "با Lor'themar حرف بزن" }, p = "بگذار Regent Lord را معطل نگذاریم.", c = "این جالب خواهد شد." }
WoWFQ[91823] = { t = "خط‌ها قطع، زبان‌ها خاموش", d = "Twilight's Blade چون دانش و رازها را دزدیده بود، به‌سادگی به Tranquillien آمد. درباره دفاع‌هایمان، جادویمان، مردممان. وقتی داخل شدند، اطلاعات بیشتری هم کشف کردند.\nحالا آن اطلاعات را با گوی‌های جادویی بین خودشان رد و بدل می‌کنند. نجواگه‌هایی آرام که در تاریکی می‌چرخند. هر پیام، حلقه دار را تنگ‌تر دور Quel'Thalas می‌کشد.\nگوی‌ها را پیدا کن. بشکنشان. هر بلوری که می‌شکند، یک نجوا خاموش می‌شود.", o = { "گوی‌های ارتباطی را در Zeb'tela Ruins نابود کن.", "گوی ارتباطی را نابود کن (4)" }, c = "خوب بود. هرچه کمتر بدانند، مردممان امن‌ترند." }
WoWFQ[91824] = { t = "ردپای دزدان", d = "تا آنجا که می‌بینم، Twilight's Blade چند یادگار arcane را دزدیده که Magisterهای ما برای تقویت ارتباط دوربرد از آن‌ها استفاده می‌کردند. اگر یاد بگیرند به کارشان بگیرند، دسترسی‌شان را به جایی می‌رسانند که مهارش نمی‌کنیم. حتی ممکن است بتوانند ارتباط‌های ما را بشنوند... و این را نمی‌شود پذیرفت.\nیادگارها را بازپس بگیر. اگر کسی سر راهت سبز شد... می‌دانی چه باید کرد.", o = { "Quel'dorei Artifactها را از Twilight's Blade در Zeb'tela Ruins بازیابی کن.", "Quel'dorei Artifact را جمع کن (10)" }, p = "این یادگارها هرگز نباید به دست اشتباه می‌افتادند.", c = "خوب. با برگشتنشان به جای اصلی‌شان، دسترسی‌شان خیلی کوتاه‌تر شد. کاش فهمیده بودیم اول از همه کی آن‌ها را دزدید." }
WoWFQ[91825] = { t = "مرده‌ها راز نگه نمی‌دارند", d = "از آنچه دیده‌ام، این گروه بی‌سرپرست عمل نمی‌کند. کسی رهبری‌شان می‌کند، مردی که در یکی از سازه‌هایشان پنهان است.\nاگر حدس بزنم، او همان کسی است که هر چیزی را که برای اعتماد به بلور یا پیکی زیاد مهم بود، نزد خودش نگه می‌دارد. اسناد، نقشه‌ها، نام‌ها.\nپیدایش کن، ساکتش کن، و هر چه محافظتش می‌کرد بیار.", o = { "اسناد دزدیده‌شده را از Gareth the Listener در Zeb'tela Ruins بازیابی کن.", "Infiltrator's Cache را بردار" }, p = "انگار این کار برایت آسان بود.", c = "عالی. همه مهم‌ترین رازهایشان، از دستشان خارج شد." }
WoWFQ[91826] = { t = "تانگوی سیم کشیک", d = "این مخزن با جادو قفل نشده. با هنر قفل‌سازی. صدای تیک‌تاک مکانیزم را از درون می‌شنوم. چرخ‌دنده‌های ریز، فنرهای کشیده، و احتمالا بطری زهری آماده شکستن به محض اینکه کسی بخواهد قفل را باز کند.\nباید با هم این کار را بکنیم. من پین‌ها را می‌گیرم، تو جلوی فروپاشی مکانیزم را می‌گیری. یک حرکت اشتباه و برای انداختن یک اوگر وسط دویدن کافی است. استوار باش.", o = { "مکانیزم را خنثی کن و اسناد را از درون صندوق بیرون بکش.", "مکانیزم تله خنثی شد", "Stolen Documents را بردار" }, p = "با آرامش، قدم به قدم.", c = "این اطلاعات حیاتی است. تعجبی ندارد که این‌همه برای حفظش زحمت کشیده بودند." }
WoWFQ[91827] = { t = "سرنخی باقی نماند", d = "خوب از پس خودت برآمدی.\nاین اسناد آن‌قدر مهم‌اند که نباید به دست پیکی یا کلاغ سپرده شوند. دوست دارم شخصا به Lor'themar برسانی. او می‌خواهد حقیقت را خودش ببیند و بداند چه کسی آن را برگردانده.\nنزدیک‌شان نگه دار و بگذار هیچ‌کس نزدیک‌شان نشود.", o = { "در Silvermoon City نزد Lor'themar Theron بازگرد." }, c = "<Lor'themar اسناد را با دقت بررسی می‌کند. لحضاتی بعد، سرش را بالا می‌آورد، به تو نگاه می‌کند و لبخندی کمرنگ می‌گذارد.>\nشاهکار بود. می‌دانستم می‌توانم روی هر دوی‌تان حساب کنم." }
WoWFQ[91843] = { t = "Recap: پیام‌آور", d = "برای فهم قصه The War Within، باید نخست با موجود مرموزی به نام پیام‌آور آغاز کرد، و اینکه قهرمانان Azeroth چگونه حقیقت را کشف کردند...", o = { "همراه با Tome of History بخوان و از رخدادهایی که The War Within را برافراشت باخبر شو.", "برای آشنایی با پیام‌آور به Tome of History مراجعه کن" }, p = "Xal'atath دشمنی مرموز با پیوند به Void بود. حضورش بشارت روزهای تاریک برای Azeroth بود...", c = "Alleria راز پیام‌آور را کشف کرد و Xal'atath را آشکار ساخت. اما دیر نگذشت که پیام‌آور قدم بعدی را برداشت." }
WoWFQ[91854] = { t = "تاریکی‌های فزاینده", d = "Champion، به کمکت نیاز دارم. اهالی Silvermoon کمتر از آنچه امید داشتیم با گذشت خویش رفتار می‌کنند.\nبه گفته‌شان باید انصاف داد: شهرشان با تاریکی‌ای روبه‌روست که Azeroth تاکنون به‌چنین شکل ندیده، پس تنش‌ها بالاست.\nمی‌شود با نگاه ویژه‌ات کمک کنی چند نقطه داغی که در اطراف Silvermoon در گرفته را آرام کنی؟", o = { "تنش‌های در حال افزایش در Silvermoon City را آرام کن.", "دعوای شهری آرام شد", "اسیر آزاد شد", "پیشگوهای آخرالزمان را دفع کن" }, p = "تنش‌ها بالاست.", c = "خوب بود. آن Voidstorm در هر کسی که ببینتش، حتی خود من، ترس و وحشت می‌ریزد.\nاما من این زندگیِ ایستادن در برابر شرارت و آب دهان به صورتش را برگزیدم. متاسفانه برای همه انتخاب نبود." }
WoWFQ[91967] = { t = "این شرارت را می‌شناسی؟", d = "Champion، وضعیت لطیفی پیش آمده.\nVanguard of the Light همین حالا خبر داد Magister Umbric را بازداشت کرده‌اند. به ظاهر می‌خواست به Sunwell نزدیک شود.\nلازم نیست بگویم تنش میان شهر من و Vanguard بالاست. برای شانس ماندن در برابر Voidstorm به پژوهش‌های Umbric نیاز داریم.\nمی‌خواهم نماینده من باشی و مذاکره برای آزادی Umbric را پیش ببری. چه دوستش داشته باشیم چه نه، به او نیاز داریم.", o = { "با Vanguard of the Light برای آزادی Magister Umbric مذاکره کن.", "Umbric را پیدا کن", "از Lothraxion درخواست کن", "از War Chaplain Senn درخواست کن", "از Grand Magister Rommath درخواست کن", "از Anduin Wrynn درخواست کن", "به Lor'themar Theron گزارش بده" }, p = "Umbric لازم است. Vanguard هم.\nاین روزها عناصر لازم و ناخوشایند زیادی برای کنار آمدن دارم، اما می‌کنم اگر یعنی مردمم امن‌اند.", c = "بابت وساطتت ممنونم. هرچند به خودم می‌بالیم که هر چه برای Silvermoon و Sunwell لازم است انجام دهم، حس می‌کنم صبرم لبریز می‌شد و چیزی می‌گفتم که همه پشیمانش می‌کردیم." }
WoWFQ[91971] = { t = "کوبیدن چکش", d = "Twilight Hammer در حال کثیف کردن ویرانه‌های Zeb'tela است. ناحیه را پاک کن و چند نشانه شخصی‌شان را هم بیار. کی می‌داند چه جالبی‌هایی برای اهل رساندن خود به دیده‌ها خوش‌یمن باشد.\nآن فرقه‌گرایان بی‌عقل شاید با کوبیدن پا خودشان را خشن نشان دهند، اما تو سریع کارشان را می‌سازی.", o = { "6 Twilight Token را بیار.", "Twilight Token را جمع کن (6)" }, p = "چیز مفیدی پیدا کردی؟", c = "با موفقیت بر تیزی ابزارهای Twilight کاستی. اینکه برای این نشانه‌های عجیب متقاضی پیدا می‌شود یا نه، معلوم نیست.\nالبته، از سلیقه که نمی‌شود حساب کشید." }
WoWFQ[91972] = { t = "نگهبانی را نگه دار", d = "هنوز اصطکاک زیادی روی مرز با Zul'Aman هست، اما باید مراقبت را در همه جبهه‌ها نگه داریم.\nدر Thalassian Pass به Bloodguard Nelric سر بزن. می‌گویند یکی از کم‌خبرترین پست‌هاست. مطمئنم از کمی گپ‌وگفت استقبال می‌کند، هرچند کوتاه.\nهوشیار باش، $p!", o = { "در Thalassian Pass به Bloodguard Nelric سر بزن و نگهبانی را نگه دار.", "گزارش: Thalassian Pass", "نگهبانی را نگه دار" }, p = "حال Bloodguard Nelric به کی گذشت؟", c = "نگهبانی بی‌خبر، بهتر از گفتگویی خالی است.\nBlood Knightها از خدمتت سپاسگزارند." }
WoWFQ[91973] = { t = "شمشیرهای naga", d = "به نظر می‌رسد اهالی این روزها به شمشیرهای naga علاقه زیادی دارند--هرچه شورزه‌تر بهتر. در ساحل جنوب‌غربی، Daggerspine nagaها را پیدا می‌کنی.\nشمشیرهای خزه‌ای و مروارید‌گرفته‌ای دارند که دقیقا مناسب‌اند.\nبرو چند تا بگیر. در گفتگوهای پیش رو ممکن است ارزش داشته باشند.", o = { "7 Naga Scimitar جمع کن.", "Naga Scimitar را جمع کن (7)" }, p = "تونستی شمشیرها را بگیری؟", c = "شاهکار! این‌ها خوب جواب می‌دهند.\nراستش فقط بین خودمان، سلیقه شخصی من صدف‌های رنگی است. شاید چون شمشیر خودم بیش از تزئین کار می‌کند." }
WoWFQ[91974] = { t = "Sunfire بر تیغه", d = "به گمانم یک فایده بودن در بازی‌های دربار این است: آدم چیزهایی می‌شنود. این ترکیب sunfire آمیخته با انرژی مقدس Blood Knightها را داریم، هدیه کیمیاگران دربار.\nاین را به Sanctum of the Moon ببر و روی مهاجمان Twilight آزمایشش کن. مشتاقم نتیجه را با جزئیات بشنوم.", o = { "10 مهاجم Twilight را در Sanctum of the Moon با Holy Sunfire بکش.", "مهاجمان Twilight پاک‌سازی شدند (10)" }, p = "چطور پیش رفت؟", c = "Anar'anel belore! این را دوست داشتنش آسان است. این خبر مطمئنا چند قلب را برای راهمان گرم می‌کند." }
WoWFQ[91975] = { t = "این چوب مال ماست", d = "به نظر می‌رسد وسوسه lightwood همچنان دردسرساز است.\nهمین‌طور بهتر است از زحمت ترول‌ها استفاده کنیم! هر چه درو کرده‌اند را جمع کن. خودمان به کارش می‌بریم.\nهر چه برای سلاح لازم نداریم، می‌توانیم به پیکرتراش‌ها بدهیم. اشراف بر تزئینات lightwood نجواها می‌کنند.", o = { "5 Harvested Lightwood جمع کن.", "Harvested Lightwood را جمع کن (5)" }, p = "lightwood را جمع کردی؟", c = "مأموریتت تمام است. به کارمان می‌آید.\nنگذار بفهمند که Blood Knightها اول انتخاب کردند." }
WoWFQ[91976] = { t = "خاموشی Lightbloom", d = "همه این گپ‌های کوچک گوش‌هایم را می‌خاراند. در کار میدانی به‌شدت مفیدتر می‌بودم. فعلا، بخش شاد ماجرا سهم توست.\nموجودات درون Lightbloom حسابی شلوغ شده‌اند. لازم است بروی آن بیرون و صدا را پایین بیاوری.\nمطمئنم آن بیرون گزینه‌های زیادی پیدا می‌کنی. چند تایشان را برایم بزن.", o = { "موجودات Lightbloom را بکش.", "موجودات Lightbloom را بکش", "Lightbloom Hydra را بکش (10)", "Lightbloom Petalwing را بکش", "Lightbloom Lasher را بکش (34)", "Irradiant Thornmaw را بکش (5)", "Lightfed Growth را بکش (20)", "Light Wyrm را بکش (50)", "Lu'ashal را بکش (3)", "Lightbloat Trampler را بکش (4)", "Lightfrenzied Lasher را بکش (20)", "Bloom Dominator را بکش (7)", "Lucent Hookbeak را بکش (10)", "Infused Seedling را بکش (50)", "Overfester Hydra را بکش (3)", "Lucent Hookbeak را بکش (10)", "Rampaging Ent را بکش (5)" }, c = "خوب انجامش دادی. Silvermoon از خدمتت قدردان است.\nکاش جای تو بودم، اما هر کس مأموریت خودش را دارد." }
WoWFQ[91977] = { t = "کمی کمتر بی‌قانون", d = "Tideborneها همیشه همان‌طرف مرز قانون‌اند. در بهترین حالت مزاحم‌اند، اما اگر زیاد راه بدهی مرزها را پس می‌زنند.\nTideborneهای Sunsail Anchorage مدتی پیش اشتباه کردند و به برخی اشراف خیانت کردند. شاید بروی کمی کتک‌کاری‌شان کنی--یادآوری کن که به بالادست‌هایشان احترام بگذارند.", o = { "8 Tideborne را تنبیه کن.", "Tideborneها را تنبیه کن" }, p = "به Tideborneها درس دادی؟", c = "آه، حتما خیلی سرگرم‌کننده بوده! بارِ تحملم امروز پایین است، بعد از آن گفتگوی جذاب درباره چرخه برداشتِ peacebloom معمولی.\nعذرخواهی می‌کنم. بدان که از خدمتت قدردانیم." }
WoWFQ[91978] = { t = "مالیات از Tideborne", d = "تا حالا دقت کرده‌ای که گاهی سود در این است که بگذاری کسی فکر کند دارد از چنگت فرار می‌کند؟ Tideborneها همان‌طور که هست، در دید همه، به قاچاق ادامه می‌دهند و خودشان را باهوش می‌بینند که مالیاتِ Silvermoon را نمی‌دهند.\nالبته با گذشت زمان جمع می‌شود. وقتی دستت گرفت، پایین بندر برو و چندی از مالیات‌های عقب‌افتاده‌شان را پس بگیر.", o = { "50 Tideborne Doubloon جمع کن.", "Tideborne Doubloon را جمع کن (50)" }, p = "وقتی از دزدها می‌دزدی، باز هم دزدی است؟", c = "آدم باید صدای زنگ مخصوص یک کیسه سنگین سکه‌های غارتی را دوست داشته باشد.\nشاهکار بود، دوست من." }
WoWFQ[91979] = { t = "قطعش کن", d = "خبر رسید که موجودی از Lightbloom Ath'Ran در ساحل غربی دردسرساز شده. کمی به پا کرده است.\nبرو و ماجرا را حل کن.", o = { "Rampaging Ent را نزدیک Lightbloom Ath'Ran بکش.", "Rampaging Ent را بکش" }, p = "مشکل حل شد؟", c = "خوب بود. مطمئنم هیزمِ خوبی ازش درمی‌آید." }
WoWFQ[91983] = { t = "پرهای دلنشین", d = "اعضای زیبای دربار Silvermoon عاشق تزئینات رنگارنگ‌اند.\nبرای همین، می‌توانیم حین انجام یک کار خوب ذخیره کنیم! به Thuron's Livery برو و مقداری از پرهای رنگارنگی که hawkstriderهای در حال تمرین ریخته‌اند بردار.\nVaelith خدمات نظافت می‌گیرد و ما پرهای دلنشین.", o = { "8 Bright Feather جمع کن.", "Bright Feather را جمع کن (8)" }, p = "مقدار زیادی پر پیدا کردی؟", c = "تو در این کار استادی!\nروزی باید این پرها را روی هم تلنبار کنیم و بگذاریم همه درشان شیرجه بزنند. به نظرم تعجب می‌کنی که چند lord و lady محترم با خوشحالی شرکت می‌کنند.\nفعلا، به سراغ زینت‌های پرِ پر می‌رویم." }
WoWFQ[91984] = { t = "ابریشم sungrub", d = "وای، $p، تا حالا به Solaarian Sunbath سر زدی؟ اگر نه، به‌شدت توصیه می‌شود.\nsungrubهایی که اطراف می‌گردند ابریشمی گران‌بها دارند که از آن پارچه‌ای حیرت‌انگیز می‌سازند. گفته می‌شود Solwin Brightstitch با جادوی خیاطی‌اش در این کار استادی.\nمواد خام را می‌برند پیشش تا از صفر کالاهای یکتا و شخصی‌سازی‌شده بسازد. مقداری از آن ابریشم دوست‌داشتنی برایمان بیاور. حین بحث‌های سخت، بالشتک نرمی است.", o = { "3 Sunsilk جمع کن.", "Sunsilk را جمع کن (3)" }, p = "وای، همه ابریشم را گرفتی؟", c = "بی‌نقص! اعتراف می‌کنم، سختم می‌شود بخشی از این‌ها را از دست بدهم.\nباید به یاد داشته باشم اینجا کاری برای انجام دادن دارم. نمی‌شود همه‌اش خنده و بازی باشد.\nاز کارت قدردانیم." }
WoWFQ[91985] = { t = "یادگاری‌های Windrunner", d = "اشراف عاشق چیزهای عجیب‌اند. یه گشتی در Windrunner Village بزن. حتما یادگاری‌های جالبی هنوز همان‌جا لای درها قایم شده‌اند.\nمن برای تکه‌هایی که می‌آوری خانه‌ای به‌صرفه پیدا می‌کنم.", o = { "5 Windrunner Memorabilia جمع کن.", "Partially-Used Memento را جمع کن (5)" }, p = "چیز جالبی پیدا کردی؟", c = "گفتم عجیب و تو هم رساندی! به نظر چند تایشان کمی... مشکوک‌اند.\nمطمئنم همه چیز خوب پیش می‌رود. از وسایل با منشأ مرموز چه ضرری برمی‌آید؟" }
WoWFQ[91986] = { t = "جرقه‌ای در گام‌شان", d = "این nagaها، مثل همیشه، مزاحم ساحل‌اند. نمی‌فهمند که این جای نخبه‌ای است؟\nشاید نتوانیم با اطمینان برانشان، اما کمی خرابکاری بی‌جا نیست.\nآهنگی پیدا کرده‌ام که snapdragonها را دیوانه می‌کند. به هر کسی که نزدیک باشد حمله می‌کنند. این را بگیر و امتحانش کن!", o = { "8 Daggerspine Snapdragon را با یک آهنگ دیوانه کن.", "Daggerspine Snapdragonها دیوانه شدند (8)" }, p = "nagaها به‌اندازه کافی آزار دیدند؟", c = "دلم برای snapdragonها می‌سوزد، اما نمی‌توانم به قیافه غافلگیری‌شان وقتی رفقای کوچکشان به‌شان می‌پرند نخندم.\nممنون که روز را کمی سرگرم‌کننده‌تر کردی." }
WoWFQ[91987] = { t = "Lasherهای گلدانی", d = "به نظر می‌رسد بعضی از اشراف درباره Lightbloom گیاه‌دوستی‌شان درگرفته است. دنبال گیاهان عجیب می‌گردند تا پشت‌پنجره‌هایشان آراسته شود و بخش خطرناک گلخانه‌شان را پر کند.\nاینجاست که تو وارد ماجرا می‌شوی، $p!\nبرو آن گیاهان کوچک و زیان‌بار را برداشت کن. پیازشان برای کاشت بهتر است.", o = { "8 Lightblooming Bulb جمع کن.", "Lightblooming Bulb را جمع کن (8)" }, p = "در برداشت مشکلی پیش آمد؟", c = "نتیجه دادن این‌ها به نخبگان Silvermoon از «تا حدی خنده‌دار» تا «فاجعه» متغیر است.\nبه هر روی، مشتاقم نتیجه تلاش‌های باغبانی‌شان را ببینم." }
WoWFQ[91988] = { t = "مراقبت از Brightwing", d = "نگهبانان Brightwing Estate اژدهاهای جوانی شیطان‌مistrar به نام Cerul دارند که هر وقت چشمشان نباشد فرار می‌کند. دور نمی‌شود، اما بازی‌اش این شده که تعقیب‌شان کند.\nاین خوراکی خوشمزه را ببر و با آن او را به خانه بکشان.", o = { "Cerul را به خانه‌اش در Brightwing Estate برگردان.", "Cerul را بکشان", "Cerul را به خانه برسان" }, c = "اینکه همه موجودات در Brightwing خانه باشند، همگی را خوشحال می‌کند. داشتن مکانی آرام برای لذت بردن از ساحل، به نفع همه است.\nممنون که گذاشتی Cerul کمی وقت بازی کند!" }
WoWFQ[91989] = { t = "فلفل‌های Ghostland", d = "فلفل‌های آبی و لطیف ghostland شاید زیاد به چشم نیایند، اما تیزی خطرناکی دارند. خیلی از اشراف حاضر نیستند اعتراف کنند، اما در بازی‌های «راست‌گو یا چالش» اشرافی خیلی محبوب‌اند.\nلطفا چند تایشان را برایم بگیر. دوست دارم عرق بریزند را ببینم.", o = { "12 Ghostland Pepper جمع کن.", "Ghostland Pepper را جمع کن (12)" }, p = "برداشت چطور پیش می‌رود؟", c = "شادی! این‌ها هیجان زیادی و کمی هم خجالت، به دربار می‌آورند.\nممنون فراوان! آه، و <name>... حتما دست‌هایت را بشور قبل از اینکه به چشمت بمالی--یا بدتر. من راه سخت یاد گرفتم." }
