WoWFQ[91991] = { t = "یک مأموریت کوچک", d = "وقتی گفتگوها گرم می‌شود، سخت می‌توان حرف‌ها را در مسیر سازنده نگه داشت. در چنین اوقاتی، کمی چرب‌کردن اجتماعی به کار می‌آید.\nبه Goldenmist Village برو و یک بشکه Vintner's Golden بردار. اثر سرخوشی‌آور آن ثابت شده و حسابی به کار می‌آید.", o = { "یک بشکه Vintner's Golden بردار.", "Vintner's Golden را بردار" }, p = "بشکه را پیدا کردی؟", c = "بی‌نقص! همین چیزی است که دربار سفارش داده." }
