WoWFQ[91996] = { t = "درخور یک Magister", d = "توان نبرد و مهارت جادویی مهم‌اند، البته، اما قدرت ظاهر را نمی‌شود انکار کرد. ارتشی خوش‌پوش خیلی بیشتر از ارتشی در پاره‌لباس‌ها اعتماد برمی‌انگیزد.\nخوش‌یمن است که یک شنل خوب هم دلنشین است هم کاربردی. ابریشم mana که در North Sanctum تولید می‌شود را می‌توان به شنل‌هایی بافت که ذخایر جادویی‌مان را عمیق‌تر و فشرده‌تر می‌کنند.\nلطف کن و مقداری برایمان بگیر، شود؟ کمد من به تازه‌سازی فصلی نیاز دارد.", o = { "5 Iridescent Mana Silk جمع کن و در North Sanctum به Bolt of Mana Silk Cloth بباف.", "Iridescent Mana Silk جمع شد (5)", "Bolt of Mana Silk Cloth را بردار" }, p = "حواست به mana wyrmها باشد. شنیده‌ام بعد از برداشت، عاصی می‌شوند.", c = "ابریشم mana درخششی زیبا دارد، نه؟\nMagisterها در طول میهمانی به‌طرز باشکوهی دیده خواهند شد." }
WoWFQ[91997] = { t = "نظافت نیرومند", d = "جشن‌ها به‌طرز شگفت‌انگیزی سرگرم‌کننده بوده، یعنی اشراف کمی به‌هم‌ریختگی در ملک به جا گذاشته‌اند. خدمه Lord Saltheril کار نظافت را پیش می‌برند، اما Magisterها می‌توانند دستی برسانی.\nجادو کردن چند جارو برای جارو کردن سرسرا، کار آسانی است اما تأثیرگذار.\nخبر دارم که یک arcanist در Farstrider Hold از همان ترفند استفاده می‌کند. برو چند تا از جاروهایش را بیاور تا اینجا دوباره جادو‌شان کنم.", o = { "5 Inanimate Broom را در Farstrider Hold با قدرت خاموش و جمع کن.", "Inanimate Broom را جمع کن (5)" }, p = "به‌ظاهر هر جارویی به کار می‌آید، اما بافت جادو روی جسمی که از قبل برای دریافت طلسم آماده شده آسان‌تر است.", c = "به‌زودی ملک می‌درخشد." }
