WoWFQ[92000] = { t = "هیجان را بیاور", d = "تا اینجا این مکان حسابی سرگرم‌کننده است، با وجود آن همه حرف سیاسی خشک. می‌دانم Saltheril تلاش می‌کند اشراف را به خرید اوراق جنگ بکشاند، اما واقعا به انرژی بیشتری اینجا نیاز داریم. اگر اشراف خواب‌آلود باشند، هیچ‌کس چیزی نمی‌خرد.\nاینطور بگویم. برو بعضی از رفقای من را دعوت کن. زیر پل، همان بیرون دروازه‌های Silvermoon جمع می‌شوند.\nاگر کسی بتواند هیجان به این میهمانی بیاورد، ما هستیم.", o = { "دعوت Vyrin را به 6 تن از رفقای \"تاجر\"اش نزدیک Path of Dawn برسان.", "\"تاجران\" دعوت شدند (6)" }, c = "هیجان بالاست، نوشیدنی‌ها جاری‌اند و مردم خوش می‌گذرانند!\nاین‌طور کارها را می‌بندند." }
