WoWFQ[92177] = { t = "شکار یک قهرمان", d = "باز هم ما sin'dorei شهری تحت تهاجم می‌بینیم. و باز هم، این ذهن‌های لطیف میان ما هستند که به کمک Silvermoon می‌آیند.\nبه ظاهر، رنج فانی بازتابی نیرومند از روح است. وقتی مهار و هدایت شود، رنج شکلی از جادوست که می‌توانیم برای حفاظت از این شهر بزرگ به کار بگیریم.\nچند هدف آکنده از رنج را در سراسر Azeroth پیدا کرده‌ام.\nیکی را برگزین و شکارش کن، و رنجش را در این ظرف بلوری ذخیره کن. بعد به من برگرد.", o = { "یک هدف شکار را شکار کن و ظرف بلوری را به Astalor Bloodsworn برگردان.", "هدف شکار روی جدول شکار انتخاب شد", "World Quest شکار کامل شد", "World Quest در حین شکار کامل شد", "شکار کامل شد", "Void Splinter را بردار" }, c = "تو رنج بیشتری جمع می‌کنی، من با پتانسیل این قدرت آزمایش می‌کنم." }
WoWFQ[92178] = { t = "جادوی کاربردی", d = "حین اینکه تو دنبال هدف‌ها می‌گشتی، من روی کاربردهای گوناگون رنج کار می‌کردم.\nقدرتی که این احساسات خام در خود دارند عمیق‌تر از آن است که فهمیده شود. فعلا شاید کاربردهایمان ساده به نظر برسند، اما با وقت کافی، مطمئنم کشفیاتم اهداف Silvermoon را پیش می‌برند.\nبگذار نشانت بدهم. ظرف بلوری را بگیر و پایین به من بپیوند.", o = { "Astalor را به تالارهای پایین همراهی کن و به اشیا قدرت رنج ببخش.", "پایین تالارهایش به Astalor بپیوند", "سلاح‌ها قدرت گرفتند", "سازه arcane قدرت گرفت", "Mana Wyrmها قدرت گرفتند", "Docile Mana Wyrm را بکش" }, c = "این‌همه سال، زندگی‌ام را وقف این جست‌وجوهای جادویی کرده‌ام.\nفصل بعدی چیزی خواهد بود که ارزش دیدن دارد." }
WoWFQ[92179] = { t = "شفای تاریک", d = "تا اینجا، رنج در استوار کردن نیروهایمان بی‌ارزش‌پذیر بوده است. سلاح‌ها و گولم‌هایمان به لطف این قدرت نو، هم سخت‌جان‌ترند هم مؤثرتر.\nهمچنین دارم راه‌هایی می‌سازم که رنج را به طلسم‌های نیرومندی بدل کند که ما الف‌ها را تقویت می‌کند.\nپایین به من بپیوند. نشان می‌دهم چه یافته‌ام.", o = { "Astalor را به تالارهای پایین‌تر دنبال کن و در کشفیاتش یاری‌اش کن.", "پایین تالارهایش به Astalor بپیوند", "Cleansing Saltها را آماده کن", "Crystalline Vessel را جایگذاری کن", "با Astalor رنج را روان کن" }, c = "عوارض جانبی ناخوشایند وقتی در لبه تیز کشف‌های جادویی هستیم، انتظار می‌رود." }
WoWFQ[92180] = { t = "جواهرات گران‌بها", d = "<name>...\nحین غیبت تو، کارمان را پخته‌تر کردم.\n<انگشتری جواهرنشانی را در کف دستش نشان می‌دهد.>\nنقشک‌ها و زیورهای کوچکی که رنج بلورشده در خود دارند.\nبی‌سروصدا به چند شهروند داوطلب Silvermoon هدیه داده‌ام. می‌خواهم اثر یک تمرکز مهارشده از رنج را در گذر زمان ببینم.\nجادو را چنان شکل داده‌ام که به دارنده سلامت و توان ببخشد. داوطلبانمان را پیدا کن و حالشان را بپرس.", o = { "از الف‌هایی که نقشک‌های Astalor را پذیرفته‌اند حال بپرس.", "گفتگو با Elf A", "گفتگو با Elf B", "گفتگو با Elf C", "الف‌های جواهرنشان را بررسی کن (3)" }, p = "کار من اینجا جهان را از قدرت Silvermoon خواهد ترساند.", c = "تهاجم فقط بیان قدرت است.\nتا وقتی ما شکارچی باشیم، نه شکار." }
WoWFQ[92181] = { t = "قربانی‌های معمولی باغ", d = "<name>... به یک ماجرا در شهر باید رسیدگی کنی.\nاز Knight Captain Solara خبر رسید که در Gardens of Remembrance حادثه‌ای رخ داده. خبر می‌دهد که الف‌ها به خشونت روی آورده‌اند، رنج انباشته را مجسم کرده و ساکنان را می‌ترساند.\nمی‌توانی با ظرف بلوری رنج انباشته را پس بگیری و الف‌هایی را که ذهن‌شان فروپاشیده آرام کنی.\nاین‌همه جادو بر تو سنگینی خواهد کرد، اما مطمئنم توانش را داری.", o = { "الف‌ها را نجات بده و رنج انباشته را در Gardens of Remembrance پس بگیر.", "الف‌ها از رنج نجات یافتند", "Silvermoon Resident را بکش (8)", "Blood Knight Adept را بکش (8)", "رنج انباشته پس گرفته شد (4)" }, p = "در همه تلاش‌هایم، همیشه کسانی هستند که بخواهند مانع پیشرفتم شوند.", c = "همیشه کسانی هستند که با پیشرفت مخالف‌اند، اما به هر بهایی، پژوهش‌های من در رنج برای مردم Silvermoon است." }
WoWFQ[92182] = { t = "گوسفند یا گرگ", d = "از قهرمانی‌ات در باغ شنیدم. Silvermoon بابت آرام کردن هرج‌ومرج از تو سپاسگزار است.\nو من بابت بازیابی این‌همه رنج ممنونم.\nظرف بلوری شاید مجرا باشد، اما بدن باید استوار باشد تا این‌همه قدرت را تحمل کند... مثل من، تو هم توان مقابله با سیل رنج درونت را داری، دست‌کم برای مدتی کوتاه.\nبیا، بگذار این بار را از دوشت بردارم.", o = { "پایین تالارهایش در Silvermoon City به Astalor بپیوند.", "پایین تالارهایش به Astalor بپیوند", "Cleansing Saltها را آماده کن", "Crystalline Vessel را جایگذاری کن", "به مراسم Astalor تن بده" }, c = "رنج قدرت است، و قدرت شکارچی‌گری.\nترجیح می‌دهی ما گوسفند باشیم یا گرگ؟" }
