WoWFQ[96614] = { t = "آب‌دیده در آتش", c = "می‌گویند نعمت‌های ققنوسی فراموش‌شده از هر ضربه چکش و هر خروش شعله در این آهنگری می‌تراود.\nبرای همین هر کسی که جدی به کارش باشد از همه سو به این نقطه می‌آید تا ساخته‌هایش را اینجا بپرورد. اما شاید همه این قدرت فقط خرافه است. راهی برای دودمان Sunstrider تا به ناتوانان قدرت ببخشند. باز هم، شاید هم نیست.\nخودت امتحانش کن، شود؟" }
WoWFQ[96633] = { t = "سمینار تجهیزات", d = "خوش برگشتی، <name>! همکاری‌ام با صنعتگران اینجا در Silvermoon را ادامه داده‌ام. تکنیک‌های‌شان هر روز پخته‌تر می‌شود. جادوی تجهیزات با جوهر سپیده دیگر تئوری نیست، دارد به یک هنر بدل می‌شود.\nبی‌قرارم کار مشترک‌مان را از سر بگیریم. یک تکه تجهیزات Adventurer دیگر بیار تا ببینیم این روش‌های بهبودیافته در عمل چطور جواب می‌دهند.\nهمیشه آدم‌های زیادی هستند که به دستی توانمند نیاز دارند. به‌شان کمک کن و به‌اندازه پاداش می‌گیری.", o = { "یک تکه تجهیزات مسیر Adventurer به دست بیاور، بعد نزد Vaskarn در Silvermoon بازگرد.", "یک آیتم مسیر Adventurer به دست بیاور" }, p = "اگر پیدا کردن تجهیزات Adventurer برایت سخت است، شنیده‌ام آن اردوگاه اکتشافی Amani به آن جزیره ممنوع حسابی به دست کمکی نیاز دارد. شاید حاضر باشند بابت کمکت تجهیزات بدهند.", c = "با روش‌های بهبودیافته‌ام می‌توانم این را خیلی بهتر کنم. تنها مانده، مواد جادویی است." }
WoWFQ[96635] = { t = "تمرین عملی ارتقا", d = "من و Cuzolth هنرمندی‌مان را از همیشه جلوتر برده‌ایم و می‌توانیم به تجهیزاتت قدرت بیشتری ببخشیم.\nبرای شکفتن پتانسیل کاملش، به Mistcrest نیاز داریم. از آزمون‌هایی از هر جنس کشیده می‌شوند--خطرهای بزرگ‌تر نشان‌های قوی‌تر می‌دهند، هرچند حتی Adventurer Mistcrest هم جرقه‌ای از آن قدرت را در خود دارد.\nپنجاه Adventurer Mistcrest بیار، <name>. ببینیم تجهیزاتت واقعا از پس چه برمی‌آید.", o = { "50 Adventurer Mistcrest را با کشتن موجودات یگانه، کامل کردن فعالیت‌های جهانی یا غارت گنج‌ها به دست بیاور. با Cuzolth صحبت کن تا یک آیتم مسیر Adventurer را با آن نشان‌ها ارتقا دهی، بعد نزد Vaskarn در Silvermoon بازگرد.", "آیتم مسیر Adventurer را ارتقا بده", "آیتم مسیر Adventurer را بار دوم ارتقا بده" }, p = "اگر Adventurer Mistcrest گیر نیامد، چشمت به گوشه‌های پنهان آن جزیره ممنوع که Amaniها فعلا کاوشش می‌کنند باشد. تلاش‌شان شاید دقیقا همان Mistcrestهایی را بدهد که می‌خواهیم.", c = "شاهکار! دقیقا همان چیزی که امیدش را داشتم.\nبا هر قدم نیرومندتر می‌شوی... که البته نگرانی اصلی من است. پژوهش‌هایم هم به‌طور طبیعی در همین مسیر پیش می‌رود. البته." }
WoWFQ[96637] = { t = "هم‌اندیشی Veteran", d = "خیلی قدرت دیگر هم در راه است!\nارتقاها با توان مقیاس می‌گیرند. آیتم‌های باکیفیت‌تر به اوج قدرت بالاتری می‌رسند. برای این قدم، به تجهیزات Veteran با چند Veteran Mistcrest نیاز دارم.\nوقتی آوردی، من و Cuzolth می‌توانیم بهبودها را ادامه دهیم.", o = { "یک تکه تجهیزات مسیر Veteran و 15 Veteran Mistcrest به دست بیاور. با Cuzolth صحبت کن تا آیتم مسیر Veteran را با آن نشان‌ها ارتقا دهی، بعد نزد Vaskarn در Silvermoon بازگرد.", "یک آیتم مسیر Veteran به دست بیاور", "آیتم مسیر Veteran را ارتقا بده" }, p = "کامل کردن یک دانژان Heroic یا یک فعالیت هفتگی چالشی با اردوگاه اکتشافی Amani باید تجهیزات Veteran مورد نظرت را بدهد. شرکت در تلاش‌هایشان هم Veteran Mistcrestها را برایمان می‌آورد!", c = "خوب بود، این کار را ذاتی داری!\nفرآیند همیشه همین است: آیتم را با نشان‌های مناسبش برایمان بیاور، و Cuzolth ارتقا را انجام می‌دهد." }
WoWFQ[96649] = { t = "اوج Mistcrest", d = "نشان‌ها شکل ثابتی ندارند. می‌توانی بین سطوح‌شان تبدیلشان کنی.\nاگر نشان‌هایی داری که از توان تجهیزات فعلی‌ات فراترند، می‌توانم به سطح‌های پایین‌تر پالایششان کنم. و وقتی تجهیزاتت پیش رفت، فرآیند را برعکس می‌کنیم و نشان‌های کوچک‌تر را به بزرگ بدل می‌کنیم.\nبا تمرینی ساده شروع کنیم. آن Veteran Mistcrestها را بیار و به Adventurer Mistcrest تبدیل‌شان می‌کنم.", o = { "10 Veteran Mistcrest را به Vaskarn در Silvermoon برسان، سپس با آن‌ها Bundle of Adventurer Mistcrest را معاوضه کن.", "به Bundle of Adventurer Mistcrest تبدیل کن" }, p = "اگر آن Veteran Mistcrestها را گم کردی، از موجودات نیرومند نزدیک Amani Expedition بیشتر پیدا می‌کنی. شنیده‌ام تنوع زیادی دارند!", c = "شاهکار بود!\nبه یاد داشته باش: تبدیل به سطح بالاتر فقط وقتی ممکن است که نشان از کار افتاده باشد، و بهایی سنگین دارد.\nبابت کمکت ممنونم، <name>." }
WoWFQ[96703] = { t = "کهنه‌کاران Great Dark", d = "وقتی Hal'hadar حمله کرد، سریع از تاریخچه‌شان با Army of the Light باخبر شدیم.\nCommander Tala'saan از این etherealها برایمان اطلاعات می‌دهد. سربازانش آماده‌اند به راه ما بپیوندند.\nاز تخصص‌شان برای برپا کردن اردوی پیشرو مأموریت‌مان خواسته‌ام.\nدر آماده‌سازی‌هایشان یاری‌شان کن و به فرمانده خبر بده به‌زودی بسیج می‌شویم.", o = { "Commander Tala'saan و Lightforgedها را برای اردوگاه Maella به خدمت بگیر.", "در Northeast Ramparts به Lightforgedها بپیوند", "با Commander Tala'saan صحبت کن", "با Baraat the Longshot صحبت کن", "با Captain Fareeya صحبت کن", "با Archmage Y'mera صحبت کن", "Lightveil Tether حین Stealth آزمایش شد" }, p = "اعتراف می‌کنم، بعد از ماجرای Voidspire، هنوز در اعتماد به متحدانی این‌همه... دلبسته Light محتاطم.\nاما با کنار گذاشتن سلیقه‌های شخصی، نمی‌توانم تخصص‌شان در جنگیدن با Void و Hal'hadar را انکار کنم.", c = "Tala'saan قبلا هشدار داده بود که فقط تعداد کمی Lightforged می‌توانند بیایند. حمله به Voidspire نیروهایشان را به‌شدت تحلیل برده بود.\nخیلی زخمی، خیلی بیشتر کشته یا مفقود.\nهر پشتیبانی که از Army of the Light فراهم کنیم در این عملیات نقش بزرگی خواهد داشت." }
WoWFQ[96725] = { t = "جرقه‌های جنگ: Val", d = "دنیای مرموز Val به روی ما باز شده و انبوهی از موجودات تازه در آن حاضرند.\nبرو و ببین چه می‌توانی درباره‌شان بفهمی.", o = { "100 Otherworldly Spark of War را در Val، در حالت War Mode، جمع کن.", "Otherworldly Spark of War را جمع کن (100)" }, p = "هنوز کار مانده.", c = "این چند پاسخ به دست داد. ممنون فراوان." }
WoWFQ[96726] = { t = "جرقه‌های جنگ: Naigtal", d = "دنیای مرموز Naigtal به روی ما باز شده و انبوهی از موجودات تازه در آن حاضرند.\nبرو و ببین درباره این دنیا و کاری که etherealها در دست دارند چه می‌فهمی.", o = { "100 Otherworldly Spark of War را در Naigtal، در حالت War Mode، جمع کن.", "Otherworldly Spark of War را جمع کن (100)" }, p = "هنوز کار مانده.", c = "این چند پاسخ به دست داد. ممنون فراوان." }
WoWFQ[96746] = { t = "باران هاگ: Rotmire", d = "کمک! آخر Harandar! آخر دنیا!\nSpore Storm دارد برای Grudge Pit چیز تازه‌ای می‌سازد، اما خیلی زیاد. خیلی زیاد! نمی‌شود مهارش کرد. آزاد می‌شود! گودال را نابود می‌کند. همه ما را نابود می‌کند!\nباید به Sporefall بروی و پیش از آنکه کنترل را از دست بدهند، Rotmire را نابود کنی!\nبرای Harandar! برای Azeroth! برای Grudge Pit!", o = { "وارد Sporefall شو و Rotmire را مغلوب کن.", "Rotmire را بکش" }, c = "همه ما را نجات دادی. Fungaria! Harandar! دنیا! Grudge Pit!\nاما دنیا، بیشتر از همه دنیا." }
WoWFQ[96808] = { t = "جرقه‌های جنگ: The Coiled Isle", d = "در Coiled Isle خطری ناشناخته کمین کرده است.\nبرو و اوضاع را روشن کن!", o = { "100 Spark of War را در Coiled Isle، در حالت War Mode، جمع کن.", "Spark of War را جمع کن (100)" }, p = "خب، برو دیگر!", c = "ممنون که اوضاع را روشن کردی." }
WoWFQ[96910] = { t = "بشکه قبض می‌گساری", c = "به میخانه‌های سراسر ناحیه‌های Midnight کمک مالی کن تا قبض‌ها پرداخت شود!" }
WoWFQ[96911] = { t = "بشکه قبض می‌گساری", c = "به میخانه‌های سراسر ناحیه‌های Midnight کمک مالی کن تا قبض‌ها پرداخت شود!" }
WoWFQ[97215] = { t = "ضربه‌ای دوم", d = "ضربه بزرگی به دشمنانمان زدیم. با این حال، همچنان حمله می‌کنند.\nDecimus و riftwardenهای من دنیای دیگری را هدف گرفته‌اند که از آن حمله‌هایشان را به راه می‌اندازند.\nبخش عمده نیروهایمان موقتا به Voidstorm عقب نشسته‌اند تا حمله‌مان به این دنیای دوم را آغاز کنیم.\nگروه ضربتی‌مان در Howling Ridge منتظر ماست.", o = { "در Voidstorm به Riftblade Maella بپیوند." }, c = "دشمنانمان هر یک سنگر خودشان را در دنیایی متفاوت برپا کرده‌اند و ما را وادار به تقسیم توجه می‌کنند.\nاگر می‌خواهیم واقعا نیروهایشان را در هم بشکنیم، باید به هر دو ضربه بزنیم و نقاط ورودمان را استوار کنیم.\nآماده شکستن شکافی دیگر هستی؟" }
WoWFQ[97321] = { t = "غنیمت‌های خزنده", d = "خبر خوب و بد دارم.\nبدش اینکه همه آن کنجکاوی‌هایی که با هم از خاک بیرون کشیدیم؟ آب شدند.\nخبر خوب؟ چند زهر خیلی جالب تازه برای کار پیدا کرده‌ام.\nاما بگذار توضیح بدهم چه شد...", o = { "به قصه Valeera گوش کن.", "به قصه Valeera گوش کن", "Slithersoul Spoils را جمع کن (6)", "Sizzling Venom را جمع کن (6)", "Venomfall Font را بررسی کن", "نمونه از Venomfall Font بردار" }, p = "نظرت چیست؟", c = "اشتباهی تازه‌کارانه بود، اما بیهوده هم نبود." }
WoWFQ[97454] = { t = "تازه‌سازی فصلی: Midnight", d = "از باز شدن Coiling Isles، ماجراهای دلوه‌ها دوباره جالب شده‌اند.\nببین میزبانان عزیزمان چیزی برای ما که واقعا گردن‌مان در خطر است کنار گذاشته‌اند یا نه، و Delver's Guide را برای تازه‌ها بررسی کن.\nیادآوری سریع به کسی آسیب نزده است.", o = { "Delver's Guide را مرور کن و آذوقه فصلی از Naleidea Rivergleam و Telemancer Astrandis بخر.", "Delver's Guide مرور شد", "Delver's Starter Kit از Naleidea خریداری شد", "Delver's Cosmetic Surprise Bag از Astrandis خریداری شد" }, p = "آماده‌ای؟", c = "عالی، هرچند از آخرین دیدارمان... تحولاتی رخ داده است." }
WoWFQ[97622] = { t = "میهمانی‌ای به یادماندنی", d = "به دیدار Saltheril می‌روی؟ و این را که پوشیده‌ای... این؟ اجازه بده لحظه‌ای در دستمال‌بندم بخندم.\n<Caeris پشت دستمال‌بندش به‌آرامی و مؤدبانه می‌خندد.>\nخب، بگذار حرفه‌ای باشم. رسما دعوت شده‌ای در میهمانی Saltheril شرکت کنی.\nخودت را شرمنده نکن، <name>. بهترین‌های Silvermoon تماشا می‌کنند.", o = { "در Saltheril's Soiree شرکت کن و سنگ‌نوشته‌های Eversong را نیرومند کن.", "\"Fortify the Runestones\" را در Saltheril's Soiree کامل کن" }, c = "نصف انتظار داشتم اشک‌آلود به خانه بدوی! امیدوارم زمان خیره‌کننده‌ای داشته باشی." }
WoWFQ[98012] = { t = "Nebulous Voidcoreها: Veteran Mistcrest", p = "می‌توانم با Catalyst یک Nebulous Voidcore دیگر برایت آماده کنم، اما برای سوخت فرآیند به مواد خام نیاز داریم.\nآن نشان‌هایی که برای نیرومند کردن تجهیزات به کار می‌بری انرژی نهفته‌ای دارند که در برابر Catalyst دقیقا به شکلی درست واکنش نشان می‌دهد.\nجمع کن: Veteran Mistcrest (100)", c = "یک voidweaving موفق دیگر! مطمئنم از این Nebulous Voidcore استفاده خوبی می‌کنی، <name>." }
WoWFQ[98015] = { t = "Nebulous Voidcoreها: Voidlight Marl", p = "می‌توانم با Catalyst یک Nebulous Voidcore دیگر برایت آماده کنم، اما برای سوخت فرآیند به مواد خام نیاز داریم.\nVoidlight Marl ماده‌ای ایده‌آل برای این کار است. ویژگی‌های رنگین‌کمانی‌اش فرآیند جدا کردن انرژی void از قدرت آشوبناک Catalyst را به‌طرز چشمگیری ساده می‌کند.\nجمع کن: Voidlight Marl (2000)", c = "یک voidweaving موفق دیگر! مطمئنم از این Nebulous Voidcore استفاده خوبی می‌کنی، <name>." }
WoWFQ[98016] = { t = "Nebulous Voidcoreها: طلا", p = "می‌توانم از قدرت انباشته Catalyst یک Nebulous Voidcore دیگر برایت ببافم، اما برای سوخت فرآیند به مواد خام نیاز داریم.\nراهی یافته‌ام تا ویژگی رسانایی طلا را برای این تبدیل به کار بگیرم. ارزان نیست، اما جواب می‌دهد.\nپول لازم: 5,000 (1)", c = "یک voidweaving موفق دیگر! مطمئنم از این Nebulous Voidcore استفاده خوبی می‌کنی، <name>." }
WoWFQ[98379] = { t = "اعماق باستانی، زهر باستانی", d = "در جریان پژوهش‌های پیشین‌ام، ماجراجویی ذره‌ای عجیب از زهر نخستین را از اعماق Atal'Utek برایم آورد. توانش به نظر با نفوذ طولانی Ula'tek بر آن مکان نفرین‌شده تقویت شده است، و به نظرم شاید بتوانیم آن را به مقاصد خودمان بکشانیم.\nلازم است بیشتر جمع کنی تا بتوانیم در مقیاس کافی آن را در معرض انرژی‌های Catalyst قرار دهیم. باید به Vaults of Atal'Utek بازگردی یا حتی عمیق‌تر به Venomous Abyss بروی و سراغ موجودات نیرومند بروی.", o = { "3 Primordial Venom Mote از Ancient Foeها در Vaults of Atal'Utek یا از اربابان دان Raid در Venomous Abyss با درجه Raid Finder یا بالاتر جمع کن تا به Orin در پژوهش Catalyst کمک کنی.\nCatalyst دسترسی به Ascendant Venomstoneها را می‌دهد؛ برای ارتقای سلاح‌ها، trinketها و گردنبندهای فصل 2 در Midnight.", "Primordial Venom Mote را جمع کن (3)" }, p = "خوشحالم که سالم از آن چاله زهرآلود برگشتی. Primordial Venom Moteها را داری؟", c = "خوب است. با قدرت Catalyst و کمی از Void، به باورم می‌توانم با این زهر نخستین به تو توان استخراج قدرت از دشمنانت را به شکل Ascendant Venomstone ببخشم و در تجهیزاتت تزریق کنم. کار روی جزئیاتش زمان می‌برد، پس به‌زودی سر بزن." }
WoWFQ[98832] = { t = "خطرهای ناگفته و سختی‌های بی‌شمار", d = "نمی‌شود گفت در مقبره‌ای چندصدساله چه تهدیدهایی به پا می‌شود.\nمراقب باش و منتظر هر چیز باش.", o = { "آماده‌سازی‌های لازم را انجام بده، بعد وارد Labyrinth of Kindo'jan شو.", "وارد Labyrinth شو", "Chamber of Rites پاک شد", "دنبال Valeera برو" } }
WoWFQ[98833] = { t = "یاد من انداختی اون پرنده رو", d = "به نظر می‌رسه Akil'zon با این ترول دیگه کارش تموم نشده--با تو هم نه.\nحضوری شرور این مقبره‌های مقدس رو کثیف کرده، و ارواح اینجا؟ اصلا خوششون نمیاد. می‌تونم التماس‌شون کنم که این در رو باز کنن و رد شی، اثبات لایق بودنت با خودت.\n<Kinduru بالی دراز می‌کنه و به نکرومانسر مُرده Vilebranch اشاره می‌کنه.>\nامیدوارم کار ساختن با این یکی کافی باشه.", o = { "راه به Reliquary رو باز کن تا دور Labyrinth رو ادامه بدی.", "راه رو باز کن" }, p = "وقت رو تلف نکنیم.", c = "برای ارواح این جا داریم جون‌مون رو می‌ذاریم، و اونا چی می‌فرستن؟\nیه پرنده حرف‌زن. عالی." }
WoWFQ[98834] = { t = "راه پیش‌رو...", d = "خب، اون پرنده یه جایی درست می‌گفت. ارواح این جا رو در دست دارن، پس اگه می‌خوایم کاری از دستمون بربیاد، به کمکشون نیاز داریم.\nببینیم تو اتاق بعدی چی خبره. امیدوارم بتونیم قانع‌شون کنم که قبل از دیر شدن، کاری با Vilebranchها بسازیم.", o = { "دور Labyrinth رو کامل کن.", "Reliquary پاک شد", "مسیر انتخاب شد", "Halazzi's Lair پاک شد", "با Kinduru صحبت کن" } }
WoWFQ[98951] = { t = "آشیانه Akil'zon", d = "احمق‌های بی‌ادب! جرئت می‌کنند این مقدس‌گاه باستانی رو آلوده کنن. خشم loaها از دل روانم می‌پیچه...\nتو، تازه‌وارد. چرا به این مکان مقدس داخل می‌شی؟ اگه دنبال گنجه‌ای، خوب گوش کن. اگه شرورانه‌ای که این Sacrosanctum رو آزار می‌ده رو برانی، پاداش گزافی می‌گیری.\nخب... اول به آشیانه Akil'zon برو. نشونمون بده که لایق قدم زدن روی این زمین‌های مقدسی.", o = { "آشیانه Akil'zon رو پیدا کن و از مهاجمان پاکش کن.", "آشیانه Akil'zon رو پیدا کن و در Tier 8+ از مهاجمان پاکش کن" } }
WoWFQ[98961] = { t = "پناهگاه Jan'alai", d = "باز هم صدا loaها رو جواب دادی... کم تازه‌واردی این کارو می‌کنه.\nبا تلاش تو، تقدس مقدس‌گاه داره برمی‌گرده، اما کارمون تموم نشده. به قلمرو Jan'alai برو و کرم‌هایی که آلوده‌ش کردن رو بیرون کن.", o = { "پناهگاه Jan'alai رو پیدا کن و از مهاجمان پاکش کن.", "پناهگاه Jan'alai رو پیدا کن و در Tier 8+ از مهاجمان پاکش کن" } }
WoWFQ[98962] = { t = "برج‌های غار", d = "باز هم برگشتی. شاید بیشتر از طمع تویی...\nخشم loaها هنوز تو این تالارها طنین‌اندازه. برج‌های غار رو امن کن و بذار هیچ متجاوزی نمونه.", o = { "برج‌های غار رو پیدا کن و از مهاجمان پاکش کن.", "برج‌های غار رو پیدا کن و در Tier 8+ از مهاجمان پاکش کن" } }
WoWFQ[98963] = { t = "لانه Halazzi", d = "پس برمی‌گردی، تازه‌وارد؟ خشم loaها هنوز فروکش نکرده، پس شاید هنوز به دردت بخوریم.\nبه لانه Halazzi برو و با عجله کار این آفت‌ها رو بساز.", o = { "لانه Halazzi رو پیدا کن و از مهاجمان پاکش کن.", "لانه Halazzi رو پیدا کن و در Tier 8+ از مهاجمان پاکش کن" } }
